window.WPS = window.WPS || {};
WPS.RONJUTSU = [
  // ===== 日本史 =====
  { id: 'j01', s: 'jh', lv: 1, topic: '班田収授法', q: '律令制のもとで、班田収授法は何を目的としていたか。', a: '【戸籍】にもとづいて6歳以上の男女に【口分田】を与え、死後に返させることで、【租】などの税を確実に集めることを目的とした。' },
  { id: 'j02', s: 'jh', lv: 1, topic: '墾田永年私財法', q: '墾田永年私財法（743年）は、土地制度にどのような変化をもたらしたか。', a: '開墾した土地の【私有】を永久に認めたため、貴族や寺社が開墾を進めて【荘園】が広がり、【公地公民】の原則がくずれていった。' },
  { id: 'j03', s: 'jh', lv: 1, topic: '摂関政治', q: '藤原氏は、どのようにして摂関政治の実権を手に入れたか。', a: '娘を天皇の【后】にして、生まれた子を天皇に立てた。天皇の【外戚】として【摂政】や【関白】の地位につき、政治の実権をにぎった。' },
  { id: 'j04', s: 'jh', lv: 1, topic: '院政', q: '院政とはどのような政治か。始めた人物とともに説明せよ。', a: '天皇が位をゆずって【上皇】となったあとも、【院庁】を中心に政治を行うしくみで、1086年に【白河上皇】が始めた。' },
  { id: 'j05', s: 'jh', lv: 1, topic: '御恩と奉公', q: '鎌倉幕府の将軍と御家人の関係を説明せよ。', a: '将軍は御家人の領地を保障したり新しい領地を与えたりする【御恩】を与え、御家人は戦いや警備で【奉公】した。【土地】を仲立ちとしたこの主従関係を【封建制度】という。' },
  { id: 'j06', s: 'jh', lv: 2, topic: '元寇', q: '元寇（蒙古襲来）は、鎌倉幕府の衰退にどうつながったか。', a: '防衛戦では新しい領地が得られず、御家人に十分な【恩賞】を与えられなかった。【分割相続】で困窮していた御家人を救うため【徳政令】を出したが効果は小さく、幕府は信頼を失った。' },
  { id: 'j07', s: 'jh', lv: 2, topic: '日明貿易', q: '足利義満が始めた日明貿易で、勘合が用いられた理由を述べよ。', a: '正式な貿易船と【倭寇】を区別するため、明が与えた【勘合】という合い札を用いた。この貿易は【朝貢】の形式で行われた。' },
  { id: 'j08', s: 'jh', lv: 1, topic: '太閤検地', q: '太閤検地は、社会にどのような変化をもたらしたか。', a: '全国の土地を統一した基準で調べ、生産力を【石高】で表した。耕作者を【検地帳】に登録して年貢の負担者とし、【荘園】のしくみは完全にくずれた。' },
  { id: 'j09', s: 'jh', lv: 2, topic: '刀狩', q: '豊臣秀吉の刀狩の目的と結果を述べよ。', a: '農民から武器を取り上げて【一揆】を防ぎ、農業に専念させた。太閤検地とあわせて、武士と農民の身分を分ける【兵農分離】が進んだ。' },
  { id: 'j10', s: 'jh', lv: 1, topic: '参勤交代', q: '参勤交代は、大名や社会にどのような影響を与えたか。', a: '大名は1年おきに【江戸】と領地を行き来し、妻子は江戸に住まわされた。多額の【出費】で大名の力が弱まる一方、【街道】や宿場町が発達した。' },
  { id: 'j11', s: 'jh', lv: 2, topic: '鎖国', q: '江戸幕府が貿易の相手を限った理由と、その相手を述べよ。', a: '【キリスト教】の広まりを防ぎ、貿易の利益を幕府が独占するため、長崎で【オランダ】と【中国】に限って貿易を認めた。' },
  { id: 'j12', s: 'jh', lv: 2, topic: '享保の改革', q: '徳川吉宗の享保の改革で行われた政策を述べよ。', a: '大名に米を納めさせる【上げ米】を行い、【新田開発】を進めて年貢を増やした。また【公事方御定書】で裁判の基準を定めた。' },
  { id: 'j13', s: 'jh', lv: 2, topic: '田沼の政治', q: '田沼意次の政治の特徴を述べよ。', a: '商人の経済力を利用し、【株仲間】の結成を認めて営業税を取り、【長崎貿易】を拡大した。一方で【わいろ】が横行したと批判された。' },
  { id: 'j14', s: 'jh', lv: 1, topic: '地租改正', q: '地租改正の内容と目的を述べよ。', a: '土地の所有者に【地券】を発行し、【地価】の3%を【現金】で納めさせた。収穫に左右されない、安定した税収を得ることが目的だった。' },
  { id: 'j15', s: 'jh', lv: 2, topic: '自由民権運動', q: '自由民権運動はどのように始まり、何を求めたか。', a: '板垣退助らが【民撰議院設立建白書】を提出して始まり、【国会】の開設や憲法の制定を求めた。政府は1881年に【国会開設の勅諭】を出した。' },
  { id: 'j16', s: 'jh', lv: 2, topic: '条約改正', q: '不平等条約の改正はどのように進んだか。', a: '1894年に【陸奥宗光】が【領事裁判権】の撤廃に成功し、1911年に【小村寿太郎】が【関税自主権】の回復を実現した。' },
  { id: 'j17', s: 'jh', lv: 3, topic: '三国干渉', q: '日清戦争後の三国干渉は、日本にどのような影響を与えたか。', a: '【下関条約】で得た【遼東半島】を、ロシア・ドイツ・フランスの勧告で清に返した。国民のあいだに【ロシア】への反感が高まり、「臥薪嘗胆」を合言葉に【軍備拡張】が進んだ。' },
  { id: 'j18', s: 'jh', lv: 2, topic: '普通選挙法', q: '1925年の普通選挙法と治安維持法は、どのような関係にあるか。', a: '普通選挙法で【満25歳以上の男子】に選挙権が与えられた。同じ年に【治安維持法】を定め、選挙権の拡大で勢いづくおそれのある【共産主義】などの運動を取り締まった。' },
  { id: 'j19', s: 'jh', lv: 3, topic: '満州事変', q: '昭和恐慌は、満州事変にどうつながったか。', a: '【世界恐慌】の影響で農村が深刻な不況におちいり、政党政治への不信が高まった。軍部は【満州】に活路を求め、1931年に【柳条湖事件】を起こして満州事変を始めた。' },
  { id: 'j20', s: 'jh', lv: 1, topic: '農地改革', q: '戦後の農地改革の内容と結果を述べよ。', a: '政府が【地主】の土地を買い上げて【小作人】に安く売り渡し、多くの【自作農】が生まれた。' },
  { id: 'j21', s: 'jh', lv: 2, topic: '高度経済成長', q: '高度経済成長期には、どのような社会問題が生じたか。', a: '工業化が急速に進んだ結果、【公害】が各地で発生し、【四大公害】訴訟が起こった。政府は1967年に【公害対策基本法】を定めた。' },
  { id: 'j22', s: 'jh', lv: 3, topic: '鎌倉新仏教', q: '鎌倉時代に新しい仏教が広まった理由を述べよ。', a: '戦乱やききんで不安が高まる中、【念仏】や【題目】を唱えるなど、わかりやすく実践しやすい教えが示されたため、【武士】や【庶民】に広まった。' },
  { id: 'j23', s: 'jh', lv: 3, topic: '応仁の乱', q: '応仁の乱は、戦国時代の始まりにどうつながったか。', a: '【将軍】のあとつぎ争いに有力【守護大名】の対立が結びついて11年続き、幕府の権威が衰えた。その結果、実力で領国を支配する【戦国大名】が各地に現れた（【下剋上】）。' },
  { id: 'j24', s: 'jh', lv: 3, topic: '天保の改革', q: '水野忠邦の天保の改革が失敗した理由を述べよ。', a: '【株仲間】を解散させたが物価は下がらず、かえって流通が混乱した。江戸・大坂周辺を幕府領にしようとした【上知令】も大名や旗本の反対で撤回され、忠邦は【失脚】した。' },
  // ===== 世界史 =====
  { id: 'w01', s: 'wh', lv: 1, topic: '大運河', q: '隋が建設した大運河は、中国の経済にどのような役割を果たしたか。', a: '【華北】と【江南】を結び、江南でとれた【穀物】を北方の都へ大量に運んだ。豊かな南方の【経済力】が王朝の政治と軍事を支えた。' },
  { id: 'w02', s: 'wh', lv: 1, topic: 'ローマの平和', q: '「ローマの平和」とよばれる時代の特徴を述べよ。', a: '【アウグストゥス】が帝政を始めてから約200年間、地中海世界が政治的に安定した（【パクス=ロマーナ】）。【道路網】の整備などで交易が栄えた。' },
  { id: 'w03', s: 'wh', lv: 1, topic: '十字軍', q: '十字軍の遠征は、ヨーロッパ社会にどのような影響を与えたか。', a: '遠征の失敗で【教皇】の権威が低下し、多くの【諸侯】や騎士が没落した。一方で【東方貿易】がさかんになり、イタリアの諸都市が栄えた。' },
  { id: 'w04', s: 'wh', lv: 2, topic: 'ルネサンス', q: 'ルネサンスがイタリアで始まった理由を述べよ。', a: '東方貿易で栄えた都市に富が集まり、【メディチ家】などの有力者が芸術を保護した。また古代【ギリシア・ローマ】の文化遺産が身近にあり、【ビザンツ帝国】から学者も流入した。' },
  { id: 'w05', s: 'wh', lv: 1, topic: '宗教改革', q: 'ルターが宗教改革を始めたきっかけと、その主張を述べよ。', a: '教皇による【贖宥状】の販売を批判し、1517年に【九十五か条の論題】を発表した。人は【信仰】によってのみ救われ、【聖書】だけが信仰のよりどころだと説いた。' },
  { id: 'w06', s: 'wh', lv: 2, topic: '大航海時代', q: '大航海時代は、ヨーロッパ経済にどのような影響を与えたか。', a: '新航路の開拓で、交易の中心が地中海から【大西洋】沿岸に移った（【商業革命】）。またアメリカ大陸から大量の【銀】が流入し、物価が大きく上がった（【価格革命】）。' },
  { id: 'w07', s: 'wh', lv: 2, topic: '名誉革命', q: '名誉革命の結果、イギリスの政治はどう変わったか。', a: '議会が新しい国王を迎え、【権利の章典】で国王の権力を制限した。これにより【議会】が政治の中心となる【立憲君主制】が確立した。' },
  { id: 'w08', s: 'wh', lv: 1, topic: '産業革命', q: 'イギリスで最初に産業革命が起こった理由を述べよ。', a: '植民地による広い【市場】と原料があったこと、【囲い込み】で生まれた労働力があったこと、【石炭】や鉄などの資源が豊かだったことがあげられる。' },
  { id: 'w09', s: 'wh', lv: 2, topic: 'アメリカ独立革命', q: 'アメリカ独立革命の原因を述べよ。', a: '七年戦争後、財政難のイギリスが【印紙法】などで植民地に課税した。植民地側は「【代表なくして課税なし】」と反発し、1776年に【独立宣言】を発表した。' },
  { id: 'w10', s: 'wh', lv: 1, topic: 'フランス革命', q: 'フランス革命が起こった社会的背景を述べよ。', a: '聖職者の【第一身分】と貴族の【第二身分】は免税などの特権をもち、人口の大部分をしめる【第三身分】が重い負担を負っていた。この【旧体制】への不満が革命につながった。' },
  { id: 'w11', s: 'wh', lv: 2, topic: 'ナポレオン', q: 'ナポレオンの支配は、ヨーロッパにどのような影響を与えたか。', a: '【ナポレオン法典】で法の下の平等など革命の理念を広めた。一方、征服された地域では【ナショナリズム】が高まり、各地で抵抗が起こった。' },
  { id: 'w12', s: 'wh', lv: 3, topic: 'ウィーン体制', q: 'ウィーン体制の基本原則と、崩壊のきっかけを述べよ。', a: 'フランス革命前の王朝と秩序を回復する【正統主義】と、大国の【勢力均衡】を原則とした。しかし【自由主義】やナショナリズムの運動が広がり、1848年の【二月革命】などで崩壊した。' },
  { id: 'w13', s: 'wh', lv: 2, topic: 'アヘン戦争', q: 'アヘン戦争の原因と結果を述べよ。', a: 'イギリスは【茶】の輸入で生じた赤字を補うため、インド産の【アヘン】を清に密輸した。清が取り締まると戦争になり、敗れた清は【南京条約】で香港を割譲し、5港を開いた。' },
  { id: 'w14', s: 'wh', lv: 3, topic: '辛亥革命', q: '辛亥革命は、どのような経過で清朝を倒したか。', a: '1911年に【武昌】で軍隊が蜂起すると各省が独立を宣言し、1912年に【孫文】を臨時大総統とする【中華民国】が成立した。清の実力者【袁世凱】が皇帝を退位させ、清は滅んだ。' },
  { id: 'w15', s: 'wh', lv: 1, topic: '第一次世界大戦', q: '第一次世界大戦は、どのように始まったか。', a: '1914年、オーストリアの帝位継承者夫妻が【サライェヴォ】で暗殺された。これをきっかけに、【三国同盟】側と【三国協商】側の対立が戦争に発展した。' },
  { id: 'w16', s: 'wh', lv: 2, topic: 'ヴェルサイユ条約', q: 'ヴェルサイユ条約は、ドイツにどのような影響を与えたか。', a: 'ドイツはすべての植民地を失い、巨額の【賠償金】と【軍備制限】を課された。国民の不満は高まり、のちに【ナチス】が台頭する一因となった。' },
  { id: 'w17', s: 'wh', lv: 1, topic: 'ニューディール', q: '世界恐慌に対して、アメリカはどのような政策をとったか。', a: '【フランクリン=ローズヴェルト】大統領が【ニューディール】政策を行った。【TVA】などの公共事業で失業者を雇うなど、政府が経済に積極的に関わった。' },
  { id: 'w18', s: 'wh', lv: 2, topic: 'ブロック経済', q: '世界恐慌後のブロック経済は、国際関係にどう影響したか。', a: 'イギリスやフランスは本国と植民地で【ブロック経済】をつくり、外国製品に高い【関税】をかけた。植民地の少ないドイツ・イタリア・日本は対外進出を強め、【第二次世界大戦】の一因となった。' },
  { id: 'w19', s: 'wh', lv: 1, topic: '冷戦', q: '冷戦とはどのような対立か。', a: '第二次世界大戦後の、【アメリカ】を中心とする資本主義陣営と、【ソ連】を中心とする社会主義陣営の対立である。両国が【直接の戦争】をしなかったため冷戦とよばれる。' },
  { id: 'w20', s: 'wh', lv: 3, topic: 'キューバ危機', q: 'キューバ危機の経過と、その後の米ソ関係を述べよ。', a: '1962年、ソ連が【キューバ】に【ミサイル】基地を建設し、核戦争の危機が高まった。ソ連の撤去で回避され、その後米ソ間に【ホットライン】が設けられて【緊張緩和】が進んだ。' },
  { id: 'w21', s: 'wh', lv: 2, topic: 'アッバース朝', q: 'アッバース朝は、ウマイヤ朝とどのような点で異なるか。', a: 'ウマイヤ朝では【アラブ人】が特権をもったが、アッバース朝では【ムスリム】であれば民族に関係なく平等とされ、改宗した非アラブ人も【ジズヤ】（人頭税）を免除された。' },
  { id: 'w22', s: 'wh', lv: 2, topic: 'モンゴル帝国', q: 'モンゴル帝国の成立は、東西の交流にどのような影響を与えたか。', a: 'ユーラシアの広い範囲が一つの勢力のもとにまとまり、【駅伝制】（ジャムチ）が整備されて、陸路と【海路】の交易がさかんになった。【マルコ=ポーロ】などが東方を訪れた。' },
  { id: 'w23', s: 'wh', lv: 3, topic: '銀の流入', q: '16世紀以降、中国に大量の銀が流入した理由と影響を述べよ。', a: '【日本】や【アメリカ大陸】で産出された銀が、生糸や陶磁器の代価として中国に流れ込んだ。その結果、税を銀で一括して納める【一条鞭法】が実施された。' },
  { id: 'w24', s: 'wh', lv: 3, topic: 'ソ連解体', q: 'ソ連が解体に向かった過程を述べよ。', a: '【ゴルバチョフ】が【ペレストロイカ】と情報公開（【グラスノスチ】）を進めたが経済は改善せず、東欧では民主化が進んだ。1991年に各共和国が独立し、ソ連は解体した。' },
  // ===== 追加分(自動) =====
  {"id": "jhx1", "s": "jh", "lv": 1, "topic": "旧石器時代", "q": "岩宿遺跡の発見は、日本の歴史研究にとってどのような意義をもったか説明せよ。", "a": "【相沢忠洋】が群馬県の【岩宿】で【関東ローム層】から【打製石器】を発見し、それまで存在しないと考えられていた日本の旧石器時代の存在が明らかになった。"},
  {"id": "jhx2", "s": "jh", "lv": 1, "topic": "縄文文化の成立", "q": "縄文文化が成立した背景には、どのような自然環境の変化があったか説明せよ。", "a": "氷期が終わって気候が温暖化し、海面が上昇して【日本列島】が形成された。中小動物をとらえるために【弓矢】が使われ、木の実を煮るために【縄文土器】が作られるようになった。"},
  {"id": "jhx3", "s": "jh", "lv": 1, "topic": "貝塚", "q": "縄文時代の貝塚からは、当時のどのようなことがわかるか説明せよ。", "a": "貝塚は当時の【ごみ捨て場】で、貝殻や獣・魚の骨、土器などから人々の【食生活】や暮らしの様子がわかる。人骨が【埋葬】されている例もあり、モースが調査した【大森貝塚】が知られる。"},
  {"id": "jhx4", "s": "jh", "lv": 2, "topic": "縄文時代の信仰", "q": "縄文時代の人々の信仰や風習を、遺物・埋葬法にふれながら説明せよ。", "a": "自然物に霊威を認める【アニミズム】が広まり、女性をかたどった【土偶】で豊かな実りや出産を祈った。死者の手足を折り曲げて葬る【屈葬】や、成人の通過儀礼とされる【抜歯】も行われた。"},
  {"id": "jhx5", "s": "jh", "lv": 2, "topic": "三内丸山遺跡", "q": "三内丸山遺跡から明らかになった縄文時代の社会の特徴を説明せよ。", "a": "青森県の【三内丸山遺跡】は長期間営まれた大規模な集落跡で、大型掘立柱建物の跡や【クリ】の栽培を示す痕跡がある。新潟県産の【ヒスイ】なども出土し、遠隔地との【交易】があったことがわかる。"},
  {"id": "jhx6", "s": "jh", "lv": 1, "topic": "稲作と社会の変化", "q": "弥生時代に水稲耕作が広まると、社会はどのように変化したか説明せよ。", "a": "米を【高床倉庫】に蓄えられるようになると、【貧富の差】や身分の差が生まれた。土地や水をめぐる争いも起こり、各地に指導者が率いる小さな【クニ】が生まれた。"},
  {"id": "jhx7", "s": "jh", "lv": 1, "topic": "弥生時代の戦い", "q": "弥生時代に戦いがあったことは、どのような遺跡からわかるか説明せよ。", "a": "周囲に濠をめぐらせた【環濠集落】や、山頂など高い場所に営まれた【高地性集落】がみられる。佐賀県の【吉野ヶ里遺跡】では、首のない人骨や矢じりの刺さった人骨も見つかっている。"},
  {"id": "jhx8", "s": "jh", "lv": 2, "topic": "弥生時代の金属器", "q": "弥生時代に伝わった鉄器と青銅器は、それぞれ主にどのように用いられたか。", "a": "【鉄器】は農具や工具、武器など実用の道具として用いられた。一方、銅鐸・銅剣・銅矛などの【青銅器】は主に【祭器】として用いられた。稲の穂首刈りには【石包丁】が使われた。"},
  {"id": "jhx9", "s": "jh", "lv": 2, "topic": "漢・後漢と倭", "q": "中国の歴史書は、紀元前後の倭の国々と中国との関係をどのように記しているか。", "a": "『漢書』地理志は、倭が百余国に分かれ【楽浪郡】に定期的に使いを送ったと記す。『後漢書』東夷伝は、57年に【奴国】王が後漢に使いを送り、光武帝から【印綬】を授けられたと記している。"},
  {"id": "jhx10", "s": "jh", "lv": 1, "topic": "邪馬台国", "q": "卑弥呼はどのように国を治め、中国とどのような関係を結んだか説明せよ。", "a": "卑弥呼は【呪術】的な権威によって約30の国々を従えた。239年に【魏】に使いを送り、「【親魏倭王】」の称号と金印、銅鏡などを授けられた。"},
  {"id": "jhx11", "s": "jh", "lv": 2, "topic": "前方後円墳", "q": "前方後円墳が各地に広がったことは、どのようなことを示しているか説明せよ。", "a": "3世紀中ごろから近畿を中心に【前方後円墳】が築かれ、同じ形式の古墳が各地に広がった。これは地方の【首長】たちが【ヤマト政権】と政治的な連合関係を結んでいたことを示している。"},
  {"id": "jhx12", "s": "jh", "lv": 3, "topic": "古墳の副葬品", "q": "古墳時代の前期と中期で副葬品はどう変化したか。その変化が示す被葬者の性格の違いとともに説明せよ。", "a": "前期は【銅鏡】や玉などの呪術的・宗教的な品が中心で、被葬者は【司祭者】的な性格をもっていた。中期には【鉄製武器】や【馬具】が増え、朝鮮半島との交流を背景に、被葬者の【武人】的な性格が強まった。"},
  {"id": "jhx13", "s": "jh", "lv": 2, "topic": "倭の五王", "q": "5世紀に倭の五王が中国の南朝に使いを送ったのはなぜか説明せよ。", "a": "倭の五王は中国【南朝】に朝貢して皇帝の権威を借り、【朝鮮半島】南部での軍事的・外交的な立場を有利にするとともに、国内での地位を高めようとした。478年には倭王【武】が宋に上表文を送った。"},
  {"id": "jhx14", "s": "jh", "lv": 3, "topic": "ワカタケル大王", "q": "稲荷山古墳出土鉄剣と江田船山古墳出土大刀の銘文から、5世紀後半のヤマト政権について何がわかるか。", "a": "埼玉県の【稲荷山古墳】出土の鉄剣と熊本県の【江田船山古墳】出土の大刀には、ともに「【ワカタケル】大王」の名が刻まれている。5世紀後半には大王の勢力が【関東】から九州中部にまで及んでいたことがわかる。"},
  {"id": "jhx15", "s": "jh", "lv": 1, "topic": "渡来人", "q": "4〜6世紀に朝鮮半島などから来た渡来人は、日本にどのような技術や文化を伝えたか。", "a": "渡来人は硬質で灰色の【須恵器】の製作や、機織り・金属加工などの技術を伝えた。また【漢字】を用いて記録や外交文書の作成にあたり、6世紀には【儒教】も伝えられた。ヤマト政権は彼らを【品部】に組織した。"},
  {"id": "jhx16", "s": "jh", "lv": 2, "topic": "氏姓制度", "q": "ヤマト政権が豪族を支配するしくみであった氏姓制度を説明せよ。", "a": "ヤマト政権は豪族を血縁などで結ばれた【氏】に組織し、家柄や地位に応じて臣・連などの【姓】を与えた。豪族は私有民の【部曲】や私有地の田荘を支配しつつ、政権の職務を分担した。"},
  {"id": "jhx17", "s": "jh", "lv": 3, "topic": "磐井の乱", "q": "6世紀前半の磐井の乱の経過と、その後のヤマト政権による地方支配の変化を説明せよ。", "a": "527年、【新羅】と結んだ筑紫国造【磐井】が、朝鮮半島に向かう政権の軍を妨げて反乱を起こしたが、鎮圧された。その後ヤマト政権は地方豪族を【国造】に任じ、各地に直轄地の【屯倉】を設けて地方支配を強めた。"},
  {"id": "jhx18", "s": "jh", "lv": 2, "topic": "仏教の伝来", "q": "6世紀に仏教が伝わると、その受け入れをめぐってどのような対立が起きたか。", "a": "6世紀半ば、【百済】の聖明王から仏教が公式に伝えられた。受け入れをめぐって崇仏派の【蘇我氏】と排仏派の【物部氏】が対立し、587年に蘇我馬子が物部守屋を滅ぼした。"},
  {"id": "jhx19", "s": "jh", "lv": 1, "topic": "推古朝の政治", "q": "推古天皇の時代に、厩戸王（聖徳太子）らはどのような国づくりをめざしたか説明せよ。", "a": "厩戸王は【蘇我馬子】と協力し、家柄にとらわれず才能のある人物を登用するため【冠位十二階】を定めた。また【十七条憲法】で役人の心構えを示し、天皇を中心とする国家をめざした。"},
  {"id": "jhx20", "s": "jh", "lv": 2, "topic": "遣隋使", "q": "遣隋使派遣の目的と、607年の国書にみられる外交姿勢を説明せよ。", "a": "中国の進んだ制度や文化を学ぶため、607年に【小野妹子】を派遣した。国書では倭の王を「天子」と記して【対等】な立場を求める姿勢を示し、隋の皇帝【煬帝】の不興を買ったが、翌年には【留学生】や学問僧も派遣された。"},
  {"id": "jhx21", "s": "jh", "lv": 2, "topic": "飛鳥文化", "q": "7世紀前半に栄えた飛鳥文化の特徴を、代表的な寺院や仏像にふれて説明せよ。", "a": "日本で最初の【仏教】文化で、【法隆寺】などの寺院が建てられた。中国の【南北朝】の文化の影響を受け、鞍作鳥の釈迦三尊像など、【渡来人】の技術に支えられた国際色豊かな文化であった。"},
  {"id": "jhx22", "s": "jh", "lv": 1, "topic": "大化の改新", "q": "7世紀半ばの大化の改新は、どのような国家をめざして行われたか説明せよ。", "a": "645年、【中大兄皇子】と中臣鎌足は蘇我氏を倒した（乙巳の変）。翌年【改新の詔】を出し、豪族の私有地・私有民を廃止する【公地公民】の方針を示して、天皇中心の中央集権国家をめざした。"},
  {"id": "jhx23", "s": "jh", "lv": 2, "topic": "白村江の戦い", "q": "白村江の戦いの結果、日本はどのような防衛策をとったか説明せよ。", "a": "663年、【百済】復興を助けるため出兵したが、唐・新羅の連合軍に大敗した。その後、唐・新羅の侵攻に備えて北九州に【水城】や朝鮮式山城を築き、【防人】を置いて防衛を固め、都を近江大津宮に移した。"},
  {"id": "jhx24", "s": "jh", "lv": 2, "topic": "壬申の乱", "q": "672年の壬申の乱の結果、天皇の権力はどのように変化したか説明せよ。", "a": "672年、【大海人皇子】が大友皇子を破って即位し【天武天皇】となった。近江朝廷側の有力豪族が没落したため天皇の権力が強まり、【八色の姓】による豪族の再編や、律令・国史の編纂が進められた。"},
  {"id": "jhx25", "s": "jh", "lv": 2, "topic": "持統朝と藤原京", "q": "持統天皇の時代に進められた律令国家づくりを、法令・戸籍・都城にふれて説明せよ。", "a": "持統天皇は【飛鳥浄御原令】を施行し、690年にはそれにもとづいて【庚寅年籍】を作成した。694年には条坊制をもつ初めての本格的な都城である【藤原京】に遷都した。"},
  {"id": "jhx26", "s": "jh", "lv": 2, "topic": "白鳳文化", "q": "白鳳文化の特徴を、代表的な建築・美術・文学にふれて説明せよ。", "a": "天武・持統天皇の時代を中心とする文化で、【初唐】の文化の影響を受けた清新な文化である。【薬師寺】東塔などが建てられ、【高松塚古墳】の壁画が描かれた。【柿本人麻呂】らが和歌を詠んだ。"},
  {"id": "jhx27", "s": "jh", "lv": 1, "topic": "大宝律令", "q": "大宝律令によって整えられた中央と地方の統治のしくみを説明せよ。", "a": "701年に【大宝律令】が完成し、中央には神祇官と【太政官】の二官と八省が置かれた。地方は国・郡・里に分けられ、中央から派遣された【国司】と、地方豪族から任じられた【郡司】が治めた。"},
  {"id": "jhx28", "s": "jh", "lv": 2, "topic": "律令制下の農民負担", "q": "律令制のもとで、農民はどのような税や負担を負っていたか説明せよ。", "a": "口分田からの収穫の一部を稲で納める【租】、地方の特産物を納める【調】、労役の代わりに布などを納める【庸】を負担した。ほかに国司のもとで労働する【雑徭】や【兵役】もあり、農民の負担は重かった。"},
  {"id": "jhx29", "s": "jh", "lv": 2, "topic": "三世一身法", "q": "奈良時代に三世一身法が出された理由と、この法の限界を説明せよ。", "a": "人口の増加などで【口分田】が不足したため、723年に【三世一身法】を出し、開墾した土地の一定期間の私有を認めた。しかし期限が近づくと耕地が荒れたため、743年の【墾田永年私財法】につながった。"},
  {"id": "jhx30", "s": "jh", "lv": 3, "topic": "律令制の動揺", "q": "8世紀から9世紀にかけて、班田収授が行われにくくなったのはなぜか説明せよ。", "a": "重い負担から逃れるため農民の【浮浪】・逃亡が増え、男子を女子と偽るなど戸籍をごまかす【偽籍】も広がった。口分田の不足も重なって【戸籍】・計帳による把握がくずれ、班田の間隔が延びて、10世紀初めを最後にほとんど行われなくなった。"},
  {"id": "jhx31", "s": "jh", "lv": 1, "topic": "平城京", "q": "平城京はどのような都であったか、手本とした都や特徴にふれて説明せよ。", "a": "710年、唐の都【長安】にならって【平城京】に遷都した。道路で碁盤の目状に区画する【条坊制】がとられ、東西の市では【和同開珎】などの貨幣も使われた。"},
  {"id": "jhx32", "s": "jh", "lv": 1, "topic": "遣唐使", "q": "遣唐使はどのような目的で派遣され、どのような役割を果たしたか。", "a": "唐の進んだ【制度】や文化を取り入れるために派遣され、【留学生】や学問僧が同行した。【吉備真備】や玄昉は帰国後に政治で活躍した。894年、【菅原道真】の建議で派遣は停止された。"},
  {"id": "jhx33", "s": "jh", "lv": 1, "topic": "鎮護国家", "q": "聖武天皇が国分寺の建立や大仏の造立を命じたのはなぜか説明せよ。", "a": "疫病や藤原広嗣の乱などで社会不安が続いたため、【仏教】の力で国家を守ろうとする【鎮護国家】の思想にもとづいて、741年に【国分寺建立の詔】、743年に【大仏造立の詔】を出した。"},
  {"id": "jhx34", "s": "jh", "lv": 3, "topic": "奈良時代の政争", "q": "奈良時代には、政治の実権がどのように移り変わったか。藤原氏と他の勢力の動きを中心に説明せよ。", "a": "藤原不比等の死後、【長屋王】が政権を握ったが、不比等の4子に倒された。4子が疫病で死ぬと【橘諸兄】が政権を握り、その後【藤原仲麻呂】、さらに僧の【道鏡】が権力をふるうなど、政権の担い手は激しく交代した。"},
  {"id": "jhx35", "s": "jh", "lv": 2, "topic": "天平文化", "q": "天平文化の特徴を、国際性や代表的な文化財・書物にふれて説明せよ。", "a": "聖武天皇の時代を中心とする、仏教色の強い貴族文化である。盛唐の文化の影響を受けて【国際色】豊かで、【正倉院】の宝物には【シルクロード】を通じて伝わった品もある。『古事記』『日本書紀』や『【万葉集】』も編まれた。"},
  {"id": "jhx36", "s": "jh", "lv": 2, "topic": "古事記と日本書紀", "q": "奈良時代初めに成立した『古事記』と『日本書紀』の成立事情と、書き方の違いを説明せよ。", "a": "『【古事記】』は稗田阿礼が誦習したものを太安万侶が筆録して712年に成立した。『【日本書紀】』は舎人親王らが720年に完成させ、【漢文】の【編年体】で書かれ、【六国史】の最初となった。"},
  {"id": "jhx37", "s": "jh", "lv": 2, "topic": "行基", "q": "行基は朝廷からどのように扱われたか。その活動の変化とともに説明せよ。", "a": "行基は民衆に布教しながら用水や橋をつくる【社会事業】を行ったため、はじめは【僧尼令】に反するとして朝廷に弾圧された。のちに【大仏造立】に協力し、【大僧正】に任じられた。"},
  {"id": "jhx38", "s": "jh", "lv": 2, "topic": "東北経営", "q": "律令国家は東北地方の蝦夷に対してどのような政策をとったか説明せよ。", "a": "律令国家は陸奥国に【多賀城】を築いて支配を広げた。桓武天皇は【坂上田村麻呂】を征夷大将軍に任じ、蝦夷の族長【阿弖流為】を降伏させ、【胆沢城】を築いて支配の拠点を北へ進めた。"},
  {"id": "jhx39", "s": "jh", "lv": 2, "topic": "桓武天皇の政治", "q": "桓武天皇が平安京に遷都した理由と、行った政治改革を説明せよ。", "a": "寺院など【仏教】勢力の政治への介入を断ち、政治を立て直すため、784年に長岡京、794年に【平安京】へ遷都した。国司の交代を監督する【勘解由使】を置き、東北などを除いて軍団を廃止し【健児】を置いた。"},
  {"id": "jhx40", "s": "jh", "lv": 2, "topic": "令外官", "q": "平安時代初期に令外官が置かれたのはなぜか。代表的な官職をあげて説明せよ。", "a": "律令の規定だけでは現実の政治に対応できなくなったため、律令にない【令外官】が置かれた。嵯峨天皇は機密を扱う【蔵人頭】や、京の治安を担う【検非違使】を置いた。また法令を整理した【格式】も編纂された。"},
  {"id": "jhx41", "s": "jh", "lv": 1, "topic": "天台宗と真言宗", "q": "平安時代初期に最澄と空海が広めた新しい仏教の特徴を説明せよ。", "a": "最澄は【比叡山】延暦寺を開いて【天台宗】を、空海は高野山金剛峯寺を開いて【真言宗】を広めた。両宗は加持祈祷で災いを除き現世の利益を願う【密教】を取り入れ、貴族の信仰を集めた。"},
  {"id": "jhx42", "s": "jh", "lv": 2, "topic": "弘仁・貞観文化", "q": "平安時代初期の弘仁・貞観文化の特徴を、文学・仏教美術・書道にふれて説明せよ。", "a": "宮廷では【漢詩文】が重んじられ、勅撰漢詩集が編まれた。仏教では【密教】が盛んになり、【曼荼羅】や一木造の神秘的な仏像が作られた。書道では嵯峨天皇・空海・橘逸勢の【三筆】が活躍した。"},
  {"id": "jhx43", "s": "jh", "lv": 2, "topic": "藤原北家の他氏排斥", "q": "藤原北家は、9〜10世紀にどのようにして他の貴族を政界から退けたか説明せよ。", "a": "藤原良房は【承和の変】で伴健岑・橘逸勢を退け、【応天門の変】で伴善男を失脚させた。藤原時平は【菅原道真】を大宰府に左遷させ、969年の【安和の変】で源高明が退けられて北家の地位が確立した。"},
  {"id": "jhx44", "s": "jh", "lv": 3, "topic": "摂関期の政治運営", "q": "摂関政治の時代、政治はどのように運営され、なぜ中・下級貴族は摂関家に近づいたのか説明せよ。", "a": "摂関政治の時代も政治は【太政官】で行われ、重要事項は公卿の会議である【陣定】で審議された。摂政・関白は官吏の【人事権】を握っていたため、中・下級貴族は摂関家に近づき、収入の多い【受領】の地位を求めた。"},
  {"id": "jhx45", "s": "jh", "lv": 1, "topic": "国風文化", "q": "遣唐使の停止前後から栄えた国風文化の特徴を、文字・文学・住宅にふれて説明せよ。", "a": "唐の文化を消化し、日本の風土や生活に合った文化が生まれた。【かな文字】が発達して紫式部の『【源氏物語】』や清少納言の『枕草子』などの女流文学が生まれ、貴族の住宅には【寝殿造】が用いられた。"},
  {"id": "jhx46", "s": "jh", "lv": 2, "topic": "浄土教", "q": "平安時代中期に浄土教が広まった理由と、その広がりを示す例を説明せよ。", "a": "社会不安と、仏の教えが衰えるという【末法思想】の広がりから、【阿弥陀仏】を信じて極楽浄土への往生を願う浄土教が広まった。【空也】が都で念仏を説き、源信は『往生要集』を著し、藤原頼通は【平等院鳳凰堂】を建てた。"},
  {"id": "jhx47", "s": "jh", "lv": 3, "topic": "受領と地方支配の変化", "q": "10世紀に国司による地方支配はどのように変化したか。課税のしくみの変化とあわせて説明せよ。", "a": "政府は国司に一定額の税の納入を請け負わせ、国内の支配を任せた。任国に赴く最上席の国司は【受領】とよばれ、課税対象を人から土地へ改めた。田地を【名】に編成し、有力農民の【田堵】に耕作と納税を請け負わせた。"},
  {"id": "jhx48", "s": "jh", "lv": 2, "topic": "寄進地系荘園", "q": "11世紀ごろに広がった寄進地系荘園は、どのようにして生まれたか説明せよ。", "a": "開発領主は国司の干渉や税の負担を逃れるため、所領を中央の有力な貴族や寺社に【寄進】した。寄進を受けた者は【領家】、さらに上級の者は【本家】となり、荘園は【不輸の権】や不入の権を得て独立性を強めた。"},
  {"id": "jhx49", "s": "jh", "lv": 1, "topic": "承平・天慶の乱", "q": "10世紀前半の承平・天慶の乱は、武士の成長にとってどのような意味をもったか。", "a": "関東で【平将門】が、瀬戸内海で【藤原純友】が反乱を起こした。朝廷は地方の【武士】の力を借りてこれらを鎮圧したため、武士の実力が明らかになり、その地位が高まった。"},
  {"id": "jhx50", "s": "jh", "lv": 2, "topic": "源氏の東国進出", "q": "11世紀の東北地方の争乱は、源氏の勢力拡大とどのように結びついたか説明せよ。", "a": "東北の争乱である【前九年合戦】と【後三年合戦】を源頼義・【源義家】らが鎮めたことで、源氏は【東国】の武士との主従関係を強めた。その後、奥州では【奥州藤原氏】が平泉を拠点に栄えた。"},
  {"id": "jhx51", "s": "jh", "lv": 2, "topic": "延久の荘園整理令", "q": "後三条天皇が出した延久の荘園整理令の内容と、その意義を説明せよ。", "a": "1069年、【後三条天皇】は【記録荘園券契所】を置き、証拠書類の不備な荘園や新しい荘園を停止させた。【摂関家】の荘園も例外とせず、摂関家と外戚関係のない天皇が政治の主導権を取り戻した。"},
  {"id": "jhx52", "s": "jh", "lv": 3, "topic": "院政の権力基盤", "q": "院政期の上皇の権力は、どのようなものに支えられていたか。直面した問題とあわせて説明せよ。", "a": "上皇は【院宣】や院庁下文で政治を動かし、【北面の武士】を置いて武力を備えた。上皇のもとには多くの【荘園】が寄進され、知行国の制度も経済基盤となった。一方、大寺院が僧兵を使って起こす【強訴】に悩まされた。"},
  {"id": "jhx53", "s": "jh", "lv": 2, "topic": "院政期の文化", "q": "院政期の文化の特徴を、地方への広がりや庶民の文化にふれて説明せよ。", "a": "浄土教が地方にも広まり、奥州藤原氏の【中尊寺金色堂】などが建てられた。後白河上皇は庶民の流行歌である【今様】を『梁塵秘抄』にまとめ、『鳥獣戯画』などの【絵巻物】も作られた。"},
  {"id": "jhx54", "s": "jh", "lv": 1, "topic": "平氏政権", "q": "平清盛は、どのようにして政治の実権を握り、どのような政策を行ったか説明せよ。", "a": "清盛は【保元の乱】・平治の乱に勝利し、1167年に武士として初めて【太政大臣】となった。娘を天皇の后として外戚となり、大輪田泊を修築して【日宋貿易】を進め、大きな利益をあげた。"},
  {"id": "jhx55", "s": "jh", "lv": 3, "topic": "平氏政権の性格", "q": "平氏政権がもっていた貴族的な性格と武家政権としての性格を、滅亡の理由とあわせて説明せよ。", "a": "平氏は一門で高位高官を独占し、【外戚】として権力を握るなど摂関家に似た【貴族的】な性格をもった。一方、各地の武士を家人とし【地頭】に任じた点では武家政権の性格もあった。院や旧勢力、地方武士の反発を招き、【治承・寿永の乱】で滅んだ。"},
  {"id": "jhx56", "s": "jh", "lv": 1, "topic": "守護と地頭", "q": "源頼朝が全国に置いた守護と地頭は、それぞれどのような役割を担ったか説明せよ。", "a": "1185年、頼朝は朝廷に認めさせ、国ごとに【守護】を置いて軍事・警察を担当させ、荘園や公領ごとに【地頭】を置いて年貢の徴収や土地の管理にあたらせた。これにより頼朝の支配が【全国】に及んだ。"},
  {"id": "jhx57", "s": "jh", "lv": 2, "topic": "執権政治", "q": "北条氏による執権政治は、どのように確立し、どのような特徴をもったか。", "a": "頼朝の死後、北条時政が【執権】となり、2代義時は【承久の乱】に勝利して地位を固めた。3代泰時は有力御家人による合議制をとって【評定衆】を置き、【御成敗式目】を定めた。"},
  {"id": "jhx58", "s": "jh", "lv": 1, "topic": "承久の乱", "q": "承久の乱の結果、鎌倉幕府の支配はどのように変化したか説明せよ。", "a": "1221年、【後鳥羽上皇】が倒幕の兵をあげたが敗れ、隠岐に流された。幕府は京都に【六波羅探題】を置いて朝廷を監視し、上皇方の所領に【新補地頭】を置いて、支配を西国にまで広げた。"},
  {"id": "jhx59", "s": "jh", "lv": 2, "topic": "御成敗式目", "q": "北条泰時が御成敗式目を定めた目的と、その基準となったものを説明せよ。", "a": "1232年、泰時は頼朝以来の【先例】と武家社会の【道理】にもとづき、【御家人】の間や御家人と荘園領主の間の争いを公平に裁く基準として定めた。最初の【武家法】で、朝廷の法を否定するものではなかった。"},
  {"id": "jhx60", "s": "jh", "lv": 3, "topic": "地頭の荘園侵略", "q": "鎌倉時代に地頭と荘園領主の対立はどのように解決がはかられ、その結果どうなったか説明せよ。", "a": "地頭が年貢を横領するなど荘園領主と対立すると、領主は地頭に一定額の年貢納入を請け負わせる【地頭請】や、土地を領主と地頭で分け合う【下地中分】で解決をはかった。その結果、地頭の【現地支配】が強まり、【荘園】制は変質していった。"},
  {"id": "jhx61", "s": "jh", "lv": 1, "topic": "鎌倉時代の産業", "q": "鎌倉時代には、農業や商業にどのような発達がみられたか説明せよ。", "a": "畿内や西日本で麦を裏作とする【二毛作】が広まり、刈敷や草木灰が肥料に使われた。寺社の門前や交通の要地では【定期市】が開かれ、【宋銭】が流通し、遠隔地の取引には【為替】が用いられた。"},
  {"id": "jhx62", "s": "jh", "lv": 2, "topic": "惣領制", "q": "鎌倉時代の武士の一族結合である惣領制と、その相続方法の変化を説明せよ。", "a": "武士は一族の長である【惣領】が庶子を率いて戦い、幕府への奉公を果たした。所領は【分割相続】されたため細分化が進み、御家人は困窮した。そのため鎌倉後期には惣領が所領を受け継ぐ【単独相続】へと移っていった。"},
  {"id": "jhx63", "s": "jh", "lv": 3, "topic": "得宗専制", "q": "蒙古襲来後の鎌倉幕府でみられた得宗専制とはどのような政治か。成立の経緯とあわせて説明せよ。", "a": "蒙古襲来後、北条氏の嫡流である【得宗】の権力が強まり、得宗の家臣である【御内人】が幕政に大きな影響力をもった。1285年の【霜月騒動】で有力御家人の安達泰盛が滅ぼされると得宗専制が確立し、【御家人】の不満が高まった。"},
  {"id": "jhx64", "s": "jh", "lv": 3, "topic": "鎌倉幕府の滅亡", "q": "鎌倉幕府が滅亡に至った背景を、御家人の状況や社会の変化にふれて説明せよ。", "a": "分割相続や【貨幣経済】の浸透で御家人が困窮する一方、【得宗専制】への反発が強まった。畿内では荘園領主や幕府に反抗する【悪党】が現れた。【後醍醐天皇】の倒幕計画に足利高氏や新田義貞らが応じ、1333年に幕府は滅亡した。"},
  {"id": "jhx65", "s": "jh", "lv": 2, "topic": "鎌倉文化の美術", "q": "鎌倉時代の彫刻・建築には、どのような特徴がみられるか説明せよ。", "a": "武士の気風を反映した力強く写実的な作品が生まれ、東大寺南大門の【金剛力士像】は【運慶】・快慶らが制作した。東大寺の再建では宋の様式を取り入れた【大仏様】が用いられ、禅宗寺院には【禅宗様】が用いられた。"},
  {"id": "jhx66", "s": "jh", "lv": 2, "topic": "鎌倉時代の文学", "q": "鎌倉時代に生まれた文学の特徴を、軍記物語や随筆にふれて説明せよ。", "a": "平氏の興亡を描いた軍記物語『【平家物語】』は、【琵琶法師】によって語られ、文字を読めない人々にも広まった。また【鴨長明】の『方丈記』や兼好法師の『【徒然草】』など、無常観を背景とする随筆も生まれた。"},
  {"id": "jhx67", "s": "jh", "lv": 1, "topic": "建武の新政", "q": "後醍醐天皇の建武の新政が、短期間で失敗したのはなぜか説明せよ。", "a": "【後醍醐天皇】は天皇中心の政治をめざしたが、公家を重んじる政策や、【恩賞】の不公平に【武士】が不満を強めた。武家政治の再興をめざす【足利尊氏】が離反し、新政は約2年半で崩れた。"},
  {"id": "jhx68", "s": "jh", "lv": 3, "topic": "南北朝の動乱", "q": "南北朝の動乱が約60年もの長期に及んだ理由を、武士社会の変化にふれて説明せよ。", "a": "【惣領制】がくずれて武士団の内部で分裂が起こり、一方が北朝につけば他方が南朝につくなど対立が複雑化した。幕府内部でも足利尊氏と直義が争う【観応の擾乱】が起きた。地縁的な結合を強めた武士は【守護】に従い、守護が権限を拡大した。"},
  {"id": "jhx69", "s": "jh", "lv": 2, "topic": "守護大名", "q": "南北朝の動乱の中で、守護はどのようにして守護大名へと成長したか説明せよ。", "a": "幕府は守護に、荘園・公領の年貢の半分を兵粮米として徴収できる【半済令】や、【刈田狼藉】の取り締まりなどの権限を与えた。守護は国内の武士を家臣化し、荘園の年貢納入を請け負う【守護請】も行って、【守護大名】へと成長した。"},
  {"id": "jhx70", "s": "jh", "lv": 2, "topic": "室町幕府の機構", "q": "室町幕府の中央と地方の主な機構と、それぞれの長官に任じられた人々を説明せよ。", "a": "将軍を補佐する【管領】には細川・斯波・畠山の三氏が交代で任じられ、侍所の長官には四職が任じられた。地方には関東を治める【鎌倉府】が置かれ、長官の【鎌倉公方】は足利基氏の子孫が世襲した。"},
  {"id": "jhx71", "s": "jh", "lv": 2, "topic": "足利義満の権力確立", "q": "足利義満はどのようにして室町幕府の権力を確立したか説明せよ。", "a": "義満は1392年に【南北朝の合一】を実現し、【明徳の乱】で山名氏清を、【応永の乱】で大内義弘を討って有力守護の勢力を抑えた。また【太政大臣】となって公家社会でも頂点に立った。"},
  {"id": "jhx72", "s": "jh", "lv": 3, "topic": "室町幕府の財政", "q": "室町幕府の財政はどのような収入によって支えられていたか、その特徴とともに説明せよ。", "a": "直轄領である【御料所】からの収入が少なかったため、高利貸しの【土倉】・酒屋に課す土倉役・酒屋役、交通の要地に設けた【関銭】・津料、日明貿易の利益などに頼った。守護を通じて【段銭】・棟別銭も徴収するなど、商業や流通への課税に依存した。"},
  {"id": "jhx73", "s": "jh", "lv": 3, "topic": "足利義教と嘉吉の乱", "q": "6代将軍足利義教の政治と嘉吉の乱は、室町幕府にどのような影響を与えたか。", "a": "【足利義教】は将軍権力の強化をめざし、【永享の乱】で鎌倉公方足利持氏を滅ぼすなど専制的な政治を行った。しかし守護の反発を招き、1441年に播磨守護【赤松満祐】に殺された（【嘉吉の乱】）。これ以後、将軍の権威は大きく衰えた。"},
  {"id": "jhx74", "s": "jh", "lv": 1, "topic": "惣村", "q": "室町時代の農村で成立した惣村とは、どのような村であったか説明せよ。", "a": "農民が自治的な村である【惣】をつくり、【寄合】で村のおきてである惣掟を定め、入会地や用水を共同で管理した。団結した農民は年貢の減免などを求めて【一揆】を結ぶこともあった。"},
  {"id": "jhx75", "s": "jh", "lv": 2, "topic": "正長の土一揆", "q": "1428年に起きた正長の土一揆の経過と、その歴史的な意味を説明せよ。", "a": "近江の【馬借】の蜂起をきっかけに、京都周辺の農民が【徳政】を要求して酒屋・【土倉】などの高利貸しを襲った。幕府は徳政令を出さなかったが、各地で実力による【私徳政】が行われ、民衆の力が示された。"},
  {"id": "jhx76", "s": "jh", "lv": 2, "topic": "山城の国一揆と加賀の一向一揆", "q": "15世紀後半の山城の国一揆と加賀の一向一揆は、それぞれどのような一揆か説明せよ。", "a": "1485年、南山城の国人と農民は争う【畠山氏】の軍を国外に退去させ、8年間自治を行った。1488年には浄土真宗の門徒らによる加賀の【一向一揆】が守護【富樫政親】を倒し、約100年間にわたって自治を行った。"},
  {"id": "jhx77", "s": "jh", "lv": 2, "topic": "室町時代の産業", "q": "室町時代の農業はどのように発達したか。商品作物や市の発達とあわせて説明せよ。", "a": "畿内では【三毛作】も行われ、人糞尿の【下肥】が肥料として使われた。灯油の原料となる【荏胡麻】や茶などの商品作物も栽培された。地方の市は月に6回開かれる【六斎市】が一般的になった。"},
  {"id": "jhx78", "s": "jh", "lv": 2, "topic": "室町時代の流通", "q": "室町時代の商工業者や流通、貨幣の使用にはどのような特徴がみられたか。", "a": "陸上輸送は【馬借】・車借、港での保管・輸送は問丸が担った。商工業者は【座】を結んで公家や寺社の保護を受け、独占的な営業権を得た。明銭の【永楽通宝】なども使われたが、粗悪な銭を嫌う【撰銭】が行われ、取引の妨げとなった。"},
  {"id": "jhx79", "s": "jh", "lv": 2, "topic": "北山文化", "q": "足利義満の時代の北山文化の特徴を、建築や芸能にふれて説明せよ。", "a": "伝統的な【公家】文化と新しい武家文化が融合し、【禅宗】の影響も受けた文化である。義満が京都の北山に建てた【金閣】がその象徴で、【観阿弥】・世阿弥父子が能を大成した。"},
  {"id": "jhx80", "s": "jh", "lv": 1, "topic": "東山文化", "q": "足利義政の時代の東山文化の特徴を、建築や絵画にふれて説明せよ。", "a": "禅の精神にもとづく簡素で深みのある美が重んじられた。慈照寺の東求堂同仁斎には、現代の和風住宅のもととなる【書院造】が用いられた。【雪舟】は【水墨画】を大成し、石や砂で自然を表す【枯山水】の庭園もつくられた。"},
  {"id": "jhx81", "s": "jh", "lv": 3, "topic": "文化の地方・庶民への広がり", "q": "室町時代後期に文化が地方や庶民に広がったのはなぜか。具体例をあげて説明せよ。", "a": "応仁の乱で京都が荒廃すると、多くの【公家】や禅僧が地方の大名を頼って下り、文化が【地方】に広まった。宗祇らが各地で【連歌】を広め、御伽草子や狂言など庶民も楽しめる文芸が生まれ、都市の町衆や村の農民も文化の担い手となった。"},
  {"id": "jhx82", "s": "jh", "lv": 2, "topic": "日朝貿易", "q": "室町時代の日朝貿易はどのように行われ、どのように衰えたか説明せよ。", "a": "朝鮮は【倭寇】の禁止を求めて日本と通交し、【対馬】の【宗氏】を通じて貿易を統制した。日本は朝鮮から【木綿】などを輸入した。1510年に朝鮮の港に住む日本人が暴動を起こした【三浦の乱】以後、貿易は衰えた。"},
  {"id": "jhx83", "s": "jh", "lv": 1, "topic": "鎌倉幕府の機構", "q": "源頼朝が鎌倉に設けた幕府の主な機関について、それぞれの役割を説明せよ。", "a": "御家人を統率し軍事・警察を担う【侍所】、一般政務や財政を担う【公文所】（のちの【政所】）、裁判を担う【問注所】が置かれた。頼朝は1192年に【征夷大将軍】に任じられた。"},
  {"id": "jhx84", "s": "jh", "lv": 1, "topic": "鎌倉武士の生活", "q": "鎌倉時代の武士は、ふだんどのような生活を送っていたか説明せよ。", "a": "武士は所領の中に堀や塀で囲んだ【館】を構え、周辺の田畑を下人などに耕作させた。日ごろから【流鏑馬】・笠懸・犬追物などで【武芸】をみがき、「弓馬の道」とよばれる武士らしい生き方を重んじた。"},
  {"id": "jhx85", "s": "jh", "lv": 2, "topic": "北条時頼の政治", "q": "5代執権北条時頼は、どのようにして執権政治を強化したか説明せよ。", "a": "時頼は1247年の【宝治合戦】で有力御家人の【三浦氏】を滅ぼし、北条氏の地位を固めた。また評定衆の下に【引付衆】を置いて御家人の所領に関する裁判の迅速化・公正化をはかり、【御家人】の保護に努めた。"},
  {"id": "jhx86", "s": "jh", "lv": 2, "topic": "両統迭立", "q": "鎌倉時代後期の皇位継承をめぐる両統迭立とは何か。後醍醐天皇の即位との関係にもふれて説明せよ。", "a": "皇室は【持明院統】と【大覚寺統】に分かれて皇位や荘園をめぐって争い、幕府の調停で両統が交代で皇位につく【両統迭立】の方式がとられた。大覚寺統から即位した【後醍醐天皇】は、これに介入する幕府を倒そうとした。"},
  {"id": "jhx87", "s": "jh", "lv": 2, "topic": "鎌倉時代の学問と和歌", "q": "鎌倉時代の公家・武家の学問や和歌には、どのような動きがみられたか説明せよ。", "a": "公家の間では伝統文化への関心が高まり、後鳥羽上皇の命で『【新古今和歌集】』が編まれた。武家では北条実時が【金沢文庫】を設けて和漢の書物を集めた。神道では度会家行が【伊勢神道】を唱えた。"},
  {"id": "jhx88", "s": "jh", "lv": 2, "topic": "琉球王国", "q": "15世紀に成立した琉球王国は、どのようにして繁栄したか説明せよ。", "a": "1429年、中山王の【尚巴志】が三山を統一して琉球王国を建てた。首里を都とし、明への朝貢を軸に日本や東南アジアの産物を取り次ぐ【中継貿易】で栄え、【那覇】は国際的な港として発展した。"},
  {"id": "jhx89", "s": "jh", "lv": 2, "topic": "アイヌと和人", "q": "室町時代の蝦夷ヶ島（北海道）における和人とアイヌの関係を説明せよ。", "a": "和人は渡島半島南部に【館】を築いて進出し、アイヌと交易した。和人の圧迫に対して1457年に【コシャマイン】が蜂起したが、【蠣崎氏】に鎮圧された。蠣崎氏はのちに【松前氏】と改め、蝦夷地の支配者となった。"},
  {"id": "jhx90", "s": "jh", "lv": 1, "topic": "戦国大名の領国支配", "q": "戦国大名は、どのようにして自らの領国や家臣を支配したか説明せよ。", "a": "戦国大名は独自の法である【分国法】を定めて家臣や領民を統制した。【指出検地】で土地や収入を把握し、家臣の収入を銭に換算した【貫高】を基準に軍役を課した。また【城下町】を建設して家臣や商工業者を集めた。"},
  {"id": "jhx91", "s": "jh", "lv": 1, "topic": "鉄砲とキリスト教の伝来", "q": "16世紀半ばに伝わった鉄砲とキリスト教は、どのように日本に広まったか。", "a": "1543年、【種子島】に漂着したポルトガル人が鉄砲を伝え、堺などで生産された。1549年には【フランシスコ・ザビエル】がキリスト教を伝えた。宣教師は【南蛮貿易】と結びついて布教し、九州などに【キリシタン大名】も現れた。"},
  {"id": "jhx92", "s": "jh", "lv": 3, "topic": "鉄砲の影響", "q": "鉄砲の普及は、戦国時代の戦い方や城郭、全国統一にどのような影響を与えたか。", "a": "鉄砲は【足軽】の鉄砲隊による集団戦法を広め、騎馬武者中心の戦い方を変えた。1575年の【長篠の戦い】はその典型である。防御のため高い石垣と【天守】をもつ城郭が築かれ、大量の鉄砲を調達できる大名が優位に立ち、【全国統一】が早まった。"},
  {"id": "jhx93", "s": "jh", "lv": 2, "topic": "自治都市", "q": "戦国時代の堺・博多・京都では、どのような自治が行われていたか説明せよ。", "a": "日明貿易や南蛮貿易で栄えた【堺】は【会合衆】、博多は年行司の合議で自治を行った。京都では富裕な商工業者である【町衆】が町を単位に自治を行い、応仁の乱で中断した【祇園祭】を復興した。"},
  {"id": "jhx94", "s": "jh", "lv": 1, "topic": "下剋上の風潮", "q": "戦国時代に広まった下剋上の風潮とは何か。具体例をあげて説明せよ。", "a": "身分の下の者が実力で上の者を倒して地位を奪う風潮を【下剋上】という。守護代や国人などが守護大名を倒して【戦国大名】となる例が多く、【北条早雲】は伊豆・相模を奪い、斎藤道三も美濃の守護を追放した。"},
  {"id": "jhx95", "s": "jh", "lv": 1, "topic": "織田信長の統一事業", "q": "織田信長は、どのような戦いや政策によって全国統一を進めたか説明せよ。", "a": "信長は1560年の【桶狭間の戦い】で今川義元を破り、1573年に将軍足利義昭を追放して【室町幕府】を滅ぼした。【比叡山延暦寺】を焼き打ちし、【石山本願寺】を屈服させるなど、仏教勢力も武力で押さえた。"},
  {"id": "jhx96", "s": "jh", "lv": 1, "topic": "楽市・楽座", "q": "織田信長が楽市・楽座や関所の撤廃を行ったのはなぜか説明せよ。", "a": "信長は安土城下などで【楽市・楽座】令を出し、【座】の特権を否定して自由な営業を認め、商工業者を城下に集めた。また【関所】を撤廃して物資の流通を盛んにし、経済力を強めて統一事業を進めようとした。"},
  {"id": "jhx97", "s": "jh", "lv": 2, "topic": "豊臣秀吉の全国統一", "q": "豊臣秀吉は、どのような権威や手段を用いて全国統一を実現したか説明せよ。", "a": "秀吉は【関白】・太政大臣となり、天皇の権威を利用して大名に私的な争いを禁じる【惣無事令】を出した。これに従わない九州の島津氏を降伏させ、1590年には【小田原】の北条氏を滅ぼして全国統一を果たした。"},
  {"id": "jhx98", "s": "jh", "lv": 2, "topic": "バテレン追放令", "q": "豊臣秀吉がバテレン追放令を出した理由と、それが不徹底に終わった理由を説明せよ。", "a": "1587年、秀吉は【大村純忠】が長崎をイエズス会に寄進していたことなどを知り、【バテレン追放令】を出して宣教師の国外退去を命じた。しかし【南蛮貿易】は奨励したため、宣教師の来日を防げず、禁教は不徹底に終わった。"},
  {"id": "jhx99", "s": "jh", "lv": 2, "topic": "朝鮮侵略", "q": "豊臣秀吉による朝鮮侵略の経過と、それが豊臣政権に与えた影響を説明せよ。", "a": "秀吉は明の征服をめざして【文禄の役】・【慶長の役】で朝鮮に出兵したが、朝鮮の義兵や【李舜臣】の率いる水軍、明の援軍に苦しみ、秀吉の死で撤兵した。多大な負担は大名を疲弊させ、【豊臣政権】を弱体化させた。"},
  {"id": "jhx100", "s": "jh", "lv": 2, "topic": "桃山文化", "q": "桃山文化の特徴を、担い手と代表的な建築・絵画・芸能にふれて説明せよ。", "a": "新興の大名や豪商の気風を反映した、豪華で壮大な文化である。【天守】をもつ城郭が築かれ、内部の襖や屏風には【狩野永徳】らが【障壁画】を描いた。【千利休】は茶の湯を侘び茶として大成した。"},
  {"id": "jhx101", "s": "jh", "lv": 3, "topic": "豊臣政権の身分統制", "q": "豊臣秀吉の政策によって、近世の身分制社会の基礎はどのように形づくられたか説明せよ。", "a": "太閤検地で耕作者を年貢負担者として検地帳に登録し、【刀狩】で百姓の武器を没収した。1591年の【人掃令】（身分統制令）では武士が町人・百姓になることや百姓が商人になることなどを禁じた。これらにより【兵農分離】が進み、近世の【身分制】社会の基礎が固まった。"},
  {"id": "jhx102", "s": "jh", "lv": 1, "topic": "江戸幕府の成立", "q": "徳川家康は、どのようにして江戸幕府を開き、その支配を固めたか説明せよ。", "a": "家康は1600年の【関ヶ原の戦い】で石田三成らを破り、1603年に【征夷大将軍】に任じられて江戸幕府を開いた。1615年の【大坂の陣】で豊臣氏を滅ぼし、幕府の支配を固めた。"},
  {"id": "jhx103", "s": "jh", "lv": 1, "topic": "武家諸法度", "q": "江戸幕府が大名を統制するために出した武家諸法度の内容を説明せよ。", "a": "1615年に初めて出された【武家諸法度】は、城の無断修築や大名どうしの無許可の【婚姻】などを禁じた。1635年には【徳川家光】が【参勤交代】を制度化した。違反した大名は領地を没収する【改易】などで処罰された。"},
  {"id": "jhx104", "s": "jh", "lv": 1, "topic": "大名の配置", "q": "江戸幕府は大名をどのように区別し、全国にどのように配置したか説明せよ。", "a": "徳川氏一門の【親藩】や、関ヶ原の戦い以前から徳川氏の家臣だった【譜代】を江戸周辺などの要地に置き、関ヶ原の戦い以後に従った【外様】は遠隔地に配置した。幕府の要職には主に譜代大名が就いた。"},
  {"id": "jhx105", "s": "jh", "lv": 2, "topic": "江戸幕府の職制", "q": "江戸幕府の主な役職について、それぞれがどのような役割を担ったか説明せよ。", "a": "常置の最高職である【老中】が政務を統括し、非常時には【大老】が置かれた。【若年寄】は老中を補佐して旗本・御家人を監督し、寺社奉行・町奉行・勘定奉行の【三奉行】が実務を担った。重要事項は評定所で合議された。"},
  {"id": "jhx106", "s": "jh", "lv": 3, "topic": "朝廷と寺社の統制", "q": "江戸幕府は、朝廷や寺社をどのように統制したか。紫衣事件の意味にもふれて説明せよ。", "a": "幕府は【禁中並公家諸法度】で天皇・公家の行動を規制し、【京都所司代】に朝廷を監視させた。1627年の【紫衣事件】は幕府の法が天皇の勅許に優越することを示した。寺院は寺院法度で統制され、【寺請制度】でキリシタンでないことを証明する役割を担わされた。"},
  {"id": "jhx107", "s": "jh", "lv": 2, "topic": "村の支配", "q": "江戸時代の村はどのように運営され、幕府や藩は村をどのように支配したか。", "a": "村は【名主】（庄屋）・組頭・百姓代の【村方三役】を中心に自治的に運営された。年貢は村全体の責任で納める【村請制】がとられ、【五人組】をつくらせて年貢の納入や犯罪の防止に連帯責任を負わせた。"},
  {"id": "jhx108", "s": "jh", "lv": 2, "topic": "本百姓と年貢", "q": "江戸時代の本百姓はどのような負担を負い、幕府は本百姓をどのように維持しようとしたか。", "a": "検地帳に登録された【本百姓】は、田畑・屋敷地にかかる【本途物成】を中心に、【小物成】や国役・伝馬役などを負担した。幕府は本百姓の没落を防ぐため、1643年に【田畑永代売買の禁止令】を出した。"},
  {"id": "jhx109", "s": "jh", "lv": 1, "topic": "島原の乱", "q": "島原・天草一揆が起きた理由と、その後の幕府の対外政策を説明せよ。", "a": "1637年、【キリシタン】への弾圧と重い年貢に苦しむ島原・天草の農民らが、【天草四郎】（益田時貞）を首領に一揆を起こした。乱の後、幕府は禁教を強化し、1639年に【ポルトガル】船の来航を禁止した。"},
  {"id": "jhx110", "s": "jh", "lv": 3, "topic": "四つの口", "q": "いわゆる「鎖国」下の江戸幕府は、長崎以外にどのような窓口で異国・異民族と交流したか説明せよ。", "a": "【対馬】藩の宗氏を通じて朝鮮と国交を結び、将軍の代がわりなどに【朝鮮通信使】が来日した。【薩摩】藩は琉球王国を支配しつつ、琉球の中国への朝貢貿易を利用した。【松前】藩はアイヌとの交易を独占した。"},
  {"id": "jhx111", "s": "jh", "lv": 2, "topic": "文治政治への転換", "q": "4代将軍徳川家綱の時代に、武断政治から文治政治へ転換したのはなぜか説明せよ。", "a": "大名の改易で増えた牢人による【由井正雪の乱】（慶安の変）を機に、武力で抑える政治から儒教の徳と礼による【文治政治】へ転換した。牢人の増加を防ぐため【末期養子の禁】をゆるめ、【殉死】も禁止した。"},
  {"id": "jhx112", "s": "jh", "lv": 2, "topic": "徳川綱吉の政治", "q": "5代将軍徳川綱吉の政治の特徴と、幕府の財政難への対応を説明せよ。", "a": "綱吉は【朱子学】を重んじて湯島聖堂を建て、極端な動物愛護令である【生類憐みの令】を出した。財政難に対しては荻原重秀の意見で金の含有量を減らした【元禄小判】を発行したため、【物価】が上昇した。"},
  {"id": "jhx113", "s": "jh", "lv": 3, "topic": "正徳の政治", "q": "新井白石による正徳の政治は、貨幣と長崎貿易についてどのような政策を行ったか、その目的とともに説明せよ。", "a": "朱子学者の【新井白石】は、元禄小判で上がった物価を抑えるため、質をもとに戻した【正徳小判】を発行した。また金銀の海外流出を防ぐため、【海舶互市新例】を出して長崎貿易での中国・オランダ船の数と貿易額を制限した。"},
  {"id": "jhx114", "s": "jh", "lv": 1, "topic": "江戸時代の農業", "q": "江戸時代前期から中期にかけて、農業生産が大きく伸びたのはなぜか説明せよ。", "a": "幕府や藩が【新田開発】を進めて耕地が大きく増えた。深く耕せる【備中鍬】や脱穀用の【千歯扱】などの農具が普及し、干鰯などの【金肥】も使われた。木綿や菜種などの【商品作物】の栽培も広がった。"},
  {"id": "jhx115", "s": "jh", "lv": 2, "topic": "江戸時代の交通", "q": "江戸時代の陸上交通と海上交通は、どのように整備されたか説明せよ。", "a": "陸上では江戸の日本橋を起点とする【五街道】が整備され、関所や宿駅が置かれた。海上では河村瑞賢が【西廻り航路】・東廻り航路を整え、江戸と大坂の間には【菱垣廻船】や樽廻船が運航した。"},
  {"id": "jhx116", "s": "jh", "lv": 1, "topic": "三都", "q": "江戸時代の三都とよばれた江戸・大坂・京都は、それぞれどのような役割をもっていたか。", "a": "【江戸】は「将軍のお膝元」で政治の中心であった。【大坂】は「天下の台所」とよばれ、諸藩の【蔵屋敷】が置かれて年貢米や特産物が集まった。【京都】には朝廷があり、西陣織など高級手工業の中心であった。"},
  {"id": "jhx117", "s": "jh", "lv": 1, "topic": "元禄文化", "q": "17世紀末から18世紀初めに栄えた元禄文化の担い手と、代表的な作者を説明せよ。", "a": "上方の豊かな【町人】を主な担い手とする文化である。【井原西鶴】は浮世草子で町人の生活を描き、【近松門左衛門】は人形浄瑠璃の脚本を書き、【松尾芭蕉】は俳諧を芸術の域に高めた。"},
  {"id": "jhx118", "s": "jh", "lv": 3, "topic": "江戸時代の儒学", "q": "江戸幕府が朱子学を重んじた理由と、朱子学を批判した儒学の学派について説明せよ。", "a": "朱子学は君臣・父子の別など上下の【身分秩序】を重んじたため、幕府の支配に都合がよく重視された。これに対し、知行合一を説く【陽明学】や、孔子・孟子の原典に立ち返ろうとする【古学】が起こり、伊藤仁斎や【荻生徂徠】らが活躍した。"},
  {"id": "jhx119", "s": "jh", "lv": 2, "topic": "江戸時代の貨幣と金融", "q": "江戸時代の貨幣制度の特徴と、両替商が果たした役割を説明せよ。", "a": "金・銀・銭の【三貨】が流通し、東日本では主に【金】、西日本では主に【銀】で取引が行われた。三貨の交換や為替・貸付を行う【両替商】が発達し、大坂・江戸の大商人は諸藩に金を貸す【大名貸】も行った。"},
  {"id": "whx1", "s": "wh", "lv": 1, "topic": "ハンムラビ法典", "q": "バビロン第1王朝のハンムラビ王が制定した法典の特徴を述べよ。", "a": "メソポタミアを統一した【ハンムラビ王】が制定した。「目には目を、歯には歯を」の【同害復讐】を原則としながら、被害者や加害者の【身分】によって刑罰に差をつけた。"},
  {"id": "whx2", "s": "wh", "lv": 1, "topic": "古代エジプトの王権", "q": "古代エジプトのファラオは、どのような存在として国を支配したか。", "a": "ファラオは太陽神【ラー】の子とされ、生ける神として【神権政治】をおこなった。【ナイル川】の治水と農業を管理する強大な権力をもち、古王国時代には巨大な【ピラミッド】を建設させた。"},
  {"id": "whx3", "s": "wh", "lv": 2, "topic": "アケメネス朝の統治", "q": "アケメネス朝ペルシアは、多様な民族が住む広大な領土をどのように統治したか。", "a": "全国を州に分けて知事【サトラップ】をおき、「王の目」「王の耳」とよばれる監察官に監視させた。幹線道路【王の道】と駅伝制で交通を整え、服属民の宗教や慣習には【寛容】な政策をとった。"},
  {"id": "whx4", "s": "wh", "lv": 2, "topic": "フェニキア人", "q": "フェニキア人の活動は、地中海世界にどのような影響を与えたか。", "a": "【シドン】や【ティルス】を拠点に地中海交易で活躍し、北アフリカに【カルタゴ】などの植民市を建設した。彼らの表音文字はギリシア人に伝わり、【アルファベット】の起源となった。"},
  {"id": "whx5", "s": "wh", "lv": 1, "topic": "ユダヤ教", "q": "ヘブライ人のユダヤ教は、どのような特徴をもつ宗教として成立したか。", "a": "【バビロン捕囚】などの苦難のなかで、唯一神【ヤハウェ】を信じる【一神教】として確立した。自分たちだけが神に救われるとする【選民思想】や、救世主（メシア）を待望する信仰をもった。"},
  {"id": "whx6", "s": "wh", "lv": 1, "topic": "ポリス", "q": "古代ギリシアのポリスとはどのような共同体か、その特徴を述べよ。", "a": "有力者を中心に人々が【集住】して成立した都市国家で、城山の【アクロポリス】と広場の【アゴラ】を中心とした。ポリスは互いに独立していたが、同一民族として【ヘレネス】という意識をもった。"},
  {"id": "whx7", "s": "wh", "lv": 1, "topic": "アテネ民主政", "q": "ペルシア戦争後、ペリクレス時代のアテネで完成した民主政の特徴を述べよ。", "a": "【ペリクレス】の時代に完成し、成年男子市民が【民会】で国政を決める【直接民主政】がおこなわれた。一方で、女性・【奴隷】・在留外人には参政権がなかった。"},
  {"id": "whx8", "s": "wh", "lv": 2, "topic": "民主政の発展", "q": "アテネで平民の発言力が高まり、民主政が発展した背景を述べよ。", "a": "交易で富を得た平民が武具を自弁して【重装歩兵】となり、国防の主力となって発言力を強めた。【ソロンの改革】や【クレイステネスの改革】を経て、【サラミスの海戦】では無産市民も軍船の漕ぎ手として活躍し、民主政が完成に向かった。"},
  {"id": "whx9", "s": "wh", "lv": 2, "topic": "ペロポネソス戦争", "q": "ペロポネソス戦争は、ギリシア世界にどのような結果をもたらしたか。", "a": "【デロス同盟】を率いるアテネと、【ペロポネソス同盟】を率いるスパルタが争い、スパルタが勝利した。その後もポリス間の抗争が続いてポリス社会は衰え、北方の【マケドニア】に支配された。"},
  {"id": "whx10", "s": "wh", "lv": 2, "topic": "ヘレニズム文化", "q": "アレクサンドロス大王の遠征後に生まれたヘレニズム文化の特徴を述べよ。", "a": "【アレクサンドロス大王】の東方遠征後、ギリシア文化がオリエントに広まって生まれた文化。ポリスの枠をこえた【世界市民主義】（コスモポリタニズム）が特徴で、エジプトの【アレクサンドリア】が学術の中心となった。"},
  {"id": "whx11", "s": "wh", "lv": 1, "topic": "スパルタ", "q": "ギリシアのポリスであるスパルタは、どのような体制で国家を維持したか。", "a": "少数の市民が多数の隷属農民【ヘイロータイ】を支配したため、反乱に備えて市民に厳しい軍事訓練を課す【軍国主義】をとった。この体制は【リュクルゴスの制】とよばれ、他国との交流を制限する【鎖国】政策をとった。"},
  {"id": "whx12", "s": "wh", "lv": 1, "topic": "ローマの身分闘争", "q": "共和政ローマで、平民が政治的権利を拡大していった過程を述べよ。", "a": "重装歩兵として国防を担った平民は貴族に対抗し、【護民官】と平民会が設けられた。【十二表法】で慣習法が成文化され、前287年の【ホルテンシウス法】で平民会の議決が国法とされ、平民と貴族は法的に平等となった。"},
  {"id": "whx13", "s": "wh", "lv": 2, "topic": "共和政の動揺", "q": "ポエニ戦争後のローマで、共和政が動揺した理由を社会の変化から述べよ。", "a": "属州から安い穀物が流入し、長期の従軍で疲弊した【中小農民】が没落した。富裕層は奴隷を使う大土地所有【ラティフンディア】を広げた。農民の再建をめざす【グラックス兄弟】の改革は失敗し、【内乱の一世紀】に入った。"},
  {"id": "whx14", "s": "wh", "lv": 1, "topic": "キリスト教の公認", "q": "ローマ帝国でキリスト教が迫害から公認、国教化へと至った過程を述べよ。", "a": "当初は皇帝崇拝を拒んだため迫害されたが、信者は増え続けた。【コンスタンティヌス帝】が313年の【ミラノ勅令】でキリスト教を公認し、392年には【テオドシウス帝】が国教とし、他の宗教を禁止した。"},
  {"id": "whx15", "s": "wh", "lv": 2, "topic": "3世紀の危機", "q": "3世紀のローマ帝国はどのような危機にみまわれ、どのように再建されたか。", "a": "各地の軍団が皇帝を擁立する【軍人皇帝】時代となり、異民族の侵入も重なって帝国は混乱した。【ディオクレティアヌス帝】は皇帝を神格化する【専制君主政】（ドミナトゥス）を始め、帝国を四分統治して秩序を回復した。"},
  {"id": "whx16", "s": "wh", "lv": 2, "topic": "コロナトゥス", "q": "ローマ帝政後期に広がったコロナトゥスとは、どのような生産体制か。", "a": "征服戦争が終わって【奴隷】の供給が減ると、【ラティフンディア】にかわり、没落農民などを小作人の【コロヌス】として使う体制が広がった。コロヌスはやがて土地に縛られ、中世の【農奴】の先駆けとなった。"},
  {"id": "whx17", "s": "wh", "lv": 3, "topic": "ギリシアとローマの市民権", "q": "古代アテネとローマの市民権のあり方を比較し、それが国家の発展に与えた影響を論ぜよ。", "a": "アテネは市民権を【血統】によって厳しく限定し、閉鎖的だった。ローマは征服した都市を【分割統治】しつつ段階的に市民権を与え、【同盟市戦争】を経てイタリア全域に拡大し、212年には【カラカラ帝】が帝国の全自由民に市民権を与え、広大な帝国の統合を支えた。"},
  {"id": "whx18", "s": "wh", "lv": 3, "topic": "ローマ法", "q": "ローマ法はどのように発展し、それが後世にどのような影響を与えたかを述べよ。", "a": "当初はローマ市民にのみ適用される【市民法】だったが、帝国の拡大にともない、あらゆる民族に適用される【万民法】へと発展した。6世紀に【ユスティニアヌス帝】が【ローマ法大全】に集大成し、近代ヨーロッパの法体系の基礎となった。"},
  {"id": "whx19", "s": "wh", "lv": 1, "topic": "ゲルマン人の大移動", "q": "ゲルマン人の大移動はどのように始まり、どのような結果をもたらしたか。", "a": "4世紀後半、アジア系の【フン人】に圧迫された【西ゴート人】がローマ帝国領内に移動したことで始まった。この混乱のなかで【西ローマ帝国】は476年に滅亡し、各地にゲルマン人の国家が建てられた。"},
  {"id": "whx20", "s": "wh", "lv": 3, "topic": "アッシリアとアケメネス朝", "q": "オリエントを統一したアッシリアとアケメネス朝の支配のあり方の違いを論ぜよ。", "a": "アッシリアは鉄製武器と戦車で征服し、服属民の【強制移住】や重税をともなう【武断的な支配】をおこなったため、反乱を招いて短期間で崩壊した。アケメネス朝は【サトラップ】による州制度で統治しつつ、服属民の宗教や慣習に【寛容】で、約200年にわたり広大な領域を維持した。"},
  {"id": "whx21", "s": "wh", "lv": 1, "topic": "インダス文明", "q": "インダス川流域に栄えたインダス文明の特徴を、都市と文字に触れて述べよ。", "a": "前2600年ごろからインダス川流域に栄えた青銅器文明で、【モエンジョ=ダーロ】や【ハラッパー】などの計画的な都市を築いた。都市には排水設備や沐浴場が整えられていた。印章に刻まれた【インダス文字】は未解読である。"},
  {"id": "whx22", "s": "wh", "lv": 1, "topic": "ヴァルナ制", "q": "アーリヤ人の社会で形成されたヴァルナ制とは、どのような身分制度か。", "a": "司祭の【バラモン】を最上位に、武士の【クシャトリヤ】、庶民のヴァイシャ、隷属民の【シュードラ】の4つの身分に分ける制度。のちに世襲の職業集団【ジャーティ】と結びつき、【カースト制度】が形成された。"},
  {"id": "whx23", "s": "wh", "lv": 1, "topic": "仏教の成立", "q": "古代インドで、仏教はどのような背景のもとで成立し、何を説いたか。", "a": "前6世紀ごろ、バラモンの権威や祭式主義への批判が高まるなかで、【ガウタマ=シッダールタ】が開いた。ヴァルナによる差別を否定し、【八正道】の実践による【解脱】を説き、【クシャトリヤ】や商人から支持された。"},
  {"id": "whx24", "s": "wh", "lv": 2, "topic": "アショーカ王", "q": "マウリヤ朝のアショーカ王は、どのような理念にもとづいて統治をおこなったか。", "a": "【カリンガ】征服の悲惨さを反省し、倫理である【ダルマ】（法）による政治を理想とした。【仏教】を保護して【仏典結集】をおこない、各地に詔勅を刻んだ石柱碑や磨崖碑を建てた。"},
  {"id": "whx25", "s": "wh", "lv": 2, "topic": "ガンダーラ美術", "q": "クシャーナ朝の時代に栄えた仏教と仏教美術の特徴について述べよ。", "a": "【カニシカ王】の保護のもと、菩薩信仰により広く人々の救済をめざす【大乗仏教】が広まった。ヘレニズム文化の影響を受けた【ガンダーラ美術】で仏像が作られ、仏教は中央アジアを経て東アジアへ伝わった。"},
  {"id": "whx26", "s": "wh", "lv": 2, "topic": "グプタ朝の文化", "q": "グプタ朝の時代に、インド古典文化が成立したことについて述べよ。", "a": "バラモン教に民間信仰が融合した【ヒンドゥー教】が定着し、【マヌ法典】が完成した。【サンスクリット語】が公用語化され、カーリダーサの『シャクンタラー』などの文学が栄えた。数学では【ゼロの概念】が生まれた。"},
  {"id": "whx27", "s": "wh", "lv": 1, "topic": "周の封建制", "q": "周王朝がおこなった封建制とは、どのような仕組みの統治制度か。", "a": "周王が一族や功臣に【封土】を与えて【諸侯】とし、諸侯は王に貢納と軍役の義務を負った。この主従関係は、父系の血縁集団の規範である【宗法】によって支えられた。"},
  {"id": "whx28", "s": "wh", "lv": 1, "topic": "諸子百家", "q": "春秋・戦国時代に諸子百家が登場した背景と、その主な思想を述べよ。", "a": "【鉄製農具】の普及で生産力が高まり、諸侯が富国強兵のため有能な人材を求めた。こうしたなかで、仁と礼を説く【儒家】、法による統治を説く【法家】、無為自然を説く【道家】など多様な思想家が活躍した。"},
  {"id": "whx29", "s": "wh", "lv": 1, "topic": "始皇帝の統一政策", "q": "中国を統一した秦の始皇帝がおこなった、主な統一政策を述べよ。", "a": "全国に【郡県制】をしいて中央集権化を進め、【貨幣】・度量衡・文字を統一した。【焚書・坑儒】で思想統制をおこない、北方の匈奴に備えて【万里の長城】を修築した。"},
  {"id": "whx30", "s": "wh", "lv": 2, "topic": "郡国制", "q": "前漢の高祖（劉邦）が採用した郡国制とは、どのような統治制度か。", "a": "秦の急激な中央集権化の失敗をふまえ、都の周辺には【郡県制】をしき、地方には一族や功臣を王とする【封建制】を併用した。景帝が【呉楚七国の乱】を鎮圧したことで、実質的に中央集権化が進んだ。"},
  {"id": "whx31", "s": "wh", "lv": 2, "topic": "武帝の政策", "q": "前漢の武帝の対外政策と、それにともなう財政政策について述べよ。", "a": "【匈奴】を攻撃して西域へ進出し、朝鮮やベトナム北部にも郡をおいた。遠征で財政が悪化したため、【塩・鉄・酒の専売】や、物価を調整する【均輸・平準】をおこなった。"},
  {"id": "whx32", "s": "wh", "lv": 2, "topic": "儒学の官学化", "q": "漢代に儒学が国家の学問となった経緯と、それが政治や社会に与えた影響を述べよ。", "a": "武帝は【董仲舒】の献策で【五経博士】をおき、儒学を官学とした。官吏登用法の【郷挙里選】により地方の【豪族】が官界に進出した。後漢では経典の字句を解釈する【訓詁学】が発達した。"},
  {"id": "whx33", "s": "wh", "lv": 3, "topic": "漢とローマの交流", "q": "前2世紀から後2世紀のユーラシア東西交流について、漢とローマの関係に触れて述べよ。", "a": "武帝が【張騫】を大月氏に派遣して西域の事情が知られ、オアシス都市を結ぶ【シルク=ロード】が開けた。後漢の【班超】は西域を経営し、部下を大秦（ローマ）に派遣した。166年には【大秦王安敦】の使者を称する者が海路で日南郡に至った。"},
  {"id": "whx34", "s": "wh", "lv": 3, "topic": "九品中正", "q": "魏で始まった官吏登用法の九品中正が、魏晋南北朝時代の社会に与えた影響を論ぜよ。", "a": "【九品中正】は地方の中正官が人材を九等に評価して推薦する制度だが、実際には有力【豪族】の子弟が高く評価され、「上品に寒門なく、下品に勢族なし」といわれた。官職を独占する【門閥貴族】が形成され、【貴族制社会】が成立した。"},
  {"id": "whx35", "s": "wh", "lv": 1, "topic": "均田制", "q": "北魏の孝文帝が実施した均田制の目的と、その後の展開を述べよ。", "a": "戦乱で荒れた土地を農民に分け与えて耕作させ、【税収】を確保することを目的とした。成人男子のほか、妻や【奴婢】・耕牛にも土地を支給した。隋・唐に受け継がれ、【租調庸制】や【府兵制】の基盤となった。"},
  {"id": "whx36", "s": "wh", "lv": 2, "topic": "孝文帝の漢化政策", "q": "北魏の孝文帝がおこなった漢化政策の内容と、それがもたらした結果を述べよ。", "a": "都を平城から【洛陽】に移し、鮮卑の服装や言語を禁止するなど【漢化政策】を進めた。しかし、これに反発した北辺の軍人たちが【六鎮の乱】を起こし、北魏は東西に分裂した。"},
  {"id": "whx37", "s": "wh", "lv": 1, "topic": "中国への仏教伝来", "q": "魏晋南北朝時代に、仏教が中国に広まった過程を主な人物に触れて述べよ。", "a": "西域から来た【仏図澄】や【鳩摩羅什】が布教や仏典の翻訳をおこない、東晋の【法顕】はインドへ赴いて仏典を持ち帰った。北魏では【雲崗】や竜門に石窟寺院が造営された。"},
  {"id": "whx38", "s": "wh", "lv": 2, "topic": "江南の開発", "q": "魏晋南北朝時代に、長江下流域の江南で開発が進んだ理由を述べよ。", "a": "華北の戦乱を避けて多くの漢人が【江南】に移住し、【東晋】や南朝の諸王朝のもとで開発が進んだ。貴族を担い手とする優雅な【六朝文化】が栄え、のちに【経済の中心】が南に移る基礎となった。"},
  {"id": "whx39", "s": "wh", "lv": 3, "topic": "古代地中海の奴隷制", "q": "古代地中海世界で奴隷が果たした役割を、アテネとローマを対比して論ぜよ。", "a": "アテネでは【債務奴隷】が禁止されたのち、戦争捕虜や購入した奴隷が家内労働や鉱山で働き、市民が政治に参加する余裕を支えた。ローマではポエニ戦争以降、大量の捕虜奴隷が【ラティフンディア】で使役され、【スパルタクスの反乱】のような大反乱も起きた。"},
  {"id": "whx40", "s": "wh", "lv": 3, "topic": "東西ローマの命運", "q": "西ローマ帝国が早くに滅亡した一方、東ローマ帝国が長く存続した理由を論ぜよ。", "a": "西方では都市が衰え、【コロナトゥス】による自給的な経済が広がり、【ゲルマン人】の侵入に抵抗できなかった。東方は【コンスタンティノープル】を中心に商業と【貨幣経済】が維持され、強固な【官僚制】と皇帝権のもとで1000年以上存続した。"},
  {"id": "whx41", "s": "wh", "lv": 1, "topic": "科挙の創設", "q": "隋で始まった科挙は、それまでの官吏登用法と比べてどのような特徴をもっていたか。", "a": "九品中正にかわり、【隋】の文帝が【学科試験】によって広く人材を登用する制度として始めた。家柄によらず能力で官僚を選ぶ点が特徴で、宋代には皇帝みずからが試験官となる【殿試】が加わり、【皇帝】の権力を支える制度となった。"},
  {"id": "whx42", "s": "wh", "lv": 1, "topic": "唐の律令体制", "q": "唐が整えた律令体制とは、どのような仕組みで国家を運営する体制か。", "a": "刑法の【律】と行政法の【令】にもとづく統治体制。中央に【三省・六部】をおき、土地制度の【均田制】、税制の【租調庸制】、兵制の府兵制を組み合わせて運営された。"},
  {"id": "whx43", "s": "wh", "lv": 2, "topic": "両税法", "q": "唐の後半に両税法が施行された背景と、その課税の仕組みを述べよ。", "a": "均田制がくずれて農民の逃亡が増え、【租調庸制】が維持できなくなった。780年、宰相楊炎の献策で【両税法】が施行され、実際に所有する土地や資産に応じて【夏と秋の2回】課税した。これは【大土地所有】を事実上認める転換となった。"},
  {"id": "whx44", "s": "wh", "lv": 1, "topic": "安史の乱", "q": "8世紀半ばにおこった安史の乱は、唐の政治と社会にどのような影響を与えたか。", "a": "755年に【節度使】の安禄山らが起こした反乱で、唐はウイグルの援助を得て鎮圧した。乱後は節度使が地方で自立して【藩鎮】となり、中央の統制が弱まった。財政難を補うため【塩の専売】が強化された。"},
  {"id": "whx45", "s": "wh", "lv": 2, "topic": "国際都市長安", "q": "唐の都長安が国際都市として栄えた理由と、その文化の特徴を述べよ。", "a": "唐は周辺諸国と【冊封】関係を結び、【シルク=ロード】や海路を通じて各地から商人や留学生が集まった。長安には【ゾロアスター教】やネストリウス派キリスト教、マニ教の寺院が建てられ、国際色豊かな【貴族文化】が栄えた。"},
  {"id": "whx46", "s": "wh", "lv": 1, "topic": "宋の文治主義", "q": "宋の太祖（趙匡胤）が採用した文治主義とは、どのような政策か。", "a": "五代の武人政治の弊害をふまえ、【節度使】の権限を弱めて文官を重視した。【科挙】を整備して【殿試】を設け、皇帝による【君主独裁体制】を確立した。一方で軍事力が弱まり、北方民族の圧迫を受けた。"},
  {"id": "whx47", "s": "wh", "lv": 2, "topic": "王安石の新法", "q": "北宋の王安石がおこなった新法の目的と、その主な内容を述べよ。", "a": "財政難と軍事力の低下を克服する【富国強兵】を目的とした。中小農民に低利で資金を貸す【青苗法】、中小商人を助ける【市易法】、農閑期に農民を訓練する【保甲法】などを実施したが、【旧法党】の反対で激しい党争を招いた。"},
  {"id": "whx48", "s": "wh", "lv": 1, "topic": "宋代の経済発展", "q": "宋代の中国で経済が大きく発展したことについて、農業と商業の面から述べよ。", "a": "江南ではひでりに強い【占城稲】の導入などで稲作が発展し、「蘇湖熟すれば天下足る」といわれた。商業では草市や鎮などの商業都市が成長し、紙幣の【交子】が使われた。商人の同業組合【行】や手工業者の【作】も結成された。"},
  {"id": "whx49", "s": "wh", "lv": 2, "topic": "士大夫", "q": "宋代に新たな支配層となった士大夫とは、どのような人々か説明せよ。", "a": "唐末五代に門閥貴族が没落したのち、新興地主層の【形勢戸】が台頭した。彼らは【科挙】に合格して官僚となり、儒学的教養を身につけた【士大夫】として政治と文化を担った。官僚を出した家は【官戸】として特権を得た。"},
  {"id": "whx50", "s": "wh", "lv": 2, "topic": "朱子学", "q": "南宋の朱熹が大成した朱子学の特徴と、その後の東アジアへの影響を述べよ。", "a": "宇宙の原理である【理】と、万物を構成する【気】によって世界を説明し、君臣・華夷の区別を重んじる【大義名分論】を説いた。四書を重視し、明代には科挙の基準とされ、朝鮮や日本でも【官学】として受容された。"},
  {"id": "whx51", "s": "wh", "lv": 1, "topic": "宋と北方民族", "q": "北宋・南宋と北方民族の国家との関係について、遼と金を中心に述べよ。", "a": "北宋は契丹の【遼】と【澶淵の盟】を結び、毎年銀や絹を贈った。のち女真の【金】と結んで遼を滅ぼしたが、金に都の開封を攻略される【靖康の変】で滅亡した。江南に逃れた南宋は金に臣下の礼をとった。"},
  {"id": "whx52", "s": "wh", "lv": 3, "topic": "征服王朝の統治", "q": "遼と金が中国の農耕地帯を支配する際に用いた統治体制の特徴を論ぜよ。", "a": "遼は遊牧民を部族制で、農耕民を州県制で治める【二重統治体制】をとり、【契丹文字】を作って民族の独自性を保った。金も女真人を軍事・行政組織の【猛安・謀克】で、漢人を州県制で治めた。両国とも漢文化を受容しつつ、固有の文化と体制を維持しようとした。"},
  {"id": "whx53", "s": "wh", "lv": 2, "topic": "元の中国支配", "q": "元が中国を支配する際にとった統治の特徴を、民族の扱いに触れて述べよ。", "a": "要職はモンゴル人が独占し、中央アジア・西アジア出身の【色目人】が財務官僚として重用された。旧金領の住民は【漢人】、旧南宋の住民は【南人】とよばれた。【科挙】は一時停止され、儒学的教養をもつ士大夫は政治の中枢から遠ざけられた。"},
  {"id": "whx54", "s": "wh", "lv": 1, "topic": "元の滅亡", "q": "中国を支配した元が、14世紀に衰退して北方へ退いた理由を述べよ。", "a": "帝位争いが続き、チベット仏教への過剰な保護で財政が悪化した。不足を補うため紙幣の【交鈔】を乱発して物価が高騰し、民衆が困窮した。白蓮教徒を中心とする【紅巾の乱】がおこり、【朱元璋】が明を建てると、元は北方へ退いた。"},
  {"id": "whx55", "s": "wh", "lv": 1, "topic": "洪武帝の政策", "q": "明の洪武帝が皇帝独裁と農村支配を強化するためにおこなった政策を述べよ。", "a": "【中書省】を廃止して六部を皇帝直属とし、【皇帝独裁】を強化した。農村には【里甲制】をしき、租税台帳の【賦役黄冊】と土地台帳の【魚鱗図冊】を作成した。民衆教化のため六諭も定めた。"},
  {"id": "whx56", "s": "wh", "lv": 1, "topic": "鄭和の南海遠征", "q": "明の永楽帝が鄭和に命じた南海遠征の目的と、その影響を述べよ。", "a": "【永楽帝】はイスラーム教徒の宦官【鄭和】に大艦隊を率いさせ、東南アジアからアフリカ東岸まで派遣した。諸国に【朝貢】をうながし、明を中心とする国際秩序を広げることが目的だった。遠征の拠点となった【マラッカ】は中継港として発展した。"},
  {"id": "whx57", "s": "wh", "lv": 2, "topic": "明の海禁", "q": "明がおこなった海禁政策とはどのようなものか、その目的と結果を述べよ。", "a": "民間人の海外渡航や交易を禁止し、貿易を国家間の【朝貢貿易】に限定した政策。【倭寇】の取り締まりと国家による貿易独占が目的だった。しかし密貿易はやまず、16世紀に【後期倭寇】が活発化したため、明は【海禁】を緩和した。"},
  {"id": "whx58", "s": "wh", "lv": 2, "topic": "北虜南倭", "q": "16世紀の明を苦しめた「北虜南倭」とは何か、その影響とともに説明せよ。", "a": "北方では【モンゴル】の【アルタン=ハーン】が侵入をくり返し、北京を包囲した。南方の沿岸では中国人を主体とする【倭寇】が密貿易や略奪をおこなった。これらへの防衛費が明の【財政】を圧迫した。"},
  {"id": "whx59", "s": "wh", "lv": 1, "topic": "明清交替", "q": "17世紀前半に明が滅亡し、清が中国支配を始めた経緯を述べよ。", "a": "豊臣秀吉の朝鮮出兵への援軍や女真との戦いで財政が悪化し、重税で民衆が困窮した。1644年、【李自成の乱】で北京が陥落し明は滅亡した。山海関を守っていた【呉三桂】が清に降り、【清】が北京に入って中国支配を始めた。"},
  {"id": "whx60", "s": "wh", "lv": 1, "topic": "清の漢人統治", "q": "清が漢人を支配するために用いた懐柔策と威圧策について述べよ。", "a": "懐柔策として、要職に満洲人と漢人を同数任命する【満漢併用制】をとり、『四庫全書』などの大編纂事業で知識人を優遇した。威圧策として、満洲人の髪型である【辮髪】を強制し、【文字の獄】や禁書で反清思想を弾圧した。"},
  {"id": "whx61", "s": "wh", "lv": 2, "topic": "康熙帝", "q": "清の康熙帝が支配を安定させるためにおこなった内政・外交の政策を述べよ。", "a": "漢人武将が南方で起こした【三藩の乱】を鎮圧し、【鄭氏台湾】を降して中国全土を平定した。北方ではロシアと【ネルチンスク条約】を結んで国境を定め、通商を認めた。"},
  {"id": "whx62", "s": "wh", "lv": 2, "topic": "地丁銀制", "q": "清代に実施された地丁銀制とは、どのような税制か、その影響とともに述べよ。", "a": "明の一条鞭法を受けつぎ、【人頭税】（丁税）を【土地税】（地税）にくりこんで一本化した税制。康熙帝が丁税額を固定したのち、【雍正帝】の時代に全国に広まった。人頭税が事実上廃止され、【人口】の急増を後押しした。"},
  {"id": "whx63", "s": "wh", "lv": 3, "topic": "清の藩部統治", "q": "清はモンゴル・チベット・新疆などの地域をどのように統治したかを論ぜよ。", "a": "これらの地域を【藩部】とし、【理藩院】に管轄させた。現地の有力者に自治を認め、モンゴルの王侯やチベット仏教の権威を利用する間接統治をおこなった。清の皇帝はモンゴルに対しては遊牧君主の【ハーン】として、チベットに対しては仏教の保護者としてふるまった。"},
  {"id": "whx64", "s": "wh", "lv": 1, "topic": "新羅の統一", "q": "7世紀に朝鮮半島を統一した新羅について、統一の過程と社会の特徴を述べよ。", "a": "新羅は唐と結んで【百済】と【高句麗】を滅ぼし、その後唐の勢力を排除して半島を統一した。唐の律令制を取り入れる一方、血統による厳格な身分制度である【骨品制】が社会を支え、都の慶州では【仏教】文化が栄えた。"},
  {"id": "whx65", "s": "wh", "lv": 2, "topic": "高麗の文化", "q": "10世紀に朝鮮半島で成立した高麗の時代に生まれた文化について述べよ。", "a": "仏教が国家の保護を受け、モンゴルの侵入からの加護を願って【高麗版大蔵経】が刊行された。世界最古級の【金属活字】も作られ、宋の影響を受けた【高麗青磁】が名品として知られた。"},
  {"id": "whx66", "s": "wh", "lv": 1, "topic": "朝鮮王朝", "q": "14世紀末に朝鮮半島で成立した朝鮮王朝の政治と文化について述べよ。", "a": "倭寇の撃退で名声を得た【李成桂】が建てた。【朱子学】を官学とし、科挙で官僚を選んだが、官僚を輩出した【両班】が特権身分となった。15世紀に世宗は表音文字の【訓民正音】（ハングル）を制定した。"},
  {"id": "whx67", "s": "wh", "lv": 2, "topic": "突厥とウイグル", "q": "6〜9世紀にモンゴル高原で活躍した突厥とウイグルについて述べよ。", "a": "【突厥】は6世紀に柔然を倒して強大化し、独自の【突厥文字】を作った。8世紀には【ウイグル】が台頭し、【安史の乱】で唐を援助した。ウイグルはソグド人と結びつき、【マニ教】を信仰した。"},
  {"id": "whx68", "s": "wh", "lv": 2, "topic": "ソグド人", "q": "ソグド人が内陸アジアの東西交流において果たした役割を述べよ。", "a": "中央アジアの【サマルカンド】などのオアシス都市を拠点に、【シルク=ロード】の交易で活躍したイラン系の民族。遊牧国家や唐と結びついて活動し、【ソグド文字】は【ウイグル文字】の起源となった。"},
  {"id": "whx69", "s": "wh", "lv": 3, "topic": "遊牧国家とオアシス都市", "q": "内陸アジアにおいて、遊牧国家とオアシス都市がどのような関係を結んでいたかを論ぜよ。", "a": "【遊牧国家】は騎馬軍事力でオアシス都市を保護・支配し、オアシス都市は【隊商交易】の利益や農産物を提供した。遊牧国家は中国王朝から絹などを【貢納】や交易で獲得し、オアシスの商人がそれを西方へ運んだ。両者は互いに依存する【共生関係】にあった。"},
  {"id": "whx70", "s": "wh", "lv": 3, "topic": "唐宋変革", "q": "唐から宋の時代に中国社会がどのように変わったのか、支配層と経済の変化から論ぜよ。", "a": "唐末の戦乱で【門閥貴族】が没落し、宋では【科挙】出身の官僚と新興地主の【形勢戸】が支配層となった。土地制度は均田制から小作人の【佃戸】を使う地主制に移り、商業では坊市制がくずれて【貨幣経済】が発展した。"},
  {"id": "whx71", "s": "wh", "lv": 3, "topic": "明清の貿易体制", "q": "明から清にかけて、中国の対外貿易体制がどのように変化したかを論ぜよ。", "a": "明初は【海禁】と【朝貢貿易】によって国家が貿易を独占したが、16世紀後半に海禁を緩めて民間貿易を許した。清は台湾の鄭氏を降すと海禁を解き、民間の【互市】を広く認めたが、18世紀半ばにはヨーロッパとの貿易を【広州】一港に限定した。"},
  {"id": "whx72", "s": "wh", "lv": 1, "topic": "宋代の文化", "q": "宋代の中国文化の特徴を、印刷などの技術と美術の面から述べよ。", "a": "【木版印刷】が普及して書物が広まり、【羅針盤】や【火薬】が実用化された。絵画では宮廷画家による院体画と、士大夫による【文人画】が描かれ、陶磁器では【青磁】や白磁が作られた。"},
  {"id": "whx73", "s": "wh", "lv": 1, "topic": "明代の文化", "q": "明代後期の中国文化の特徴を、儒学などの学問と庶民文化の面から述べよ。", "a": "【王守仁】（王陽明）は知識と実践の一致を説く【陽明学】をおこした。実用的な学問も重視され、『本草綱目』や『天工開物』が著された。庶民の間では『西遊記』『水滸伝』などの口語【小説】が広く読まれた。"},
  {"id": "whx74", "s": "wh", "lv": 2, "topic": "イエズス会宣教師", "q": "明末清初に中国で活動したイエズス会宣教師の役割と、その後の布教禁止について述べよ。", "a": "【マテオ=リッチ】は世界地図「坤輿万国全図」を作り、徐光啓と『幾何原本』を訳した。【アダム=シャール】らは暦の作成に関わった。のち布教方法をめぐる【典礼問題】がおこり、【雍正帝】はキリスト教の布教を禁止した。"},
  {"id": "whx75", "s": "wh", "lv": 2, "topic": "考証学", "q": "清代の中国で考証学が盛んになった背景と、その学風の特徴を述べよ。", "a": "明末清初の【顧炎武】らは、空論におちいった陽明学を批判し、経書を実証的に研究する学風をおこした。清の【文字の獄】による思想統制で政治的な議論が難しくなると、学者は古典の文献研究に向かい、【考証学】が隆盛した。"},
  {"id": "whx76", "s": "wh", "lv": 1, "topic": "隋の滅亡", "q": "南北朝を統一した隋が、わずか30年ほどで滅亡した理由を述べよ。", "a": "第2代の【煬帝】は【大運河】の建設などの大土木事業や、3度にわたる【高句麗遠征】をおこなった。重い負担に苦しむ民衆の反乱が各地でおこり、隋は統一から約30年で滅亡した。"},
  {"id": "whx77", "s": "wh", "lv": 2, "topic": "冊封体制", "q": "中国王朝が周辺諸国と結んだ冊封体制とは、どのような国際関係か。", "a": "中国皇帝が周辺諸国の君主に【官爵】を与えて君臣関係を結び、君主は皇帝に【朝貢】した。皇帝の徳が周辺に及ぶとする【中華思想】にもとづく秩序で、周辺国は権威の承認と【交易】の利益を得た。"},
  {"id": "whx78", "s": "wh", "lv": 1, "topic": "白蓮教徒の乱", "q": "18世紀末に清でおこった白蓮教徒の乱の背景と、その影響を述べよ。", "a": "18世紀の【人口】急増で耕地が不足し、山間部に移住した貧民が【白蓮教】を信仰して反乱をおこした。正規軍の【八旗】は役に立たず、【郷勇】とよばれる義勇軍によって鎮圧された。財政も悪化し、清の衰退が始まった。"},
  {"id": "whx79", "s": "wh", "lv": 3, "topic": "明清の江南経済", "q": "明代後期から清代にかけて、長江流域の経済構造がどのように変化したかを論ぜよ。", "a": "長江下流域では【綿織物】や【生糸】などの家内手工業が発達し、商品作物の栽培が広がった。そのため穀倉地帯は中流域に移り「【湖広熟すれば天下足る】」といわれた。【山西商人】や【徽州商人】など、遠隔地商業で富を得た商人が活躍した。"},
  {"id": "whx80", "s": "wh", "lv": 1, "topic": "イスラーム教の成立", "q": "7世紀にムハンマドが創始したイスラーム教の特徴と、その成立の過程を述べよ。", "a": "【メッカ】の商人ムハンマドが唯一神【アッラー】の啓示を受けたとして始めた。神の前での信者の平等を説き、偶像崇拝を厳しく禁じた。迫害を受けて622年にメディナへ移住した【ヒジュラ】（聖遷）がイスラーム暦の元年とされ、教えは聖典【コーラン】にまとめられた。"},
  {"id": "whx81", "s": "wh", "lv": 1, "topic": "正統カリフ時代", "q": "ムハンマドの死後、正統カリフ時代にイスラーム勢力がどのように拡大したかを述べよ。", "a": "信者の合意で選ばれた【カリフ】が共同体を指導した。【ジハード】（聖戦）による大征服でビザンツ帝国からシリアやエジプトを奪い、イランの【ササン朝】を滅ぼした。征服地の異教徒には人頭税の【ジズヤ】と地租の【ハラージュ】を課した。"},
  {"id": "whx82", "s": "wh", "lv": 2, "topic": "スンナ派とシーア派", "q": "イスラーム教のスンナ派とシーア派は、どのような点で考え方が異なるかを説明せよ。", "a": "【シーア派】は第4代正統カリフの【アリー】とその子孫だけを正統な指導者（イマーム）とする。一方、多数派の【スンナ派】は歴代カリフの権威を認め、ムハンマドの言行（スンナ）に従う共同体の合意を重視する。"},
  {"id": "whx83", "s": "wh", "lv": 2, "topic": "知恵の館と翻訳", "q": "アッバース朝の時代に学問が発達した理由と、それがヨーロッパに与えた影響を述べよ。", "a": "都【バグダード】の【知恵の館】でギリシア語文献がアラビア語に翻訳され、哲学・医学・天文学が発達した。【イブン=シーナー】の『医学典範』などは、のちに【ラテン語】に翻訳されて西欧に伝わり、【12世紀ルネサンス】をもたらした。"},
  {"id": "whx84", "s": "wh", "lv": 2, "topic": "3カリフの並立", "q": "10世紀のイスラーム世界で、3人のカリフが並び立った経緯を述べよ。", "a": "アッバース朝のカリフに対し、北アフリカに興ったシーア派の【ファーティマ朝】の君主がカリフを称し、イベリア半島の【後ウマイヤ朝】の君主もカリフを称した。さらに、バグダードはシーア派の【ブワイフ朝】に占領され、アッバース朝カリフの政治的権威は低下した。"},
  {"id": "whx85", "s": "wh", "lv": 2, "topic": "セルジューク朝", "q": "11世紀に成立したセルジューク朝が、イスラーム世界で果たした役割について述べよ。", "a": "トルコ系の【セルジューク朝】は1055年にバグダードに入り、カリフから【スルタン】の称号を得て政治権力を握った。アナトリアに進出してビザンツ帝国を圧迫し、これが【十字軍】のきっかけとなった。軍人に徴税権を与える【イクター制】を広く施行した。"},
  {"id": "whx86", "s": "wh", "lv": 3, "topic": "イクター制", "q": "イスラーム世界におけるイクター制の成立と、その特徴を西欧の封建制と比べて論ぜよ。", "a": "【ブワイフ朝】が軍人に俸給のかわりに土地の【徴税権】を与えたことで始まり、【セルジューク朝】が広く施行した。現金収入の不足に対応して軍事力を維持する制度だった。西欧の封建制と異なり、原則として【世襲】は認められず、国家による土地支配が維持された。"},
  {"id": "whx87", "s": "wh", "lv": 1, "topic": "オスマン帝国の拡大", "q": "オスマン帝国が14〜16世紀に勢力を拡大した過程を、主な君主に触れて述べよ。", "a": "バルカン半島へ進出し、1453年に【メフメト2世】が【コンスタンティノープル】を攻略してビザンツ帝国を滅ぼした。セリム1世はマムルーク朝を滅ぼして聖地を支配下におき、【スレイマン1世】の時代には【ウィーン】を包囲するなど最盛期を迎えた。"},
  {"id": "whx88", "s": "wh", "lv": 2, "topic": "オスマン帝国の統治", "q": "オスマン帝国は、多民族・多宗教の人々をどのように統治したかを述べよ。", "a": "キリスト教徒やユダヤ教徒の宗教共同体【ミッレト】に、納税と引きかえに自治を認めた。キリスト教徒の子弟を強制的に集める【デヴシルメ】で官僚や常備歩兵軍の【イェニチェリ】を養成し、騎士には【ティマール制】で徴税権を与えた。"},
  {"id": "whx89", "s": "wh", "lv": 2, "topic": "サファヴィー朝", "q": "16世紀初めにイランで成立したサファヴィー朝の特徴を述べよ。", "a": "神秘主義教団の長イスマーイールが建国し、【シーア派】を国教としてスンナ派のオスマン帝国と対立した。君主はイラン伝統の【シャー】の称号を用いた。【アッバース1世】は新都【イスファハーン】を建設し、「世界の半分」といわれるほど繁栄した。"},
  {"id": "whx90", "s": "wh", "lv": 1, "topic": "アクバルの統治", "q": "ムガル帝国のアクバルが、多数のヒンドゥー教徒を統治するためにおこなった政策を述べよ。", "a": "【アクバル】は非ムスリムに課される人頭税の【ジズヤ】を廃止し、ヒンドゥー教徒の【ラージプート】の王女と結婚するなど融和を図った。官僚の位階に応じて給与と保持すべき騎兵数を定める【マンサブダール制】で支配体制を整えた。"},
  {"id": "whx91", "s": "wh", "lv": 2, "topic": "アウラングゼーブ", "q": "ムガル帝国のアウラングゼーブ帝の宗教政策は、帝国にどのような影響を与えたか。", "a": "熱心なスンナ派ムスリムの【アウラングゼーブ】は、【ジズヤ】を復活させるなどヒンドゥー教徒を圧迫した。そのため【ラージプート】やデカン高原の【マラーター】、パンジャーブの【シク教徒】の反抗を招き、彼の死後、帝国は急速に衰退した。"},
  {"id": "whx92", "s": "wh", "lv": 2, "topic": "インド=イスラーム文化", "q": "ムガル帝国時代に生まれたインド=イスラーム文化の特徴を述べよ。", "a": "イスラーム文化とインドの文化が融合した文化。建築ではシャー=ジャハーンが造った【タージ=マハル】、絵画ではペルシアの影響を受けた【細密画】が発達した。言語では【ウルドゥー語】が生まれ、宗教ではナーナクが【シク教】を開いた。"},
  {"id": "whx93", "s": "wh", "lv": 1, "topic": "インドのイスラーム化", "q": "10世紀以降、北インドにイスラーム教が広まった過程を述べよ。", "a": "10世紀末から【ガズナ朝】や【ゴール朝】が北インドに侵入した。13世紀には【奴隷王朝】がデリーを都として成立し、以後の五王朝は【デリー=スルタン朝】とよばれた。神との合一をめざす【神秘主義】（スーフィズム）の聖者の活動で、民衆にも改宗が広まった。"},
  {"id": "whx94", "s": "wh", "lv": 3, "topic": "東南アジアのイスラーム化", "q": "13世紀以降、東南アジアの島嶼部にイスラーム教が広まった経緯を論ぜよ。", "a": "インド洋交易に従事する【ムスリム商人】の来航とともに、港市の支配者が改宗していった。15世紀には【マラッカ王国】が国王の改宗によってイスラーム化し、交易の拠点として布教の中心となった。その後、スマトラの【アチェ王国】やジャワの【マタラム王国】などのイスラーム国家が成立した。"},
  {"id": "whx95", "s": "wh", "lv": 1, "topic": "アンコール朝", "q": "9世紀以降カンボジアで栄えたアンコール朝の特徴を、建造物に触れて述べよ。", "a": "クメール人が建てた王朝で、インドから伝わった【ヒンドゥー教】や仏教の影響を受けた。12世紀にはヒンドゥー教寺院の【アンコール=ワット】が造営され、のちに仏教色の強い都城【アンコール=トム】も建てられた。"},
  {"id": "whx96", "s": "wh", "lv": 2, "topic": "シュリーヴィジャヤ", "q": "7世紀にスマトラ島を中心に栄えたシュリーヴィジャヤが繁栄した理由を述べよ。", "a": "【マラッカ海峡】を押さえる位置にあり、中国とインドを結ぶ【海上交易】の中継で栄えた【港市国家】である。唐の僧【義浄】がインドへの往復で滞在して記録を残したように、仏教が盛んだった。"},
  {"id": "whx97", "s": "wh", "lv": 2, "topic": "東南アジアのインド化", "q": "東南アジアの「インド化」とはどのような現象か、具体例を挙げて述べよ。", "a": "交易を通じて、インドから【ヒンドゥー教】や【仏教】、サンスクリット語、神聖な王権の観念などが受け入れられた現象。ジャワ島の【シャイレンドラ朝】は大乗仏教の寺院【ボロブドゥール】を建設した。"},
  {"id": "whx98", "s": "wh", "lv": 2, "topic": "ベトナムの諸王朝", "q": "中国の支配から独立したベトナムの諸王朝と、中国との関係について述べよ。", "a": "10世紀に独立し、11世紀に【李朝】が大越国を建てた。【陳朝】は元の侵攻を撃退し、漢字をもとに独自の文字【チュノム】（字喃）を作った。15世紀の【黎朝】は明の支配を退けたのち、明の制度を取り入れて中央集権化を進めた。"},
  {"id": "whx99", "s": "wh", "lv": 1, "topic": "上座部仏教の広がり", "q": "東南アジアの大陸部に、スリランカから上座部仏教が広まったことについて述べよ。", "a": "11世紀以降、ビルマの【パガン朝】やタイの【スコータイ朝】、のちの【アユタヤ朝】で、スリランカから伝わった【上座部仏教】が信仰された。上座部仏教は王権と結びつき、民衆の間にも定着した。"},
  {"id": "whx100", "s": "wh", "lv": 1, "topic": "西アフリカの諸王国", "q": "西アフリカのガーナ王国やマリ王国が繁栄した理由を、交易品に触れて述べよ。", "a": "サハラ砂漠をこえる【サハラ縦断交易】で、西アフリカの【金】と北方の【岩塩】を交換して栄えた。マリ王国の【マンサ=ムーサ】はメッカ巡礼で大量の金を使い、その富を広く知らせた。【トンブクトゥ】は交易と学問の中心となった。"},
  {"id": "whx101", "s": "wh", "lv": 2, "topic": "スワヒリ文化", "q": "東アフリカ沿岸の海港都市の繁栄と、そこで生まれた文化について述べよ。", "a": "【マリンディ】や【キルワ】などの海港都市が、【ムスリム商人】による【インド洋交易】で栄えた。現地のバントゥー系言語にアラビア語の語彙が加わった【スワヒリ語】が共通語として広まった。"},
  {"id": "whx102", "s": "wh", "lv": 2, "topic": "大ジンバブエ", "q": "アフリカ南部のジンバブエ高原で栄えた国家と、大ジンバブエ遺跡について述べよ。", "a": "ショナ人の国家が【金】や象牙の輸出で栄え、巨大な石造建築の【大ジンバブエ遺跡】を残した。遺跡からは【インド洋交易】を通じてもたらされた中国の陶磁器も出土している。15世紀以降は【モノモタパ王国】が栄えた。"},
  {"id": "whx103", "s": "wh", "lv": 3, "topic": "アフリカのイスラーム化", "q": "中世のアフリカで、イスラーム教が受容された経路と、その特徴を論ぜよ。", "a": "西アフリカでは【サハラ縦断交易】を通じてムスリム商人が来訪し、【マリ王国】や【ソンガイ王国】の支配層が改宗した。東アフリカ沿岸では【インド洋交易】を通じてイスラームが浸透し、【スワヒリ文化】が生まれた。いずれも交易を担う商人と、王権や都市の支配層を通じて広まった。"},
  {"id": "whx104", "s": "wh", "lv": 1, "topic": "カールの戴冠", "q": "カール大帝の戴冠は、ヨーロッパ史においてどのような意義をもつか述べよ。", "a": "800年、教皇【レオ3世】がフランク王【カール大帝】にローマ皇帝の冠を与えた。これにより【ローマ=カトリック教会】とゲルマン人の国家が結びつき、ビザンツ帝国から自立した【西ヨーロッパ世界】が成立した。"},
  {"id": "whx105", "s": "wh", "lv": 1, "topic": "封建的主従関係", "q": "中世西ヨーロッパの封建的主従関係とは、どのような関係かを説明せよ。", "a": "主君が家臣に【封土】を与えて保護し、家臣は主君に【軍事的奉仕】の義務を負う関係。双方が義務を負う【双務的契約】である点が特徴で、一人の家臣が複数の主君に仕えることもあった。"},
  {"id": "whx106", "s": "wh", "lv": 1, "topic": "荘園と農奴", "q": "中世西ヨーロッパの荘園において、農民はどのような立場におかれていたか。", "a": "農民の多くは移動の自由のない【農奴】で、領主直営地での【賦役】と、保有地からの生産物を納める【貢納】の義務を負った。結婚税や死亡税も課された。領主は国王の役人の立ち入りや課税を拒む【不輸不入権】をもち、荘園を支配した。"},
  {"id": "whx107", "s": "wh", "lv": 2, "topic": "叙任権闘争", "q": "11〜12世紀の叙任権闘争とはどのような争いか、その経過と結果を述べよ。", "a": "聖職者の任命権をめぐる教皇と神聖ローマ皇帝の争い。教皇【グレゴリウス7世】が皇帝【ハインリヒ4世】を破門し、皇帝が教皇に謝罪する【カノッサの屈辱】がおこった。1122年の【ヴォルムス協約】で、叙任権は教皇がもつことが確認された。"},
  {"id": "whx108", "s": "wh", "lv": 2, "topic": "中世都市の自治", "q": "中世西ヨーロッパで都市が発達した背景と、都市の自治について述べよ。", "a": "農業生産力の向上で余剰生産物が生まれ、【商業の復活】が進んで都市が発達した。都市は皇帝や国王から【特許状】を得て自治権を獲得した。北イタリアの【コムーネ】やドイツの【自由都市】が成立し、【ハンザ同盟】などの都市同盟も結ばれた。"},
  {"id": "whx109", "s": "wh", "lv": 2, "topic": "ギルド", "q": "中世都市のギルドとはどのような組織か、その特徴と都市政治への影響を述べよ。", "a": "商人や手工業者の同業組合。【同職ギルド】では親方だけが組合員となり、職人や徒弟を従えた。自由な競争を禁止し、製品の品質・価格・生産量を統制した。市政を独占した【商人ギルド】に対し、手工業者は【ツンフト闘争】をおこして市政への参加を実現した。"},
  {"id": "whx110", "s": "wh", "lv": 1, "topic": "黒死病", "q": "14世紀にヨーロッパで流行した黒死病は、社会にどのような影響を与えたか。", "a": "人口の約3分の1が失われ、労働力不足から農民の地位が向上し、イギリスでは【独立自営農民】（ヨーマン）が成長した。領主が再び束縛を強めると【ジャックリーの乱】や【ワット=タイラーの乱】がおこり、【封建社会】は解体に向かった。"},
  {"id": "whx111", "s": "wh", "lv": 2, "topic": "百年戦争", "q": "14〜15世紀の百年戦争の原因と、それが英仏両国に与えた影響を述べよ。", "a": "フランスの王位継承問題と、毛織物産業の盛んな【フランドル地方】の支配をめぐって英仏が争った。【ジャンヌ=ダルク】の活躍もありフランスが勝利した。戦争で両国の諸侯や騎士が没落し、【中央集権化】が進んだ。イギリスではその後【バラ戦争】がおこった。"},
  {"id": "whx112", "s": "wh", "lv": 1, "topic": "教皇権の衰退", "q": "13世紀末以降、ローマ教皇の権威が衰退していった経過を述べよ。", "a": "フランス王【フィリップ4世】が教皇ボニファティウス8世をとらえる【アナーニ事件】がおこった。その後、教皇庁が南フランスのアヴィニョンに移される【教皇のバビロン捕囚】が続き、さらに複数の教皇が並び立つ【教会大分裂】がおこった。"},
  {"id": "whx113", "s": "wh", "lv": 2, "topic": "ビザンツ帝国", "q": "東ローマ（ビザンツ）帝国の政治体制の特徴と、その文化について述べよ。", "a": "皇帝が政治と宗教の両方の最高権力をもつ【皇帝教皇主義】をとった。7世紀以降、異民族の侵入に対して【軍管区制】（テマ制）をしき、【屯田兵制】で防衛した。ギリシア正教とギリシア古典文化を融合した文化が栄え、【ハギア=ソフィア聖堂】が建てられた。"},
  {"id": "whx114", "s": "wh", "lv": 2, "topic": "東西教会の分裂", "q": "キリスト教会がローマ=カトリック教会とギリシア正教会に分裂した経緯を述べよ。", "a": "726年、ビザンツ皇帝レオン3世が【聖像禁止令】を出すと、ゲルマン人への布教に聖像を用いていたローマ教会が反発し、フランク王国に接近した。両教会の対立は深まり、1054年に【ローマ=カトリック教会】と【ギリシア正教会】に分裂した。"},
  {"id": "whx115", "s": "wh", "lv": 1, "topic": "ノルマン人の移動", "q": "9〜11世紀のノルマン人の移動は、ヨーロッパ各地にどのような国家を生んだか。", "a": "北フランスに【ノルマンディー公国】を建て、そこから【ノルマン=コンクェスト】でイングランドを征服した。南イタリアとシチリアには【両シチリア王国】を建て、東ではルーシの一派が【ノヴゴロド国】を建てた。"},
  {"id": "whx116", "s": "wh", "lv": 2, "topic": "イギリス議会の起源", "q": "中世イングランドで、議会政治の基礎が形成された過程を13世紀を中心に述べよ。", "a": "ジョン王は貴族らの要求で1215年に【大憲章】（マグナ=カルタ）を認め、課税には貴族の同意が必要とされた。13世紀後半の【シモン=ド=モンフォール】の議会を経て、エドワード1世が【模範議会】を招集した。14世紀には貴族院と庶民院の【二院制】が成立した。"},
  {"id": "whx117", "s": "wh", "lv": 3, "topic": "中世の農業革命", "q": "11〜13世紀の西ヨーロッパで農業生産力が向上した理由と、その社会的影響を論ぜよ。", "a": "秋耕地・春耕地・休耕地を輪作する【三圃制】や、牛馬に引かせる【重量有輪犂】の普及で生産力が高まり、人口が増加した。余剰生産物は【商業の復活】と都市の発達を促し、人口増加はエルベ川以東への【東方植民】や十字軍など、ヨーロッパの対外的な拡大をもたらした。"},
  {"id": "whx118", "s": "wh", "lv": 3, "topic": "ビザンツ帝国の変容", "q": "11世紀以降のビザンツ帝国で、国家体制がどのように変化したかを論ぜよ。", "a": "テマ制を支えた【屯田兵】などの自由農民が没落し、軍管区制はくずれた。帝国は有力者に軍役と引きかえに土地の管理と徴税を委ねる【プロノイア制】を導入し、地方の有力者が自立して【封建化】が進んだ。【第4回十字軍】によるコンスタンティノープル占領で、帝国はさらに衰えた。"},
  {"id": "whx119", "s": "wh", "lv": 3, "topic": "レコンキスタ", "q": "イベリア半島でのレコンキスタの過程と、それが近世スペインの性格に与えた影響を論ぜよ。", "a": "キリスト教諸国がイスラーム勢力から領土を奪回する【レコンキスタ】が進み、【カスティリャ】と【アラゴン】が統合してスペイン王国が成立した。1492年に【グラナダ】を攻略して完了した。強いカトリック信仰が王権と結びつき、ユダヤ教徒の追放や、新大陸への進出と布教につながった。"},
  {"id": "whx120", "s": "wh", "lv": 1, "topic": "マムルーク朝", "q": "13世紀にエジプトで成立したマムルーク朝が、イスラーム世界で果たした役割を述べよ。", "a": "トルコ系の軍人奴隷【マムルーク】が建てた王朝で、【モンゴル軍】の侵攻を撃退し、十字軍勢力も一掃した。首都【カイロ】はイスラーム世界の政治・経済・文化の中心として栄え、【カーリミー商人】が香辛料交易で活躍した。"},
  {"id": "whx121", "s": "wh", "lv": 1, "topic": "ティムール朝", "q": "14世紀後半に中央アジアで成立したティムール朝について述べよ。", "a": "【ティムール】はモンゴル帝国の再興をめざして中央アジアから西アジアに大帝国を築き、【アンカラの戦い】でオスマン帝国を破った。都の【サマルカンド】は交易と文化の中心として栄え、細密画などの【トルコ=イスラーム文化】が発達した。"},
  {"id": "whx122", "s": "wh", "lv": 1, "topic": "絶対王政", "q": "16〜18世紀のヨーロッパで成立した絶対王政の特徴を、その支柱に触れて述べよ。", "a": "国王は【王権神授説】を唱えて強大な権力をふるった。その権力を支えたのは、国王に忠実な【官僚制】と【常備軍】であり、それらを維持する財源を得るため、【重商主義】政策がとられた。"},
  {"id": "whx123", "s": "wh", "lv": 1, "topic": "三十年戦争", "q": "三十年戦争の性格と、ウェストファリア条約の内容および意義を述べよ。", "a": "ドイツの新旧両派の宗教対立から始まり、周辺各国が介入する【国際戦争】に発展した。1648年の【ウェストファリア条約】でカルヴァン派が公認され、ドイツの諸邦がほぼ完全な【主権】を認められて神聖ローマ帝国は有名無実化した。オランダとスイスの独立も承認され、【主権国家体制】が確立した。"},
  {"id": "whx124", "s": "wh", "lv": 2, "topic": "オランダの独立", "q": "オランダがスペインから独立し、17世紀に繁栄した経緯を述べよ。", "a": "スペイン王【フェリペ2世】のカトリック強制と重税に対し、ネーデルラントのカルヴァン派などが反乱をおこした。北部7州は【ユトレヒト同盟】を結んで【ネーデルラント連邦共和国】の独立を宣言した。17世紀には【東インド会社】を設立してアジア貿易で栄え、アムステルダムは国際金融の中心となった。"},
  {"id": "whx125", "s": "wh", "lv": 1, "topic": "エリザベス1世", "q": "エリザベス1世の時代に、イギリスが国力を高めた理由を述べよ。", "a": "【統一法】でイギリス国教会を確立し、宗教対立をおさめた。1588年にスペインの【無敵艦隊】を破り、海外進出の基礎を築いた。国内では【毛織物工業】を保護し、1600年には【東インド会社】を設立した。"},
  {"id": "whx126", "s": "wh", "lv": 2, "topic": "ピューリタン革命", "q": "イギリスのピューリタン革命がおこった原因と、その経過を述べよ。", "a": "ジェームズ1世とチャールズ1世が王権神授説をかかげて議会を軽視したため、議会は1628年に【権利の請願】を提出した。王が議会を解散して専制を続けると内戦となり、【クロムウェル】の率いる議会派が勝利して1649年に国王を処刑し、【共和政】が成立した。"},
  {"id": "whx127", "s": "wh", "lv": 1, "topic": "ルイ14世", "q": "「太陽王」とよばれたフランスのルイ14世の時代の政治について述べよ。", "a": "【ルイ14世】は王権神授説を唱えて絶対王政の最盛期を築いた。財務総監【コルベール】が重商主義政策を進め、壮大な【ヴェルサイユ宮殿】を造営した。しかし【ナントの王令】を廃止したため、ユグノーの商工業者が国外に流出した。"},
  {"id": "whx128", "s": "wh", "lv": 2, "topic": "啓蒙専制君主", "q": "啓蒙専制君主とはどのような君主か、プロイセンのフリードリヒ2世を例に述べよ。", "a": "【啓蒙思想】の影響を受け、上からの近代化を進めた君主。【フリードリヒ2世】は「君主は国家第一の僕」と称し、宗教寛容や産業の育成を進めた。一方で、領主貴族【ユンカー】による農場領主制は維持され、改革は国家の強化を目的とする限界をもった。"},
  {"id": "whx129", "s": "wh", "lv": 2, "topic": "ピョートル1世", "q": "ロシアのピョートル1世がおこなった近代化政策と対外政策を述べよ。", "a": "みずから西欧を視察して技術を学び、【西欧化】を進めた。【北方戦争】でスウェーデンを破ってバルト海に進出し、新都【ペテルブルク】を建設した。東方ではシベリア経営を進め、清と【ネルチンスク条約】を結んだ。"},
  {"id": "whx130", "s": "wh", "lv": 3, "topic": "再版農奴制", "q": "16世紀以降のエルベ川以東の地域で、再版農奴制が成立した理由を論ぜよ。", "a": "西欧で商工業が発展して都市人口が増えると、東欧は西欧への【穀物】輸出地域となった。領主は輸出用の穀物を生産するため、農民の賦役を強化して【農場領主制】（グーツヘルシャフト）を経営し、【再版農奴制】が成立した。これは西欧を中心とする【国際分業】の一環であった。"},
  {"id": "whx131", "s": "wh", "lv": 1, "topic": "啓蒙思想", "q": "18世紀の啓蒙思想家が唱えた、政治に関する主な思想を述べよ。", "a": "【モンテスキュー】は『法の精神』で【三権分立】を説いた。【ルソー】は『社会契約論』で人民主権を唱え、フランス革命に影響を与えた。【ヴォルテール】は理性にもとづいて教会の権威や専制政治を批判した。"},
  {"id": "whx132", "s": "wh", "lv": 2, "topic": "科学革命", "q": "17世紀ヨーロッパの科学革命について、主な人物と業績を挙げて述べよ。", "a": "観察と実験にもとづく近代科学が成立した。【ガリレイ】は望遠鏡による観測から【地動説】を支持し、【ニュートン】は万有引力の法則を発見した。哲学ではフランシス=ベーコンが帰納法、【デカルト】が演繹法を唱えた。"},
  {"id": "whx133", "s": "wh", "lv": 2, "topic": "英仏植民地戦争", "q": "17〜18世紀の英仏による植民地争奪戦の経過と、その結果を述べよ。", "a": "両国は北アメリカやインドで戦争をくり返した。七年戦争と並行した【フレンチ=インディアン戦争】でイギリスが勝ち、1763年の【パリ条約】でカナダやミシシッピ川以東を獲得した。インドでも【プラッシーの戦い】に勝利し、イギリスの優位が確立した。"},
  {"id": "whx134", "s": "wh", "lv": 3, "topic": "大西洋三角貿易", "q": "17〜18世紀の大西洋三角貿易の仕組みと、それがヨーロッパに与えた影響を論ぜよ。", "a": "ヨーロッパから【武器】や綿織物をアフリカへ運び、アフリカから【黒人奴隷】を南北アメリカへ運び、アメリカから【砂糖】・綿花・タバコをヨーロッパに運んだ。この貿易で得た利益はイギリスの資本蓄積を進め、【産業革命】の前提となった。"},
  {"id": "whx135", "s": "wh", "lv": 1, "topic": "1848年革命", "q": "1848年にヨーロッパ各地でおこった革命の内容と、その結果を述べよ。", "a": "フランスの【二月革命】で七月王政が倒れ、第二共和政が成立した。その影響でオーストリアやドイツで【三月革命】がおこり、【メッテルニヒ】が失脚した。各地の民族運動も高まり【諸国民の春】とよばれたが、多くは保守勢力に鎮圧された。"},
  {"id": "whx136", "s": "wh", "lv": 1, "topic": "イタリア統一", "q": "19世紀のイタリア統一は、どのような過程で実現したかを述べよ。", "a": "【サルデーニャ王国】の首相【カヴール】が近代化を進め、フランスと結んでオーストリアからロンバルディアを獲得した。【ガリバルディ】が両シチリア王国を占領してサルデーニャ王に献上し、1861年に【イタリア王国】が成立した。"},
  {"id": "whx137", "s": "wh", "lv": 1, "topic": "ドイツ統一", "q": "プロイセンが中心となってドイツ統一を実現した過程を述べよ。", "a": "プロイセン首相【ビスマルク】は【鉄血政策】による軍備拡張を進め、デンマーク戦争、【普墺戦争】、普仏戦争に勝利した。1871年、ヴェルサイユ宮殿でプロイセン王がドイツ皇帝に即位し、【ドイツ帝国】が成立した。"},
  {"id": "whx138", "s": "wh", "lv": 2, "topic": "ビスマルク外交", "q": "ドイツ帝国成立後のビスマルク外交の目的と、その内容を述べよ。", "a": "普仏戦争で敵対した【フランスの孤立化】を目的とした。オーストリア・ロシアと【三帝同盟】を結び、オーストリア・イタリアと【三国同盟】を結成した。のちにロシアとは【再保障条約】を結び、ヨーロッパの勢力均衡を維持した。"},
  {"id": "whx139", "s": "wh", "lv": 2, "topic": "ビスマルクの内政", "q": "ビスマルクがドイツ帝国でおこなった内政を、「アメとムチ」に触れて述べよ。", "a": "カトリック勢力を抑えるため【文化闘争】をおこない、【社会主義者鎮圧法】で社会主義運動を弾圧した。一方で労働者を体制にとりこむため、災害保険や養老保険などの【社会保険制度】を整備した。この政策は「アメとムチ」とよばれた。"},
  {"id": "whx140", "s": "wh", "lv": 1, "topic": "南北戦争", "q": "アメリカ南北戦争の原因と、その結果を述べよ。", "a": "工業が発展し【保護関税】を求める北部と、綿花を輸出するため自由貿易を求め、【奴隷制】を維持したい南部が対立した。奴隷制拡大に反対する【リンカン】の大統領当選を機に南部が分離して戦争となり、北部が勝利した。戦争中には【奴隷解放宣言】が出された。"},
  {"id": "whx141", "s": "wh", "lv": 2, "topic": "アメリカの領土拡大", "q": "19世紀のアメリカ合衆国の領土拡大の過程と、それが先住民に与えた影響を述べよ。", "a": "フランスからルイジアナを買収し、【アメリカ=メキシコ戦争】でカリフォルニアなどを獲得した。領土拡大は【明白な天命】として正当化されたが、【先住民強制移住法】などで先住民は土地を奪われた。1890年には【フロンティア】の消滅が宣言された。"},
  {"id": "whx142", "s": "wh", "lv": 1, "topic": "ロシアの農奴解放", "q": "ロシアのアレクサンドル2世が農奴解放令を出した理由と、その結果を述べよ。", "a": "【クリミア戦争】の敗北で国の後進性が明らかになり、【アレクサンドル2世】は1861年に【農奴解放令】を出した。農民は人格的な自由を得たが、土地の取得は有償で、【ミール】（農村共同体）に縛られたままだった。"},
  {"id": "whx143", "s": "wh", "lv": 2, "topic": "イギリスの自由主義的改革", "q": "19世紀前半のイギリスで進められた自由主義的改革について述べよ。", "a": "【審査法】の廃止とカトリック教徒解放法で宗教上の差別が緩和され、【第1回選挙法改正】で産業資本家が選挙権を得た。選挙権のない労働者は【チャーティスト運動】で普通選挙を要求した。自由貿易を求める運動の結果、【穀物法】が廃止された。"},
  {"id": "whx144", "s": "wh", "lv": 2, "topic": "東方問題とクリミア戦争", "q": "19世紀の「東方問題」とは何か、クリミア戦争を例に説明せよ。", "a": "オスマン帝国の衰退にともない、その領土や民族問題をめぐって列強が対立した国際問題。ロシアは不凍港を求めて【南下政策】を進め、聖地管理権を口実にオスマン帝国と【クリミア戦争】をおこしたが、【イギリス】とフランスがオスマン帝国を支援し、ロシアは敗北した。"},
  {"id": "whx145", "s": "wh", "lv": 2, "topic": "ベルリン会議", "q": "1878年に開かれたベルリン会議の背景と、その結果を述べよ。", "a": "【ロシア=トルコ戦争】に勝利したロシアは、【サン=ステファノ条約】でブルガリアを保護下においた。これにイギリスとオーストリアが反発したため、【ビスマルク】が仲介してベルリン会議が開かれた。ブルガリアは縮小され、ロシアの南下は再び阻まれた。"},
  {"id": "whx146", "s": "wh", "lv": 1, "topic": "帝国主義", "q": "19世紀末に欧米列強が帝国主義政策をとるようになった理由を述べよ。", "a": "【第2次産業革命】で重化学工業が発展し、巨大企業による【独占資本】が形成された。列強は原料供給地や商品市場、【資本輸出】の対象を求めて植民地獲得を競い、アジア・アフリカを分割した。"},
  {"id": "whx147", "s": "wh", "lv": 1, "topic": "アフリカ分割", "q": "19世紀末のアフリカ分割において、イギリスとフランスがとった政策と、両国の衝突を述べよ。", "a": "イギリスはエジプトとケープ植民地を結ぶ【アフリカ縦断政策】をとり、フランスはアルジェリアなどから東へ進む【アフリカ横断政策】をとった。両国は1898年にスーダンで【ファショダ事件】をおこしたが、フランスが譲歩し、のちに【英仏協商】が結ばれた。"},
  {"id": "whx148", "s": "wh", "lv": 2, "topic": "ベルリン=コンゴ会議", "q": "1884〜85年のベルリン会議（ベルリン=コンゴ会議）が、アフリカ分割に与えた影響を述べよ。", "a": "ビスマルクの主催で開かれ、【コンゴ自由国】をベルギー国王の私有地として認めた。また、アフリカの土地を先に【実効支配】した国が領有できるという【先占権】の原則が確認され、列強による分割が加速した。"},
  {"id": "whx149", "s": "wh", "lv": 3, "topic": "大不況と独占資本", "q": "19世紀後半の「大不況」の時期に、欧米の経済と社会がどのように変化したかを論ぜよ。", "a": "1873年から長期の不況が続き、企業は競争を避けて【カルテル】やトラストを形成し、【独占資本】が成長した。各国は【保護関税】政策に転じ、市場と投資先を求めて植民地獲得を進めた。また、困窮した多くの人々が新大陸へ【移民】として渡った。"},
  {"id": "whx150", "s": "wh", "lv": 1, "topic": "社会主義思想", "q": "19世紀に社会主義思想が生まれた背景と、その主な思想を述べよ。", "a": "産業革命による資本主義の発展で、長時間労働などの【労働問題】や貧富の差が深刻化した。オーウェンらの初期社会主義に続き、【マルクス】はエンゲルスとともに『【共産党宣言】』を著し、労働者階級の革命によって【社会主義】社会を実現すると説いた。"},
  {"id": "whx151", "s": "wh", "lv": 2, "topic": "第三共和政の危機", "q": "19世紀末にフランス第三共和政を揺るがした事件と、その影響について述べよ。", "a": "対独復讐を唱える元陸軍大臣を担いだ【ブーランジェ事件】や、ユダヤ系軍人がスパイ容疑で冤罪を受けた【ドレフュス事件】がおこった。ドレフュス事件ではゾラらが軍を批判し、共和派が勢力を強め、1905年に【政教分離法】が制定された。"},
  {"id": "whx152", "s": "wh", "lv": 3, "topic": "国民国家の形成", "q": "19世紀のヨーロッパで、国民国家の形成がどのように進められたかを論ぜよ。", "a": "フランス革命を通じて、国民が主権をもつという【国民主義】（ナショナリズム）の理念が広まった。各国は【義務教育】や【徴兵制】を整え、国語や国民の歴史を教えて【国民意識】を育てた。イタリアやドイツでは、統一運動を通じて【国民国家】が形成された。"},
  {"id": "whx153", "s": "wh", "lv": 3, "topic": "世界の工場イギリス", "q": "19世紀半ばのイギリスが「世界の工場」として築いた経済体制と、その対外政策を論ぜよ。", "a": "圧倒的な工業力をもつイギリスは、【穀物法】や【航海法】を廃止して【自由貿易】体制を確立した。工業製品を輸出し原料や食料を輸入する国際分業を進め、ロンドンは国際金融の中心となった。軍事力を背景に通商を開かせる【自由貿易帝国主義】で、アジアやラテンアメリカに影響力を広げた。"},
  {"id": "whx154", "s": "wh", "lv": 1, "topic": "ヴィクトリア時代の議会政治", "q": "ヴィクトリア女王時代のイギリスで発達した議会政治について述べよ。", "a": "自由党と保守党の【二大政党】が交互に政権を担当し、自由党の【グラッドストン】と保守党の【ディズレーリ】が活躍した。第2回・第3回の【選挙法改正】で、都市労働者や農業労働者にも選挙権が拡大された。"},
  {"id": "whx155", "s": "wh", "lv": 2, "topic": "アイルランド問題", "q": "19世紀から20世紀初めにかけての、イギリスにおけるアイルランド問題の経過を述べよ。", "a": "1801年にアイルランドはイギリスに【併合】され、カトリック教徒への差別や不在地主の支配が続いた。1840年代の【ジャガイモ飢饉】では多くの人々が餓死し、アメリカなどへ移住した。グラッドストンの【アイルランド自治法案】は否決が続き、1914年に成立したが実施は延期された。"},
  {"id": "whx156", "s": "wh", "lv": 1, "topic": "対抗宗教改革", "q": "宗教改革に対して、カトリック側がおこなった対抗宗教改革の内容を述べよ。", "a": "【トリエント公会議】で教皇の至上権とカトリックの教義を再確認し、教会内部の粛正を進めた。【イエズス会】が設立され、ザビエルらがアジアやラテンアメリカで【海外布教】をおこなった。異端の取り締まりのため【宗教裁判】や禁書目録も強化された。"},
  {"id": "whx157", "s": "wh", "lv": 2, "topic": "ユグノー戦争", "q": "16世紀後半のフランスでおこったユグノー戦争の経過と、その終結について述べよ。", "a": "カトリックとカルヴァン派の【ユグノー】の対立に貴族の争いが結びつき、内戦となった。1572年の【サンバルテルミの虐殺】ではユグノーが多数殺害された。ブルボン朝を開いた【アンリ4世】が1598年に【ナントの王令】を出し、ユグノーに信仰の自由を認めて内戦を終結させた。"},
  {"id": "whx158", "s": "wh", "lv": 3, "topic": "重商主義", "q": "絶対王政期の重商主義とはどのような経済政策か、フランスとイギリスの例を挙げて論ぜよ。", "a": "国家が経済に介入して国富を増大させようとする政策。初期には金銀の獲得をめざす【重金主義】がとられ、のちに輸出拡大で利益を得る【貿易差額主義】が中心となった。フランスでは【コルベール】が王立マニュファクチュアを育成し、イギリスは【航海法】でオランダの中継貿易に打撃を与えた。"},
  {"id": "whx159", "s": "wh", "lv": 2, "topic": "第2次囲い込み", "q": "18世紀イギリスの第2次囲い込みと農業革命は、社会にどのような影響を与えたか。", "a": "【第2次囲い込み】では、大地主が議会の承認のもとで開放耕地や共有地を囲い込み、【ノーフォーク農法】などで生産力を高めた。土地を失った小農民は賃金労働者となり、工業の【労働力】を提供した。農業でも地主・農業資本家・農業労働者による【資本主義的経営】が広がった。"},
  {"id": "geox1", "s": "geo", "lv": 1, "topic": "西岸海洋性気候", "q": "西ヨーロッパは高緯度のわりに冬が温和である。その理由を説明せよ。", "a": "沖合を暖流の【北大西洋海流】が流れ、その上を通って暖められた空気を、一年中吹く【偏西風】が大陸西岸に運ぶため。その結果、気温の年較差が小さい【西岸海洋性気候】となる。"},
  {"id": "geox2", "s": "geo", "lv": 1, "topic": "赤道付近の多雨", "q": "赤道付近で一年中降水量が多くなるのはなぜか。", "a": "赤道付近は太陽からの熱を強く受けて地表の空気が暖められ、【上昇気流】が発達する。空気は上昇して冷えると雲をつくり、【熱帯収束帯（赤道低圧帯）】となって【スコール】などの多量の雨が降るため。"},
  {"id": "geox3", "s": "geo", "lv": 1, "topic": "回帰線付近の砂漠", "q": "南北の回帰線付近に大きな砂漠が分布するのはなぜか。", "a": "回帰線付近は赤道で上昇した空気が下降してくる【亜熱帯高圧帯】にあたる。【下降気流】のもとでは雲ができにくく、降水がきわめて少ないため、サハラ砂漠などの【砂漠気候】が広がる。"},
  {"id": "geox4", "s": "geo", "lv": 1, "topic": "海岸砂漠", "q": "ペルーやチリのアタカマ砂漠のように、海岸に砂漠ができるのはなぜか。", "a": "沖合を【寒流】（ペルー海流）が流れ、海面近くの空気が冷やされて下層が冷たく上層が暖かい【安定】した大気となる。そのため【上昇気流】が起こらず雨雲が発達しにくく、【海岸砂漠】が形成される。"},
  {"id": "geox5", "s": "geo", "lv": 1, "topic": "季節風", "q": "東アジアや南アジアで夏に雨が多いのはなぜか。季節風に着目して説明せよ。", "a": "夏は大陸が海洋より暖まりやすく大陸上が低圧になるため、海洋から大陸へ湿った【季節風（モンスーン）】が吹きこむ。この湿った風が【水蒸気】を運んで雨を降らせるため、夏に【雨季】となる。"},
  {"id": "geox6", "s": "geo", "lv": 1, "topic": "扇状地", "q": "扇状地の扇央が果樹園などに利用されることが多いのはなぜか。", "a": "扇央は【砂礫】が堆積してできており水はけがよく、河川が地下にもぐって【伏流】しやすいため水が得にくい。そのため水田には向かず、乾燥に強い【果樹園】や桑畑に利用されてきた。"},
  {"id": "geox7", "s": "geo", "lv": 1, "topic": "三角州", "q": "三角州はどのようにして形成されるか。また、その土地利用を説明せよ。", "a": "河川が海や湖に流れこむところで流速が落ち、運んできた細かい【砂や泥】が【堆積】して形成される。低平で水が得やすいため【水田】に利用され、大都市が発達することも多いが、【洪水】や高潮の被害を受けやすい。"},
  {"id": "geox8", "s": "geo", "lv": 1, "topic": "リアス海岸", "q": "リアス海岸はどのようにしてできたか。また、どのような産業に利用されているか。", "a": "山地の谷が【沈降】や海面上昇によって海に沈み、【溺れ谷】となって複雑な海岸線ができた。湾内は波がおだやかで水深があるため、【養殖業】や漁港に利用されるが、【津波】の被害を受けやすい。"},
  {"id": "geox9", "s": "geo", "lv": 1, "topic": "フィヨルド", "q": "ノルウェーなどに見られるフィヨルドの成因を説明せよ。", "a": "氷期に【氷河】が谷を削って断面が【U字谷】の深い谷をつくり、氷期が終わって氷河がとけ【海面上昇】が起こると、その谷に海水が入りこんで奥行きの長い細長い湾となった。"},
  {"id": "geox10", "s": "geo", "lv": 1, "topic": "日本海側の豪雪", "q": "冬に日本海側で雪が多くなる理由を説明せよ。", "a": "冬は【シベリア高気圧】から北西の【季節風】が吹き出す。この乾いた冷たい風が比較的暖かい【日本海】の上で水蒸気を補給され、山地にぶつかって上昇気流となり、日本海側に多量の雪を降らせるため。"},
  {"id": "geox11", "s": "geo", "lv": 1, "topic": "地中海式農業", "q": "地中海式農業ではどのような作物がつくられるか。気候と関連づけて説明せよ。", "a": "夏は高温で【乾燥】し、冬に雨が降る気候に合わせ、夏は乾燥に強い【オリーブ】やぶどう、柑橘類などの【樹木作物】を、降水のある冬には小麦などの穀物を栽培する。"},
  {"id": "geox12", "s": "geo", "lv": 1, "topic": "混合農業", "q": "ヨーロッパの混合農業とはどのような農業か説明せよ。", "a": "小麦などの【食用穀物】と、大麦・てんさいなどの【飼料作物】を【輪作】し、飼料で牛や豚などの【家畜】を飼育する農業。作物の栽培と家畜の飼育を組み合わせて地力を維持しながら経営する。"},
  {"id": "geox13", "s": "geo", "lv": 1, "topic": "酪農の立地", "q": "酪農が冷涼な地域や大都市の近郊で発達しやすい理由を説明せよ。", "a": "冷涼でやせた土地でも【牧草】はよく育つため、乳牛を飼う酪農に適している。また生乳は【鮮度】が重要で輸送しにくいため、消費地である【大都市】の近郊でも発達してきた。"},
  {"id": "geox14", "s": "geo", "lv": 1, "topic": "鉄鋼業の立地", "q": "日本の製鉄所が臨海部に立地している理由を説明せよ。", "a": "日本は【鉄鉱石】や【石炭】などの原料をほぼ輸入に頼っているため、大型船で原料を運びこみやすく、製品の輸出にも便利な【臨海部】の【港湾】付近に製鉄所が立地している。"},
  {"id": "geox15", "s": "geo", "lv": 1, "topic": "セメント工業", "q": "セメント工業が原料産地の近くに立地しやすいのはなぜか。", "a": "セメントの主原料である【石灰石】は、製品にすると重量が大きく減る【重量減損原料】で、原料の輸送費が大きいため。輸送費を節約できる【原料産地】（秩父など）に立地する【原料指向型】工業である。"},
  {"id": "geox16", "s": "geo", "lv": 1, "topic": "IC工業の立地", "q": "IC（集積回路）工場が空港や高速道路の近くに立地しやすいのはなぜか。", "a": "ICは小型・軽量で【付加価値】が高く、輸送費の負担が小さいため、【航空機】や高速道路のトラックで輸送しても採算がとれる。そのため地価が安く労働力も得やすい地方の【空港】や【高速道路】沿いに立地する。"},
  {"id": "geox17", "s": "geo", "lv": 1, "topic": "人口ピラミッド", "q": "日本の人口ピラミッドが富士山型からつぼ型へと変化した理由を説明せよ。", "a": "医療の発達などで【死亡率】が下がって平均寿命が延び、高齢者が増えた。一方、女性の社会進出や晩婚化などで【出生率】が低下したため、【少子高齢化】が進み、若い年齢層ほど人口の少ない【つぼ型】になった。"},
  {"id": "geox18", "s": "geo", "lv": 1, "topic": "ドーナツ化現象", "q": "大都市でみられたドーナツ化現象とはどのような現象か。", "a": "都心部の【地価】の高騰や環境悪化によって住民が【郊外】へ移り、都心部の【夜間人口】が減少して、周辺部の人口が増加する現象。都心は昼間人口が多く夜間人口が少なくなる。"},
  {"id": "geox19", "s": "geo", "lv": 1, "topic": "首位都市", "q": "発展途上国で首都などの一都市に人口が集中するのはなぜか。", "a": "農村では人口増加により仕事が不足し、多くの人が雇用や所得を求めて都市へ【人口流入】する。工業やサービス業、行政機能が一つの都市に集中しているため【首位都市（プライメートシティ）】が形成され、住環境の悪い【スラム】も生まれやすい。"},
  {"id": "geox20", "s": "geo", "lv": 1, "topic": "ヒートアイランド", "q": "大都市の気温が周辺より高くなるヒートアイランド現象の原因を説明せよ。", "a": "都市では地面が【アスファルト】やコンクリートに覆われて熱をため込み、緑地や水面が少ないため【蒸発】による冷却が弱い。さらにエアコンや自動車などの【人工排熱】が多いため、気温が周辺より高くなる。"},
  {"id": "geox21", "s": "geo", "lv": 1, "topic": "環太平洋造山帯", "q": "日本列島で地震や火山活動が多いのはなぜか。プレートの動きから説明せよ。", "a": "日本列島は【環太平洋造山帯】に位置し、太平洋プレートやフィリピン海プレートが大陸側のプレートの下に【沈み込む】【プレート境界】付近にあるため、地殻変動が活発で地震や火山活動が多い。"},
  {"id": "geox22", "s": "geo", "lv": 1, "topic": "安定陸塊", "q": "安定陸塊と新期造山帯では、地形にどのような違いがあるか。", "a": "【安定陸塊】は先カンブリア時代以降大きな造山運動を受けず、長い【侵食】で平坦な台地や平原が広がる。一方【新期造山帯】は現在も地殻変動が活発で、高く険しい山脈が連なり、地震や火山が多い。"},
  {"id": "geox23", "s": "geo", "lv": 1, "topic": "熱帯林の減少", "q": "アマゾンなどで熱帯林が減少している主な原因を説明せよ。", "a": "大規模な【牧場】や大豆畑の開発、木材を得るための【伐採】、道路建設にともなう入植、過度な【焼畑】などによって森林が切り開かれているため。熱帯林の減少は生物多様性の喪失や【地球温暖化】につながる。"},
  {"id": "geox24", "s": "geo", "lv": 1, "topic": "企業的穀物農業", "q": "アメリカやカナダで行われている企業的穀物農業の特色を説明せよ。", "a": "広大な土地で大型の【機械】を使い、小麦やとうもろこしなどを【大規模】に栽培する。少ない労働力で生産するため【労働生産性】が高く、生産物の多くを世界に【輸出】している。"},
  {"id": "geox25", "s": "geo", "lv": 2, "topic": "フェーン現象", "q": "山を越えて吹き降りる風が高温・乾燥になるフェーン現象のしくみを説明せよ。", "a": "湿った空気が山を上昇するとき、雲ができて雨を降らせ、水蒸気が凝結する際の【潜熱】で空気の温度低下がゆるやかになる（【湿潤断熱減率】）。山を越えて下降するときは【乾燥断熱減率】で大きく昇温するため、風下側は高温・乾燥になる。"},
  {"id": "geox26", "s": "geo", "lv": 2, "topic": "大陸東岸の気候", "q": "同じ緯度でも、ユーラシア大陸の東岸は西岸に比べて気温の年較差が大きい。その理由を説明せよ。", "a": "中緯度では【偏西風】が吹くため、東岸は大陸の影響を強く受ける。冬は大陸から寒冷な【季節風】が吹いて非常に寒く、夏は海洋からの季節風で高温になるため、【大陸性気候】の性格が強く【年較差】が大きくなる。"},
  {"id": "geox27", "s": "geo", "lv": 2, "topic": "河岸段丘", "q": "河岸段丘はどのようにして形成されるか説明せよ。", "a": "河川がつくった谷底平野が、土地の【隆起】や海面の低下によって河川の【下刻（侵食）】が再び強まると、川がより低い位置を流れるようになる。これがくり返されて、もとの谷底が【階段状】の平坦面（段丘面）として残る。"},
  {"id": "geox28", "s": "geo", "lv": 2, "topic": "カルスト地形", "q": "カルスト地形はどのようなしくみで形成されるか。", "a": "【石灰岩】の地域で、二酸化炭素を含む雨水や地下水が岩石を【溶食】することによって形成される。地表には【ドリーネ】などのくぼ地が、地下には【鍾乳洞】ができる。"},
  {"id": "geox29", "s": "geo", "lv": 2, "topic": "サンゴ礁", "q": "サンゴ礁が熱帯・亜熱帯の島の周りなどに分布する理由を説明せよ。", "a": "造礁サンゴは体内の褐虫藻が【光合成】を行うため、【水温】が高く、日光が届く【浅い】、濁りの少ない【澄んだ】海でしか生育できない。そのため河川からの土砂が流れこまない熱帯・亜熱帯の島の周りなどに発達する。"},
  {"id": "geox30", "s": "geo", "lv": 2, "topic": "永久凍土と高床", "q": "シベリアの建物が高床式になっていることが多い理由を説明せよ。", "a": "シベリアには一年中凍結した【永久凍土】が広がる。建物の暖房の熱が地面に伝わると凍土が【融解】して地盤が沈下し、建物が傾くおそれがあるため、【高床式】にして熱が地面に伝わらないようにしている。"},
  {"id": "geox31", "s": "geo", "lv": 2, "topic": "エルニーニョ現象", "q": "エルニーニョ現象とはどのような現象か。日本への影響もあわせて説明せよ。", "a": "太平洋赤道域で【貿易風】が弱まり、東部（ペルー沖）の【海面水温】が平年より高くなる現象。ペルー沖では寒流による湧昇が弱まって漁獲が減る。日本では【冷夏】や【暖冬】になりやすい。"},
  {"id": "geox32", "s": "geo", "lv": 2, "topic": "緑の革命", "q": "1960年代以降にアジアで進められた緑の革命の内容と、その課題を説明せよ。", "a": "米や小麦の【高収量品種】を導入し、【灌漑】設備や【化学肥料】・農薬を使って穀物の生産を大きく増やした。一方で、資金のある大規模農家が恩恵を受けやすく、【農民間の格差】の拡大や環境への負荷などの課題が生じた。"},
  {"id": "geox33", "s": "geo", "lv": 2, "topic": "センターピボット", "q": "アメリカのグレートプレーンズでは灌漑農業が地下水の問題を引き起こしている。その内容を説明せよ。", "a": "乾燥したグレートプレーンズでは【オガララ帯水層】の地下水をくみ上げ、回転式の【センターピボット】で散水して大規模に穀物を栽培している。しかし、くみ上げが補給量を上回っているため【地下水の枯渇】が懸念されている。"},
  {"id": "geox34", "s": "geo", "lv": 2, "topic": "適地適作", "q": "アメリカの農業における「適地適作」とはどのような考え方か。具体例をあげて説明せよ。", "a": "各地域の【気候】や土壌などの自然条件や市場との関係に最も適した作物を集中して栽培すること。例えば、冷涼な北部では【酪農】、中西部ではとうもろこしと大豆の【コーンベルト】、南部では【綿花】の栽培が行われる。"},
  {"id": "geox35", "s": "geo", "lv": 2, "topic": "プランテーション", "q": "プランテーション農業はどのようにして成立したか。その特色とあわせて説明せよ。", "a": "熱帯地域が欧米の【植民地】だった時代に、欧米の資本と現地の安い【労働力】を使い、輸出向けに天然ゴム・コーヒー・カカオなどの【商品作物】を大規模に【単一栽培】する農園として成立した。"},
  {"id": "geox36", "s": "geo", "lv": 2, "topic": "日本の食料自給率", "q": "日本の食料自給率（カロリーベース）が低下してきた理由を説明せよ。", "a": "食生活の【洋風化】で米の消費が減り、肉や油脂の消費が増えたが、それらや家畜の【飼料】の多くを輸入に頼っている。また【貿易自由化】で安い外国産の農産物が増え、農業の担い手の減少も進んだため。"},
  {"id": "geox37", "s": "geo", "lv": 2, "topic": "自動車工業", "q": "自動車工業の工場の周辺に多くの工場が集まる理由を説明せよ。", "a": "自動車は約3万点もの【部品】を組み立てて生産する【組立型工業】である。完成車工場が必要な部品を必要な時に受け取る【ジャストインタイム】方式をとるため、多くの【関連工場】が周辺に集まり【企業城下町】が形成される。"},
  {"id": "geox38", "s": "geo", "lv": 2, "topic": "産業の空洞化", "q": "1980年代後半以降、日本で産業の空洞化が問題となった理由を説明せよ。", "a": "【円高】の進行や国内の高い【人件費】を背景に、企業が生産拠点を安い労働力が得られるアジアなどの【海外】へ移した。その結果、国内の工場が減って雇用が失われ、地域の製造業が衰える【産業の空洞化】が起こった。"},
  {"id": "geox39", "s": "geo", "lv": 2, "topic": "輸出加工区", "q": "発展途上国が輸出加工区を設けて工業化をめざした理由を説明せよ。", "a": "関税の免除や税の優遇などで【外国企業】を誘致し、【資本】や技術を導入するため。豊富で安い【労働力】を生かして製品を輸出することで、外貨を獲得し【輸出指向型】の工業化を進めようとした。"},
  {"id": "geox40", "s": "geo", "lv": 2, "topic": "サンベルト", "q": "1970年代以降、アメリカで工業の中心がサンベルトへ移った理由を説明せよ。", "a": "北緯37度以南の【サンベルト】は温暖で、広い土地が安く、労働組合の組織率が低く【賃金】が安かった。州政府の誘致策もあり、【先端技術産業】や航空宇宙産業が進出し、【スノーベルト】に代わって工業の中心となった。"},
  {"id": "geox41", "s": "geo", "lv": 2, "topic": "人口転換", "q": "人口転換（人口革命）とはどのような過程か説明せよ。", "a": "経済発展にともない、人口動態が【多産多死】から、医療・衛生の改善で死亡率が下がる【多産少死】へ移り、人口が急増する。さらに教育の普及や都市化で出生率も下がり、【少産少死】へと移行する過程をいう。"},
  {"id": "geox42", "s": "geo", "lv": 2, "topic": "スプロール現象", "q": "大都市の郊外でみられるスプロール現象とはどのような現象で、何が問題か。", "a": "都市の拡大にともない、郊外で住宅や工場などが計画性なく【無秩序】に広がる現象。農地と住宅地が【虫食い】状に混在し、道路や下水道などの【都市基盤】の整備が追いつかないことが問題となる。"},
  {"id": "geox43", "s": "geo", "lv": 2, "topic": "インナーシティ問題", "q": "欧米の大都市でみられるインナーシティ問題について説明せよ。", "a": "都心周辺の古い市街地から、比較的豊かな層が【郊外】へ流出し、高齢者や低所得者、移民などが取り残される。その結果、建物の【老朽化】や治安の悪化、税収の減少が進み、地域が【スラム化】する問題。"},
  {"id": "geox44", "s": "geo", "lv": 2, "topic": "東南アジアの華人", "q": "東南アジアに華人が多く住み、経済的に大きな影響力をもつのはなぜか。", "a": "19世紀以降、中国の【福建】省や広東省などから、植民地での鉱山や農園の労働者、商人として多くの人々が移住した。彼らの子孫である【華人】は【商業】や金融業で成功し、各国の経済に大きな影響力をもつようになった。"},
  {"id": "geox45", "s": "geo", "lv": 2, "topic": "外来河川", "q": "エジプトでは砂漠気候にもかかわらず古くから農業が営まれてきた。その理由を説明せよ。", "a": "湿潤な地域に水源をもち、乾燥地域を貫いて流れる【外来河川】の【ナイル川】があるため。かつては定期的な【洪水】が肥沃な土を運び、現在はアスワンハイダムによる【灌漑】で農業が営まれている。"},
  {"id": "geox46", "s": "geo", "lv": 2, "topic": "乾燥地の塩害", "q": "乾燥地域の灌漑農業で塩害が起こるしくみを説明せよ。", "a": "乾燥地域では【蒸発】が盛んなため、過剰な【灌漑】で地下水位が上がると、土壌中の水が毛細管現象で地表に上がって蒸発し、水に溶けていた【塩分】が地表に集積する。こうして【土壌の塩性化】が進み、作物が育たなくなる。"},
  {"id": "geox47", "s": "geo", "lv": 2, "topic": "中国の経済特区", "q": "中国が1980年ごろから沿岸部に経済特区を設けた目的を説明せよ。", "a": "【改革開放政策】のもと、税の優遇などで【外国資本】や技術を導入し、輸出向けの工業化を進めるため。【シェンチェン（深圳）】など香港や台湾に近い南部の沿岸部に設けられ、その後の経済成長の起点となった。"},
  {"id": "geox48", "s": "geo", "lv": 2, "topic": "国際河川", "q": "ライン川がヨーロッパの経済にとって重要である理由を説明せよ。", "a": "ライン川は複数の国を流れ、条約で外国船の自由な航行が認められた【国際河川】である。流れが緩やかで水量が安定し【内陸水運】に適しているため、【ルール工業地域】などと河口の【ユーロポート】を結ぶ物流の大動脈となっている。"},
  {"id": "geox49", "s": "geo", "lv": 3, "topic": "地中海性気候の夏の乾燥", "q": "地中海性気候の地域で、夏に乾燥し冬に雨が多くなる理由を、大気大循環と関連づけて説明せよ。", "a": "大気の循環帯は太陽の【回帰】にともない季節によって南北に移動する。夏には【亜熱帯高圧帯】が高緯度側へ移動してその支配下に入るため乾燥し、冬には【偏西風】帯に入り、【温帯低気圧】や前線が通過して雨が多くなる。"},
  {"id": "geox50", "s": "geo", "lv": 3, "topic": "熱帯林の土壌", "q": "熱帯雨林は植物が非常に豊かだが、土壌はやせていることが多い。その理由を説明せよ。", "a": "高温多雨のため落葉などの有機物は微生物によってすぐに【分解】され、養分は植物にすぐ吸収されて【腐植層】が発達しにくい。さらに多量の雨で養分が【溶脱】され、鉄やアルミニウムの酸化物が残った赤色の【ラトソル】となるため。"},
  {"id": "geox51", "s": "geo", "lv": 3, "topic": "黒土地帯", "q": "ウクライナから黒海北岸にかけての地域が世界的な小麦の産地となっている理由を、土壌と気候から説明せよ。", "a": "この地域は【ステップ気候】の草原地帯で、草の根や枯れ草に由来する【腐植】が、降水が少なく流されにくいため厚く蓄積した、肥沃な黒色の【チェルノーゼム】が分布する。適度な降水と広大な平原もあり【小麦】の栽培に適している。"},
  {"id": "geox52", "s": "geo", "lv": 3, "topic": "モノカルチャー経済", "q": "アフリカの多くの国でみられるモノカルチャー経済の問題点を、その成立の背景とあわせて説明せよ。", "a": "【植民地】時代に宗主国向けの特定の農産物や鉱産資源の生産に特化させられたため成立した。少数の【一次産品】の輸出に依存するため、【国際価格】の変動や天候不順で国家収入が不安定になり、【交易条件】の悪化も受けやすい。"},
  {"id": "geox53", "s": "geo", "lv": 3, "topic": "青いバナナ", "q": "ヨーロッパで「青いバナナ（ブルーバナナ）」とよばれる地域に人口や産業が集中している理由を説明せよ。", "a": "イギリス南部からライン川流域を経て北イタリアに至る地域で、【ライン川】の水運や交通網に恵まれ、古くから商業・工業が発展してきた。【EU】の統合で国境を越えた移動が自由になり、ロンドンや【ルール】地方などの中心地が連なる経済の中核となっている。"},
  {"id": "geox54", "s": "geo", "lv": 3, "topic": "中国の地域格差", "q": "中国で沿海部と内陸部の経済格差が拡大した理由と、政府の対応を説明せよ。", "a": "【改革開放政策】で経済特区などの沿海部に外国資本が集中し、工業化と所得向上が急速に進んだ一方、内陸部は開発が遅れたため格差が拡大した。政府は【西部大開発】でインフラ整備などを進め、農村から都市への【出稼ぎ（農民工）】も多い。"},
  {"id": "geox55", "s": "geo", "lv": 3, "topic": "過疎と限界集落", "q": "日本の山間部などで過疎化が進むと、どのような問題が生じるか。", "a": "若者が都市へ流出して【高齢化】が進み、65歳以上が半数を超える【限界集落】が増える。地域の共同作業や祭りの維持が難しくなり、バスや病院、商店などの【生活サービス】が撤退し、【耕作放棄地】や荒廃した森林も増加する。"},
  {"id": "geox56", "s": "geo", "lv": 3, "topic": "仮想水", "q": "「仮想水（バーチャルウォーター）」の考え方から、日本の食料輸入の意味を説明せよ。", "a": "仮想水とは、輸入した農産物や畜産物を自国で生産したと仮定した場合に必要となる【水】の量のこと。日本は大量の食料を輸入することで、間接的に海外の【水資源】を大量に消費しており、輸出国の【水不足】の問題とも関わっている。"},
  {"id": "geox57", "s": "geo", "lv": 3, "topic": "オーストラリアの貿易", "q": "オーストラリアの主な貿易相手国がイギリスからアジア諸国へ変化した理由を説明せよ。", "a": "かつては【イギリス】の植民地として本国との結びつきが強かったが、イギリスの【EC加盟】で関係が弱まった。一方、日本や中国などアジアの工業化で【鉄鉱石】・石炭などの需要が高まり、白豪主義の撤廃と【多文化主義】もあってアジアとの結びつきが強まった。"},
  {"id": "geox58", "s": "geo", "lv": 3, "topic": "インドのICT産業", "q": "インドでICT（情報通信技術）産業が発展した理由を説明せよ。", "a": "理数系の教育水準が高い人材が豊富で、【英語】を話せる人が多く、【人件費】も比較的安い。またアメリカとの【時差】が約半日あるため、アメリカの夜間に業務を引き継げる。【ベンガルール】などに企業が集積している。"},
  {"id": "geox59", "s": "geo", "lv": 3, "topic": "ブラジルのバイオ燃料", "q": "ブラジルでさとうきびを原料とするバイオエタノールの生産が進められた理由と、その課題を説明せよ。", "a": "【石油危機】を機に、石油輸入への依存を減らすため、国内で豊富に栽培できる【さとうきび】から燃料をつくり、【フレックス燃料車】も普及した。一方で、農地の拡大による【森林破壊】や、食料との競合による価格上昇が課題となっている。"},
  {"id": "geox60", "s": "geo", "lv": 3, "topic": "熱帯低気圧の発達", "q": "熱帯低気圧が海面水温の高い海域で発達しやすく、上陸すると急速に衰える理由を説明せよ。", "a": "熱帯低気圧は、海面から蒸発した大量の【水蒸気】が上空で凝結するときに放出する【潜熱】をエネルギー源として発達する。上陸すると水蒸気の供給が絶たれ、地表との【摩擦】も大きくなるため衰える。"},
  {"id": "seikeix1", "s": "seikei", "lv": 1, "topic": "法の支配", "q": "「法の支配」とはどのような考え方か。「法治主義」との違いにもふれて説明せよ。", "a": "権力者も含めてすべての人が、【基本的人権】を保障する正しい内容の法に従うべきだという考え方で、【権力の濫用】を防ぐ。法の内容よりも法律に基づく手続きを重視した19世紀ドイツの【法治主義】（【形式的法治主義】）とは異なる。"},
  {"id": "seikeix2", "s": "seikei", "lv": 1, "topic": "三権分立", "q": "モンテスキューが唱えた三権分立とはどのような考え方か。", "a": "国家権力を【立法】・【行政】・【司法】の三つに分け、それぞれを別の機関に担当させて互いに【抑制と均衡】をはからせることで、権力の集中と濫用を防ぎ、国民の自由を守ろうとする考え方。『法の精神』で唱えられた。"},
  {"id": "seikeix3", "s": "seikei", "lv": 1, "topic": "ロックの社会契約説", "q": "ロックの社会契約説の内容を、抵抗権にふれて説明せよ。", "a": "人は生まれながらに生命・自由・財産を守る【自然権】をもつ。人々はその保障を確実にするため【社会契約】を結んで政府に権力を【信託】する。政府が自然権を侵害した場合、人民は【抵抗権（革命権）】によって政府を取りかえることができる。"},
  {"id": "seikeix4", "s": "seikei", "lv": 1, "topic": "日本国憲法の三大原理", "q": "日本国憲法の三大原理を挙げ、それぞれ簡潔に説明せよ。", "a": "政治のあり方を最終的に決める力が国民にあるとする【国民主権】、人が生まれながらにもつ権利を侵すことのできない永久の権利として保障する【基本的人権の尊重】、戦争を放棄し戦力をもたないとする【平和主義】の三つである。"},
  {"id": "seikeix5", "s": "seikei", "lv": 1, "topic": "違憲審査権", "q": "裁判所の違憲審査権とはどのような権限か。その意義も説明せよ。", "a": "法律や命令、処分などが【憲法】に適合するかどうかを判断する権限で、すべての裁判所がもつ。最終的な判断を下す最高裁判所は【憲法の番人】とよばれる。国会などによる【人権侵害】を防ぎ、【憲法の最高法規性】を守る意義がある。"},
  {"id": "seikeix6", "s": "seikei", "lv": 1, "topic": "衆議院の優越", "q": "衆議院に参議院より強い権限（衆議院の優越）が認められている理由を説明せよ。", "a": "衆議院は議員の【任期】が4年と参議院の6年より短く、任期途中の【解散】もあるため、選挙を通じて【民意】をより強く反映しやすいと考えられている。そのため【予算】の議決や首相の指名などで優越が認められている。"},
  {"id": "seikeix7", "s": "seikei", "lv": 1, "topic": "議院内閣制", "q": "日本の議院内閣制とはどのようなしくみか。内閣と国会の関係に着目して説明せよ。", "a": "内閣が【国会】の信任にもとづいて成立し、国会に対して【連帯責任】を負うしくみ。内閣総理大臣は国会議員の中から国会が指名し、衆議院が【内閣不信任】を決議すると、内閣は10日以内に衆議院を【解散】しない限り総辞職しなければならない。"},
  {"id": "seikeix8", "s": "seikei", "lv": 1, "topic": "アメリカの大統領制", "q": "アメリカの大統領制の特徴を、議院内閣制と比較して説明せよ。", "a": "大統領は国民が【間接選挙】で選び、議会から独立して行政権をもつ。議会は大統領を【不信任】できず、大統領も議会を解散できない。大統領は法案の提出権をもたないが、【教書】を送り、法案への【拒否権】をもつなど、【厳格な三権分立】がとられている。"},
  {"id": "seikeix9", "s": "seikei", "lv": 1, "topic": "生存権", "q": "日本国憲法第25条の生存権とはどのような権利か説明せよ。", "a": "すべての国民が「【健康で文化的な最低限度の生活】」を営む権利で、国に対して積極的な保障を求める【社会権】の一つである。国はこれを実現するため、【生活保護】などの【社会保障】制度を整備する責任を負う。"},
  {"id": "seikeix10", "s": "seikei", "lv": 1, "topic": "小選挙区制", "q": "衆議院議員選挙などで採用されている小選挙区制の長所と短所を説明せよ。", "a": "一つの選挙区から1人を選ぶ制度で、【二大政党制】になりやすく政局が安定しやすい。一方で、落選者に投じられた【死票】が多くなり、【少数意見】が議席に反映されにくい。"},
  {"id": "seikeix11", "s": "seikei", "lv": 1, "topic": "比例代表制", "q": "選挙制度のうち、比例代表制の長所と短所を小選挙区制と比べて説明せよ。", "a": "政党の【得票率】に応じて議席を配分する制度で、【死票】が少なく、多様な民意を議席に反映しやすい。一方で、【小党分立】になりやすく、【連立政権】となって政局が不安定になりやすい。"},
  {"id": "seikeix12", "s": "seikei", "lv": 1, "topic": "民主主義の学校", "q": "ブライスが「地方自治は民主主義の学校である」と述べたのはなぜか。", "a": "住民が身近な地域の問題に直接関わり、【住民自治】を実践することで、政治に参加する力や責任感が養われる。こうした経験が国の【民主主義】を支える基礎となると考えたため。日本では【直接請求権】などで住民の参加が保障されている。"},
  {"id": "seikeix13", "s": "seikei", "lv": 1, "topic": "市場メカニズム", "q": "市場で商品の価格はどのように決まるか。需要と供給の関係から説明せよ。", "a": "価格が高いと【需要】は減り【供給】は増え、売れ残りが生じて価格が下がる。逆に価格が低いと品不足になり価格が上がる。こうして需要量と供給量が一致する【均衡価格】に落ちつく。このはたらきを【価格の自動調節機能】という。"},
  {"id": "seikeix14", "s": "seikei", "lv": 1, "topic": "寡占と管理価格", "q": "寡占市場で価格が下がりにくくなる理由を説明せよ。", "a": "少数の企業が市場を支配する【寡占】市場では、有力企業が【プライス・リーダー】として価格を決め、他社が追随する【管理価格】が形成されやすい。企業は価格競争を避けて広告などの【非価格競争】を行うため、価格が下がりにくい（【価格の下方硬直性】）。"},
  {"id": "seikeix15", "s": "seikei", "lv": 1, "topic": "外部不経済", "q": "「外部不経済」とは何か。具体例をあげて説明せよ。", "a": "ある経済主体の活動が、【市場】での取引を通さずに第三者に不利益を与えること。例えば工場の排煙による【公害】で周辺住民が健康被害を受ける場合など。費用が価格に反映されないため、【市場の失敗】の一つとされる。"},
  {"id": "seikeix16", "s": "seikei", "lv": 1, "topic": "公共財", "q": "公共財が市場では十分に供給されないのはなぜか。", "a": "公共財は、多くの人が同時に利用できる【非競合性】と、対価を払わない人の利用を防げない【非排除性】をもつ。【フリーライダー】が生じて企業は利益を得にくいため市場では供給されず、【政府】が税金で供給する必要がある。"},
  {"id": "seikeix17", "s": "seikei", "lv": 1, "topic": "インフレーション", "q": "インフレーションは人々の生活にどのような影響を与えるか。", "a": "物価が継続的に上昇すると【貨幣価値】が下がるため、【預貯金】の実質的な価値が目減りし、賃金や年金など【定額所得者】の生活が苦しくなる。一方、借金の実質的な負担は軽くなるため、【債務者】には有利になる。"},
  {"id": "seikeix18", "s": "seikei", "lv": 1, "topic": "累進課税", "q": "所得税に累進課税制度が採用されている目的を説明せよ。", "a": "所得が多い人ほど高い【税率】を適用することで、負担能力に応じた【垂直的公平】を実現し、【所得の再分配】によって経済的な【格差】を縮小することを目的としている。景気を安定させる効果もある。"},
  {"id": "seikeix19", "s": "seikei", "lv": 1, "topic": "日本銀行の役割", "q": "日本の中央銀行である日本銀行が果たしている三つの役割を説明せよ。", "a": "日本銀行券を独占的に発行する【発券銀行】、市中の金融機関と取引し資金の貸し出しや預金の受け入れを行う【銀行の銀行】、国の資金を出し入れし国庫金を管理する【政府の銀行】という三つの役割をもつ。"},
  {"id": "seikeix20", "s": "seikei", "lv": 1, "topic": "比較生産費説", "q": "リカードの比較生産費説の内容を説明せよ。", "a": "各国が他国に比べて相対的に安く生産できる【比較優位】をもつ財の生産に【特化】し、互いに【貿易】すれば、両国全体の生産量が増えて双方が利益を得られるという説。【自由貿易】を支持する根拠となった。"},
  {"id": "seikeix21", "s": "seikei", "lv": 1, "topic": "円高の影響", "q": "円高は日本の輸出産業にどのような影響を与えるか説明せよ。", "a": "円高になると、外国から見た日本製品の【ドル建て価格】が上がるため、日本製品の価格競争力が落ちて【輸出】が不利になる。輸出企業の円に換算した売上が減るため、生産拠点を【海外】に移す動きも強まる。"},
  {"id": "seikeix22", "s": "seikei", "lv": 1, "topic": "社会保障制度", "q": "日本の社会保障制度の四つの柱を説明せよ。", "a": "保険料を出し合い病気や老齢などに備える【社会保険】、生活困窮者に最低限度の生活を保障する【公的扶助】、高齢者や障害者などを支援する【社会福祉】、感染症予防などで国民の健康を守る【公衆衛生】の四つである。"},
  {"id": "seikeix23", "s": "seikei", "lv": 1, "topic": "安保理の拒否権", "q": "国連安全保障理事会の拒否権とは何か。また、その問題点を説明せよ。", "a": "安保理の実質事項の決定には、【常任理事国】5か国すべての同意が必要とされ、1か国でも反対すれば決議できない。これを【拒否権】という。大国の利害が対立すると安保理が機能せず、【紛争】に有効に対処できないことがある。"},
  {"id": "seikeix24", "s": "seikei", "lv": 1, "topic": "汚染者負担の原則", "q": "公害対策における汚染者負担の原則（PPP）とはどのような考え方か。", "a": "公害の防止や被害の救済にかかる費用は、汚染を引き起こした【汚染者】が負担すべきだという考え方。費用を製品の価格に反映させて【外部不経済】を内部化させる。日本の公害健康被害補償法などにも取り入れられた。また故意・過失がなくても責任を負う【無過失責任】も導入された。"},
  {"id": "seikeix25", "s": "seikei", "lv": 2, "topic": "一票の格差", "q": "「一票の格差」とは何か。それが問題とされる理由を説明せよ。", "a": "選挙区によって議員1人あたりの有権者数が異なるため、有権者の一票の重みに差が生じること。憲法の【法の下の平等】に反するおそれがあり、最高裁は【違憲状態】や【違憲】の判決を出している。【議員定数】の是正が求められている。"},
  {"id": "seikeix26", "s": "seikei", "lv": 2, "topic": "プライバシーの権利", "q": "新しい人権としてのプライバシーの権利は、どのように変化してきたか。", "a": "当初は「私生活をみだりに公開されない権利」とされ、『宴のあと』事件などで認められた。情報化の進展にともない、自分の情報を自ら管理する【自己情報コントロール権】として捉えられるようになり、【個人情報保護法】が制定された。憲法第13条の【幸福追求権】が根拠とされる。"},
  {"id": "seikeix27", "s": "seikei", "lv": 2, "topic": "公共の福祉", "q": "日本国憲法における「公共の福祉」とはどのような考え方か。", "a": "人権どうしが衝突した場合にそれを【調整】するための原理であり、人権も無制限ではないことを示す。特に【経済の自由】は、社会的・経済的弱者を守るため、【精神の自由】よりも広い制約を受けるとされる（【二重の基準】）。"},
  {"id": "seikeix28", "s": "seikei", "lv": 2, "topic": "刑事手続の保障", "q": "日本国憲法が刑事手続について詳細な人権保障を定めている理由と、その内容を説明せよ。", "a": "戦前に特高警察などによる不当な逮捕や拷問が行われた反省から、法律の定める手続きによらなければ刑罰を科されない【法定手続きの保障】、法律がなければ罰せられない【罪刑法定主義】、裁判官の令状がなければ逮捕されない【令状主義】、【黙秘権】などを定めている。"},
  {"id": "seikeix29", "s": "seikei", "lv": 2, "topic": "内閣不信任と解散", "q": "衆議院の内閣不信任決議と衆議院の解散の関係を、憲法の規定にもとづいて説明せよ。", "a": "憲法第69条により、衆議院で【内閣不信任】案が可決されると、内閣は10日以内に衆議院を【解散】するか【総辞職】しなければならない。解散の場合、40日以内に【総選挙】が行われ、その後の特別国会で内閣は総辞職する。"},
  {"id": "seikeix30", "s": "seikei", "lv": 2, "topic": "司法権の独立", "q": "司法権の独立とは何か。それを保障するしくみを説明せよ。", "a": "裁判所が国会や内閣など他の権力から干渉を受けず、裁判官が【良心】に従い憲法と法律にのみ拘束されて裁判を行うこと。裁判官は【身分保障】され、【弾劾裁判】や心身の故障などの場合を除いて罷免されない。【大津事件】が先例とされる。"},
  {"id": "seikeix31", "s": "seikei", "lv": 2, "topic": "三位一体の改革", "q": "2000年代に行われた「三位一体の改革」の内容と、そのねらいを説明せよ。", "a": "国から地方への【補助金】の削減、【地方交付税】の見直し、国から地方への【税源移譲】の三つを一体的に行った改革。地方の財政的な自立を高め、【地方分権】を進めることがねらいだったが、地方の財源不足が問題となった。"},
  {"id": "seikeix32", "s": "seikei", "lv": 2, "topic": "55年体制", "q": "55年体制とはどのような政治体制であったか説明せよ。", "a": "1955年に左右の社会党が統一し、保守政党も合同して【自由民主党】が結成されたことで成立した体制。自民党が長期にわたり政権を担当し、野党第一党の【日本社会党】が改憲阻止に必要な3分の1程度の議席をもった。1993年の【非自民連立政権】の成立で崩壊した。"},
  {"id": "seikeix33", "s": "seikei", "lv": 2, "topic": "財政の三機能", "q": "政府が行う経済活動である財政には、どのような三つの機能があるか説明せよ。", "a": "道路や警察など市場では供給されにくい公共財を供給する【資源配分機能】、累進課税や社会保障で所得格差を縮める【所得再分配機能】、財政政策で景気の変動をやわらげる【経済安定化機能（景気調整機能）】の三つである。"},
  {"id": "seikeix34", "s": "seikei", "lv": 2, "topic": "ビルトイン・スタビライザー", "q": "ビルトイン・スタビライザー（自動安定化装置）のしくみを説明せよ。", "a": "財政に組み込まれた制度が景気を自動的に安定させるしくみ。好況期には【累進課税】によって税収が増え、失業者が減って【社会保障】の支出が減るため、景気の過熱が抑えられる。不況期にはその逆に作用して、【有効需要】の減少を和らげる。"},
  {"id": "seikeix35", "s": "seikei", "lv": 2, "topic": "国債の問題点", "q": "国債を大量に発行することの問題点を説明せよ。", "a": "国債の元利払いにあてる【国債費】が増えて、他の政策に使える予算が減る【財政の硬直化】が起こる。また、返済の負担を将来の世代に先送りする【世代間の不公平】や、民間の資金需要と競合して金利が上がる【クラウディング・アウト】などの問題がある。"},
  {"id": "seikeix36", "s": "seikei", "lv": 2, "topic": "公開市場操作", "q": "日本銀行の公開市場操作によって、景気はどのように調整されるか説明せよ。", "a": "不況時には日銀が金融機関から国債などを買う【買いオペレーション】で資金を供給し、市場金利を下げて企業の借り入れや投資を促す。景気過熱時には【売りオペレーション】で資金を吸収し、【金利】を上げて景気を抑える。"},
  {"id": "seikeix37", "s": "seikei", "lv": 2, "topic": "信用創造", "q": "銀行の信用創造とはどのようなしくみか説明せよ。", "a": "銀行が受け入れた預金の一部を【支払準備金】として残し、残りを貸し出す。貸し出された資金は再び別の銀行に【預金】され、さらに貸し出される。これがくり返されることで、最初の預金の何倍もの【預金通貨】が生み出されるしくみ。"},
  {"id": "seikeix38", "s": "seikei", "lv": 2, "topic": "デフレスパイラル", "q": "デフレスパイラルとはどのような状況か説明せよ。", "a": "物価の下落によって企業の【売上】や利益が減り、【賃金】の引き下げや雇用の削減が行われる。その結果、家計の所得が減って消費が落ち込み、さらに物価が下落する。このように物価下落と【景気後退】が悪循環を起こす状況をいう。"},
  {"id": "seikeix39", "s": "seikei", "lv": 2, "topic": "直接金融と間接金融", "q": "企業が資金を調達する方法としての直接金融と間接金融の違いを説明せよ。", "a": "【直接金融】は、企業が【株式】や社債を発行して、資金の出し手から直接資金を調達する方法。【間接金融】は、家計の預金などを【銀行】が仲立ちして企業に貸し出す方法で、戦後の日本では間接金融の比重が高かった。"},
  {"id": "seikeix40", "s": "seikei", "lv": 2, "topic": "経常収支", "q": "近年の日本の経常収支の特徴を、その内訳から説明せよ。", "a": "かつては【貿易収支】の大幅な黒字が経常収支の黒字を支えていたが、近年は燃料輸入の増加や生産拠点の海外移転で貿易収支の黒字が縮小し、赤字の年もある。一方、海外への投資から得る配当や利子などの【第一次所得収支】の黒字が大きく、【経常収支】の黒字を支えている。"},
  {"id": "seikeix41", "s": "seikei", "lv": 2, "topic": "ニクソン・ショック", "q": "ブレトン・ウッズ体制が崩壊し、変動相場制へ移行した経緯を説明せよ。", "a": "アメリカはベトナム戦争や貿易収支の悪化で【ドル】が大量に流出し、金の保有量が減少した。1971年、ニクソン大統領は【金とドルの交換停止】を発表した（【ニクソン・ショック】）。スミソニアン協定による調整も失敗し、1973年に主要国は【変動相場制】へ移行した。"},
  {"id": "seikeix42", "s": "seikei", "lv": 2, "topic": "GATTの原則", "q": "GATT（関税と貿易に関する一般協定）が掲げた三原則を説明せよ。", "a": "関税を引き下げ貿易制限を減らす【自由】、ある国に与えた最も有利な貿易条件をすべての加盟国に適用する【最恵国待遇】などの【無差別】、多国間の交渉（ラウンド）で貿易ルールを決める【多角】の三原則である。"},
  {"id": "seikeix43", "s": "seikei", "lv": 2, "topic": "南北問題", "q": "南北問題とは何か。発展途上国の経済構造にふれながら、その背景を説明せよ。", "a": "主に北半球に多い先進国と、南半球に多い発展途上国との間の【経済格差】の問題。途上国の多くは植民地時代から特定の【一次産品】の輸出に依存する【モノカルチャー経済】で、工業製品に比べて一次産品の価格が低迷しがちなため、格差が拡大した。"},
  {"id": "seikeix44", "s": "seikei", "lv": 2, "topic": "ケインズの有効需要", "q": "ケインズが唱えた有効需要の原理と、それにもとづく政策を説明せよ。", "a": "一国の生産量や雇用量は、貨幣の支出をともなう【有効需要】の大きさによって決まるとした。不況で失業が生じるのは有効需要が不足しているためであり、政府が【公共投資】などで積極的に市場に介入して需要を創出すべきだと主張し、【大きな政府】の理論的根拠となった。"},
  {"id": "seikeix45", "s": "seikei", "lv": 2, "topic": "労働三権", "q": "労働三権の内容と、それが保障されている理由を説明せよ。", "a": "労働者が労働組合をつくる【団結権】、使用者と労働条件について交渉する【団体交渉権】、ストライキなどを行う【団体行動権（争議権）】の三つ。個々の労働者は使用者に比べて弱い立場にあるため、団結して【対等】に交渉できるように保障されている。"},
  {"id": "seikeix46", "s": "seikei", "lv": 2, "topic": "消費税の逆進性", "q": "消費税にはしばしば「逆進性」があると指摘される。その意味を説明せよ。", "a": "消費税は所得に関係なく同じ【税率】で課されるが、低所得者ほど所得に占める【消費】の割合が高いため、所得に対する税負担の割合が重くなる。これを【逆進性】という。対策として食料品などに【軽減税率】が導入された。"},
  {"id": "seikeix47", "s": "seikei", "lv": 2, "topic": "情報の非対称性", "q": "「情報の非対称性」が市場の失敗をもたらす理由を、具体例をあげて説明せよ。", "a": "売り手と買い手の間で商品についての【情報】に差がある状態をいう。例えば中古車市場では、買い手が品質を見分けられないため良質な商品が適正に評価されず、粗悪な商品ばかりが出回る【逆選択】が起こり、市場がうまく機能しなくなる。そのため【市場の失敗】とされる。"},
  {"id": "seikeix48", "s": "seikei", "lv": 2, "topic": "集団安全保障", "q": "国際連合の集団安全保障は、勢力均衡とどのように異なるか説明せよ。", "a": "【勢力均衡】は対立する国家群が軍事力を均衡させて戦争を防ぐ方式だが、軍拡競争を招きやすい。【集団安全保障】は対立国も含めて国際機構に加盟し、侵略などを行った国に対して全加盟国が協力して【制裁】を加える方式で、国際連合では【安全保障理事会】が中心となる。"},
  {"id": "seikeix49", "s": "seikei", "lv": 3, "topic": "統治行為論", "q": "統治行為論とはどのような考え方か。それに対する批判もあわせて説明せよ。", "a": "国家の統治の基本に関わる【高度な政治性】をもつ国家行為については、裁判所は【司法審査】の対象外とすべきだとする考え方。【砂川事件】の最高裁判決などで用いられた。しかし、裁判所が【違憲審査権】の行使を回避し、憲法による統制を弱めるとの批判がある。"},
  {"id": "seikeix50", "s": "seikei", "lv": 3, "topic": "非伝統的金融政策", "q": "日本銀行が量的緩和政策などの非伝統的な金融政策をとった理由と、その限界を説明せよ。", "a": "デフレ下で政策金利がほぼゼロまで下がり、金利の引き下げという通常の手段が使えなくなったため、日銀は【量的緩和】で国債などを大量に買い入れ、【マネタリーベース】を増やした。しかし資金需要が弱いと貸出が増えず、【流動性の罠】のように効果が限られ、【物価上昇】目標の達成には時間がかかった。"},
  {"id": "seikeix51", "s": "seikei", "lv": 3, "topic": "国際金融のトリレンマ", "q": "国際金融のトリレンマとは何か説明せよ。", "a": "【為替相場の安定（固定相場制）】、【自由な資本移動】、【金融政策の独立性】の三つを同時に実現することはできず、いずれか二つしか選べないという理論。例えばユーロ圏の各国は固定相場と資本移動の自由を選び、独自の金融政策を放棄している。"},
  {"id": "seikeix52", "s": "seikei", "lv": 3, "topic": "プライマリーバランス", "q": "日本の財政健全化で、プライマリーバランスの黒字化が目標とされる理由を説明せよ。", "a": "【プライマリーバランス（基礎的財政収支）】は、国債費を除く歳出を、国債発行以外の税収などでまかなえているかを示す。これが黒字化すれば、政策的経費を借金に頼らずに済み、経済成長率が金利を上回れば【債務残高】の対【GDP】比を安定的に引き下げられるため。"},
  {"id": "seikeix53", "s": "seikei", "lv": 3, "topic": "リーマン・ショック", "q": "2008年の世界金融危機（リーマン・ショック）が世界的に広がった理由を説明せよ。", "a": "アメリカで信用力の低い人向けの【サブプライムローン】が、他の債権と組み合わせて【証券化】され、世界中の金融機関に販売されていた。住宅価格の下落で返済が滞ると、これらの証券の価値が暴落し、大手証券会社の【リーマン・ブラザーズ】が破綻。【金融のグローバル化】により危機が世界に波及した。"},
  {"id": "seikeix54", "s": "seikei", "lv": 3, "topic": "新自由主義", "q": "1980年代に広がった新自由主義の考え方と、その具体的な政策を説明せよ。", "a": "政府の市場介入や福祉を拡大した大きな政府が財政赤字や経済の停滞を招いたと批判し、市場の機能を重視して【小さな政府】を目指す考え方。イギリスの【サッチャー】政権やアメリカのレーガン政権が、【規制緩和】や国営企業の【民営化】、減税を進めた。"},
  {"id": "seikeix55", "s": "seikei", "lv": 3, "topic": "FTAの増加", "q": "WTO体制のもとで、二国間や地域間のFTA・EPAが増えている理由を説明せよ。", "a": "【WTO】は全会一致を原則とし、加盟国の増加で利害が対立して、【ドーハ・ラウンド】の交渉が停滞した。そのため各国は、合意しやすい特定の国や地域との間で関税を撤廃する【FTA】や、投資・人の移動なども含む【EPA】を結んで、貿易の自由化を進めている。"},
  {"id": "seikeix56", "s": "seikei", "lv": 3, "topic": "少子高齢化と年金", "q": "日本の公的年金制度が少子高齢化によって抱える課題を、財政方式に着目して説明せよ。", "a": "日本の公的年金は、現役世代の保険料で高齢者の年金をまかなう【賦課方式】を基本としている。少子高齢化で年金受給者が増え、支え手の【現役世代】が減ると、保険料負担が重くなる。そのため【マクロ経済スライド】で給付を抑制するなど、【世代間の公平】の確保が課題となっている。"},
  {"id": "seikeix57", "s": "seikei", "lv": 3, "topic": "立憲主義", "q": "立憲主義とはどのような考え方か。民主主義との関係にもふれて説明せよ。", "a": "【憲法】によって国家権力を制限し、国民の【基本的人権】を保障しようとする考え方。民主主義のもとでも、多数派が少数者の人権を侵害するおそれがあるため、憲法は【多数決】でも侵せない価値を定め、権力を縛る役割を果たす。改正に特別な手続きを求める【硬性憲法】もその表れである。"},
  {"id": "seikeix58", "s": "seikei", "lv": 3, "topic": "Jカーブ効果", "q": "円安になっても、すぐには日本の貿易収支が改善しないことがある。その理由を説明せよ。", "a": "円安直後は、すでに結ばれた契約にもとづいて取引が行われ、輸出入の【数量】がすぐには変化しない。そのため、外貨建ての輸入品の【円建て価格】が上昇する効果が先に表れ、貿易収支が一時的に悪化する。時間がたつと輸出数量が増えて改善に向かう。これを【Jカーブ効果】という。"},
  {"id": "seikeix59", "s": "seikei", "lv": 3, "topic": "バブル崩壊と不良債権", "q": "1990年代の日本で、バブル崩壊後に景気低迷が長期化した理由を説明せよ。", "a": "バブル期に土地や株を担保に行われた過剰な融資が、【地価】や株価の暴落で回収できなくなり、銀行は多額の【不良債権】を抱えた。銀行が【貸し渋り】を行い、企業も投資を控えたため経済が停滞し、【失われた10年】とよばれる長期不況となった。"},
  {"id": "seikeix60", "s": "seikei", "lv": 3, "topic": "集団的自衛権", "q": "集団的自衛権とは何か。日本政府の解釈の変化をふまえて説明せよ。", "a": "密接な関係にある他国への武力攻撃を、自国が攻撃されていなくても実力で阻止する権利で、【国連憲章】第51条で認められている。日本政府は従来、憲法上行使できないとしてきたが、2014年の【閣議決定】で【存立危機事態】に限り行使できると解釈を変更し、翌年【安全保障関連法】が成立した。"},
  {"id": "rinrix1", "s": "rinri", "lv": 1, "topic": "無知の知", "q": "ソクラテスの「無知の知」とはどのような考え方か説明せよ。", "a": "自分が大切な事柄について何も知らないことを自覚することこそが、真の知への出発点であるという考え方。ソクラテスは対話を通して相手に無知を自覚させる【問答法（助産術）】を用い、【魂への配慮】を説いて「【善く生きる】」ことを求めた。これを【無知の知】という。"},
  {"id": "rinrix2", "s": "rinri", "lv": 1, "topic": "イデア論", "q": "プラトンのイデア論とはどのような考え方か説明せよ。", "a": "感覚でとらえられる現実の世界は変化する不完全な【現象界】にすぎず、その背後に、理性によってのみとらえられる永遠不変の真の実在である【イデア】の世界（【イデア界】）があるとする考え方。最高のイデアは【善のイデア】とされた。"},
  {"id": "rinrix3", "s": "rinri", "lv": 1, "topic": "中庸", "q": "アリストテレスの説いた「中庸」とはどのようなものか説明せよ。", "a": "感情や行為において、過剰と不足の両極端を避けた適切な状態のこと。例えば勇気は無謀と臆病の【中庸】である。正しい行為をくり返して【習慣】づけることで身につく【習性的徳（倫理的徳）】とされた。"},
  {"id": "rinrix4", "s": "rinri", "lv": 1, "topic": "仁と礼", "q": "孔子が説いた「仁」と「礼」について、その関係を説明せよ。", "a": "【仁】は人を愛する心で、親子・兄弟間の自然な親愛の情である【孝悌】を基本とする内面的な徳である。【礼】は仁が外に表れた社会的な規範であり、孔子は自己の欲望を抑えて礼に従う【克己復礼】が仁であると説いた。"},
  {"id": "rinrix5", "s": "rinri", "lv": 1, "topic": "性善説", "q": "孟子の性善説の内容を、四端の説にふれて説明せよ。", "a": "人間は生まれつき善い性質をもつという考え方。人には他人の不幸を見過ごせない【惻隠の心】など四つの心の芽生え（【四端】）が備わっており、これを育てれば仁・義・礼・智の【四徳】が完成するとした。"},
  {"id": "rinrix6", "s": "rinri", "lv": 1, "topic": "性悪説", "q": "荀子の性悪説の内容と、そこから導かれる政治思想を説明せよ。", "a": "人間は生まれつき利益を好み欲望にまかせて争う【悪】の性質をもつとした。そのため、外から【礼】によって人間の性質を矯正する必要があると説き、礼による統治である【礼治主義】を主張した。後の【法家】の思想に影響を与えた。"},
  {"id": "rinrix7", "s": "rinri", "lv": 1, "topic": "無為自然", "q": "老子の「無為自然」とはどのような考え方か説明せよ。", "a": "万物を生み出す根源である【道（タオ）】に従い、人為的なはからいを捨てて、あるがままに生きるべきだという考え方。儒家の説く仁義などの道徳は、道が失われたことによる人為的なものだと批判し、【柔弱謙下】の生き方や、小さな共同体である【小国寡民】を理想とした。"},
  {"id": "rinrix8", "s": "rinri", "lv": 1, "topic": "四諦", "q": "ブッダ（ゴータマ・シッダッタ）が説いた四諦の内容を説明せよ。", "a": "人生は【苦】であるという苦諦、苦の原因は【煩悩】（渇愛）であるという集諦、煩悩を滅すれば苦のない【涅槃】の境地に至るという滅諦、そのための正しい修行の道である【八正道】を説く道諦の四つの真理である。"},
  {"id": "rinrix9", "s": "rinri", "lv": 1, "topic": "方法的懐疑", "q": "デカルトの「方法的懐疑」とはどのようなものか説明せよ。", "a": "確実な真理を見いだすために、少しでも疑わしいものはすべて疑ってみる方法。感覚や数学の真理さえも疑ったが、疑っている自分の存在だけは疑えないとして、「【われ思う、ゆえにわれあり】」を哲学の第一原理とした。そこから【演繹法】で知識を導いた。この方法を【方法的懐疑】という。"},
  {"id": "rinrix10", "s": "rinri", "lv": 1, "topic": "イドラ", "q": "ベーコンが説いた「イドラ」とは何か説明せよ。", "a": "正しい認識をさまたげる偏見や先入観のこと。人間という種族に共通する【種族のイドラ】、個人の性格や経験による洞窟のイドラ、言葉の不適切な使用による市場のイドラ、権威や学説の盲信による劇場のイドラの四つをあげ、これらを排して【経験】にもとづく【帰納法】による学問を説いた。"},
  {"id": "rinrix11", "s": "rinri", "lv": 1, "topic": "カントの道徳", "q": "カントは道徳的な行為をどのようなものと考えたか説明せよ。", "a": "道徳的な行為とは、結果ではなく、義務にもとづこうとする【善意志】から行われる行為であるとした。道徳法則は「〜せよ」と無条件に命じる【定言命法】の形をとり、人間は自ら立てた道徳法則に自ら従う【自律】によって自由な人格となる。"},
  {"id": "rinrix12", "s": "rinri", "lv": 1, "topic": "ベンサムの功利主義", "q": "ベンサムの功利主義では、行為の善悪をどのように判断するか説明せよ。", "a": "人間は快楽を求め苦痛を避ける存在であり、快楽をもたらす行為が善であるとした。快楽は量的に計算できるとして【快楽計算】を唱え、社会全体の快楽を最大にする「【最大多数の最大幸福】」を道徳と立法の原理とした。行為を外から規制する【制裁（サンクション）】も重視した。"},
  {"id": "rinrix13", "s": "rinri", "lv": 1, "topic": "労働の疎外", "q": "マルクスが説いた「労働の疎外」とはどのようなことか説明せよ。", "a": "本来、【労働】は人間が自らの能力を発揮し、他者とつながる本質的な活動である。しかし【資本主義】社会では、生産手段をもたない労働者が生産物や労働そのものを資本家に奪われ、労働が苦役となって人間らしさを失う。これを【疎外】という。"},
  {"id": "rinrix14", "s": "rinri", "lv": 1, "topic": "悪人正機", "q": "親鸞の「悪人正機」とはどのような考え方か説明せよ。", "a": "自力で善を積むことのできない、煩悩にまみれた【悪人】こそが、【阿弥陀仏】の救いの本来の対象であるという考え方。親鸞は念仏さえも阿弥陀仏のはからいによるものとし、すべてを仏にまかせる【絶対他力】を説いた。"},
  {"id": "rinrix15", "s": "rinri", "lv": 1, "topic": "もののあはれ", "q": "本居宣長の説いた「もののあはれ」と「真心」について説明せよ。", "a": "宣長は、物事にふれて素直に心が動く感情を【もののあはれ】とよび、それを知ることが人間の本来のあり方だとした。また、儒教や仏教の影響である【漢意】を排し、生まれながらのありのままの心である【真心】に従って生きることを説いた。彼は【国学】を大成した。"},
  {"id": "rinrix16", "s": "rinri", "lv": 1, "topic": "青年期", "q": "青年期を表す「マージナル・マン（境界人）」と「心理的離乳」について説明せよ。", "a": "レヴィンは、青年は子どもの集団にも大人の集団にも完全には属さない不安定な存在であるとして【マージナル・マン】とよんだ。ホリングワースは、青年期に親から精神的に自立しようとすることを【心理的離乳】とよんだ。青年期は【自我のめざめ】の時期でもある。"},
  {"id": "rinrix17", "s": "rinri", "lv": 2, "topic": "ミルの功利主義", "q": "ミルの功利主義は、ベンサムの功利主義をどのように修正したか説明せよ。", "a": "ベンサムが快楽を量的に計算できるとしたのに対し、ミルは快楽には【質】の違いがあり、精神的快楽は肉体的快楽よりも優れているとした（【質的功利主義】）。「満足した豚より不満足な人間がよい」と述べ、外的制裁よりも良心による【内的制裁】を重視した。"},
  {"id": "rinrix18", "s": "rinri", "lv": 2, "topic": "ヘーゲルの人倫", "q": "ヘーゲルが説いた「人倫」とはどのようなものか、その三段階をふまえて説明せよ。", "a": "人倫とは、外面的な【法】と内面的な【道徳】が【弁証法】的に統合されたものであり、自由が具体的に実現された共同体である。人倫は、愛で結ばれる【家族】、欲望の体系である市民社会を経て、両者を統合した国家において完成するとした。"},
  {"id": "rinrix19", "s": "rinri", "lv": 2, "topic": "実存の三段階", "q": "キルケゴールの説いた実存の三段階について説明せよ。", "a": "人は、快楽を求めて生きるがやがて【絶望】に陥る【美的実存】、良心に従い義務を果たそうとするが自らの無力さに挫折する【倫理的実存】を経て、単独者として神の前に立ち、信仰に生きる【宗教的実存】へと至るとした。"},
  {"id": "rinrix20", "s": "rinri", "lv": 2, "topic": "ニーチェの超人", "q": "ニーチェが「神は死んだ」と述べた意味と、彼が理想とした人間像を説明せよ。", "a": "キリスト教的な価値観が力を失い、最高の価値が無価値となる【ニヒリズム】の到来を宣言した。キリスト教道徳は弱者の強者へのねたみ（【ルサンチマン】）から生まれた奴隷道徳だと批判し、【力への意志】にもとづき、【永劫回帰】の運命を肯定して新たな価値を創造する【超人】を理想とした。"},
  {"id": "rinrix21", "s": "rinri", "lv": 2, "topic": "実存は本質に先立つ", "q": "サルトルの「実存は本質に先立つ」という言葉の意味を説明せよ。", "a": "人間は、あらかじめ本質が定められて生まれてくるのではなく、まず存在し、自らの【自由】な選択によって自分のあり方をつくっていく存在だという意味。人間は「【自由の刑】に処されている」とし、自らの選択が全人類に関わるため、社会に参加する【アンガージュマン】が大切だとした。"},
  {"id": "rinrix22", "s": "rinri", "lv": 2, "topic": "限界状況", "q": "ヤスパースの説いた「限界状況」と「実存的交わり」について説明せよ。", "a": "死・苦悩・争い・罪責など、人間の力では避けられない壁を【限界状況】とよんだ。人はそれに直面して挫折するとき、自己を超えた【超越者（包括者）】に出会い、真の実存に目覚める。また、他者と誠実に語り合う【実存的交わり（愛しながらの戦い）】を重視した。"},
  {"id": "rinrix23", "s": "rinri", "lv": 2, "topic": "朱子学と陽明学", "q": "朱子学と陽明学では、人間の心と理の関係についてどのように考えが異なるか説明せよ。", "a": "朱子は、人間の本来の性は理であるとする【性即理】を説き、事物の理を一つずつ窮める【格物致知】を重んじた。これに対して王陽明は、心そのものが理であるとする【心即理】を説き、生まれつきの良知を発揮することを重視し、知と行は一体であるという【知行合一】を唱えた。"},
  {"id": "rinrix24", "s": "rinri", "lv": 2, "topic": "大乗仏教", "q": "大乗仏教は上座部仏教とどのように異なるか説明せよ。", "a": "上座部仏教が出家者の厳しい修行による自己の解脱を重視し、【阿羅漢】を理想としたのに対し、大乗仏教は在家者も含めたすべての人々の救済をめざし、自らの悟りとともに他者の救済にも努める【菩薩】を理想とした。【六波羅蜜】の実践を説き、【空】の思想を展開した。"},
  {"id": "rinrix25", "s": "rinri", "lv": 2, "topic": "只管打坐", "q": "道元の「只管打坐」と「修証一等」について説明せよ。", "a": "道元は、ただひたすら坐禅に打ち込む【只管打坐】を説いた。坐禅によって身も心も一切の執着から離れる【身心脱落】の境地に至るとした。また、坐禅は悟りのための手段ではなく、修行そのものが悟りであるという【修証一等】を唱えた。彼は【曹洞宗】の開祖である。"},
  {"id": "rinrix26", "s": "rinri", "lv": 2, "topic": "古学", "q": "伊藤仁斎と荻生徂徠は、それぞれ朱子学をどのように批判したか説明せよ。", "a": "伊藤仁斎は、『論語』などの原典を直接読む【古義学】を唱え、朱子学の理を批判して、日常の人間関係における【誠】の心と仁愛を重視した。荻生徂徠は、古代の言葉の研究にもとづく【古文辞学】を唱え、道とは聖人が天下を安んじるために作った【礼楽刑政】であるとした。"},
  {"id": "rinrix27", "s": "rinri", "lv": 2, "topic": "独立自尊", "q": "福沢諭吉の「独立自尊」とはどのような考え方か説明せよ。", "a": "人は生まれながらに平等であるという【天賦人権】の考えにもとづき、各人が他に依存せず自らの判断と責任で生きる【独立自尊】の精神を説いた。そのためには日常に役立つ【実学】を学ぶことが必要とし、「一身独立して【一国独立】す」と述べた。"},
  {"id": "rinrix28", "s": "rinri", "lv": 2, "topic": "二つのJ", "q": "内村鑑三の「二つのJ」とはどのような考え方か説明せよ。", "a": "内村は【イエス（Jesus）】と【日本（Japan）】の二つに生涯をささげることを誓った。武士道の精神をキリスト教の土台とし、教会や儀式にとらわれず聖書に直接もとづいて信仰する【無教会主義】を唱えた。日露戦争に際しては【非戦論】を主張した。"},
  {"id": "rinrix29", "s": "rinri", "lv": 2, "topic": "自己本位", "q": "夏目漱石の「自己本位」とはどのような考え方か説明せよ。", "a": "漱石は、日本の近代化は西洋に迫られた【外発的開化】であり表面的だと批判した。そのうえで、他人に追随するのではなく、自己の内面に根ざして主体的に生きる【自己本位】を説いた。晩年には、私を去って天に従う【則天去私】の境地を求めたとされる。"},
  {"id": "rinrix30", "s": "rinri", "lv": 2, "topic": "アガペー", "q": "イエスが説いた「神の愛（アガペー）」とはどのような愛か説明せよ。", "a": "【アガペー】は、罪深い人間に対しても無差別・無償に注がれる神の愛である。イエスはこれにもとづき、形式的な【律法主義】を批判し、「【神への愛】」と、敵をも愛する「【隣人愛】」を最も重要な教えとした。"},
  {"id": "rinrix31", "s": "rinri", "lv": 2, "topic": "ストア派とエピクロス派", "q": "ストア派とエピクロス派は、幸福な生き方についてどのように考えたか比較して説明せよ。", "a": "ストア派のゼノンは、宇宙を貫く理性（ロゴス）に従い、情念に動かされない【アパテイア】の境地を理想とし、「【自然に従って生きよ】」と説いた。一方エピクロスは、快楽を善としつつも、身体の苦痛や魂の不安から解放された【アタラクシア】を理想とし、「【隠れて生きよ】」と説いた。"},
  {"id": "rinrix32", "s": "rinri", "lv": 2, "topic": "ロールズの正義論", "q": "ロールズの『正義論』の内容を、功利主義批判とあわせて説明せよ。", "a": "功利主義は全体の幸福のために個人の権利を犠牲にしうると批判した。自分の立場を知らない【無知のヴェール】のもとで人々が合意する原理として、各人に平等な基本的自由を保障する原理と、不平等は【公正な機会均等】と、最も恵まれない人の利益を最大にする【格差原理】を満たす場合に限り許されるという原理を示した。"},
  {"id": "rinrix33", "s": "rinri", "lv": 3, "topic": "間柄的存在", "q": "和辻哲郎は人間をどのような存在と考えたか。西洋近代の個人主義と比較して説明せよ。", "a": "和辻は、西洋近代の倫理学が孤立した【個人】を出発点とすることを批判した。人間は個人であると同時に社会的な存在でもあり、人と人との関係において成り立つ【間柄的存在】であるとした。倫理とは、個人と社会が互いに否定しあう【弁証法】的な運動の中で実現されるとした。"},
  {"id": "rinrix34", "s": "rinri", "lv": 3, "topic": "純粋経験", "q": "西田幾多郎の「純粋経験」とはどのようなものか説明せよ。", "a": "音楽に聴き入っているときのように、見る自己と見られる対象とが分かれる以前の、主観と客観が一体となった直接的な経験（【主客未分】）のこと。西田はこの【純粋経験】を真の実在とし、西洋哲学の【主客二元論】を乗り越えようとした。【禅】の体験が背景にあり、主著は『善の研究』である。"},
  {"id": "rinrix35", "s": "rinri", "lv": 3, "topic": "死への存在", "q": "ハイデガーは、人間が本来的な生き方を取り戻すにはどうすべきだと考えたか説明せよ。", "a": "人間（【現存在】）は、日常において世間に埋没し、自分を見失った【ダス・マン（世人）】として生きている。しかし、自らが【死への存在】であることを自覚し、死に向き合う【先駆的決意】をもつことによって、かけがえのない本来的な自己を取り戻すことができるとした。"},
  {"id": "rinrix36", "s": "rinri", "lv": 3, "topic": "フーコーの権力論", "q": "フーコーは近代社会における権力をどのようにとらえたか説明せよ。", "a": "近代の権力は、王のように上から暴力で支配するものではなく、学校・病院・軍隊などで人々を【規律・訓練】し、規範を内面化させて自発的に従わせるものだととらえた（【規律権力】）。その象徴として、常に監視されていると意識させる【パノプティコン】をあげた。また、正常と【狂気】を区別する近代理性のあり方も批判した。"},
  {"id": "rinrix37", "s": "rinri", "lv": 3, "topic": "コミュニケーション的合理性", "q": "ハーバーマスの「コミュニケーション的合理性」とはどのような考え方か説明せよ。", "a": "目的達成のための効率を重視する【道具的理性】に対し、人々が対等な立場で自由に討議し、相互理解と【合意】を形成する理性のはたらきを【コミュニケーション的合理性】とよんだ。行政や市場の論理が日常の【生活世界】を侵す「生活世界の植民地化」を批判した。"},
  {"id": "rinrix38", "s": "rinri", "lv": 3, "topic": "アーレントの活動", "q": "アーレントは人間の営みをどのように分類し、何を重視したか説明せよ。", "a": "人間の営みを、生命維持のための【労働】、道具や作品をつくる【仕事】、他者と言葉を交わして共同体に関わる【活動】の三つに分けた。近代では労働が優位となり公共性が失われたと批判し、多様な人々が【公共性】の場で語り合う活動を重視した。それが失われると全体主義を招くとした。"},
  {"id": "rinrix39", "s": "rinri", "lv": 3, "topic": "潜在能力", "q": "アマルティア・センの「潜在能力（ケイパビリティ）」の考え方を説明せよ。", "a": "センは、豊かさを所得や財の量だけでとらえるのではなく、人がその財を用いて実際に何ができるか、どのような状態でありうるかという【機能】の組み合わせ、すなわち【潜在能力】の大きさで評価すべきだとした。この考えは【人間の安全保障】や、国連の【人間開発指数】の基礎となった。"},
  {"id": "rinrix40", "s": "rinri", "lv": 3, "topic": "道具的理性批判", "q": "ホルクハイマーとアドルノは、近代の理性をどのように批判したか説明せよ。", "a": "彼らは『【啓蒙の弁証法】』で、人間を解放するはずの啓蒙的理性が、自然や人間を支配・管理するための効率性ばかりを追求する【道具的理性】に変質したと批判した。それが【ナチズム】などの全体主義や、大衆を画一化する文化産業を生んだとした。彼らは【フランクフルト学派】の思想家である。"},
  {"id": "physx1", "s": "phys", "lv": 1, "topic": "慣性の法則", "q": "走っているバスが急ブレーキをかけると、乗客が前のめりになる理由を説明せよ。", "a": "物体は外から力を受けなければ、その運動状態を保とうとする性質（【慣性】）をもつ。バスが急に減速しても、乗客の体は【慣性の法則】によってそれまでの【速度】で前に進み続けようとするため、前のめりになる。"},
  {"id": "physx2", "s": "phys", "lv": 1, "topic": "作用・反作用", "q": "ロケットが真空の宇宙空間でも加速できる理由を説明せよ。", "a": "ロケットは燃料を燃やしたガスを後方へ勢いよく噴き出す。このときロケットがガスを押す力の【反作用】として、ガスがロケットを前方へ押す力がはたらく（【作用・反作用の法則】）。空気を押す必要はないため、【真空】中でも加速できる。"},
  {"id": "physx3", "s": "phys", "lv": 1, "topic": "浮力", "q": "鉄でできた船が水に浮くことができる理由を説明せよ。", "a": "水中の物体は、押しのけた水の【重さ】に等しい大きさの上向きの【浮力】を受ける（【アルキメデスの原理】）。船は内部が空洞で体積が大きく、多くの水を押しのけるため、浮力が船の重力とつり合い、浮くことができる。"},
  {"id": "physx4", "s": "phys", "lv": 1, "topic": "光の屈折", "q": "水の入ったプールの底が、実際より浅く見えるのはなぜか説明せよ。", "a": "水中から空気中へ出る光は、水面で【屈折】し、【屈折角】が入射角より大きくなる。目は光が【直進】してきたと判断するため、屈折した光を延長した位置、つまり実際より浅い位置に底があるように見える。"},
  {"id": "physx5", "s": "phys", "lv": 1, "topic": "ドップラー効果", "q": "救急車が近づくときはサイレンの音が高く、遠ざかるときは低く聞こえる理由を説明せよ。", "a": "音源が近づくと、音源が進む向きの音波の【波長】が短く縮められ、観測者に届く音の【振動数】が大きくなるため高く聞こえる。遠ざかるときは波長が長くなり振動数が小さくなるため低く聞こえる。この現象を【ドップラー効果】という。"},
  {"id": "physx6", "s": "phys", "lv": 1, "topic": "静電誘導", "q": "こすって帯電させた下じきに、帯電していない小さな紙片が引きつけられる理由を説明せよ。", "a": "帯電した下じきを近づけると、紙片の中で【静電誘導】（誘電分極）が起こり、下じきに近い側に下じきと【異符号】の電荷が、遠い側に同符号の電荷が現れる。近い側の【引力】が遠い側の斥力より大きいため、紙片は引きつけられる。"},
  {"id": "physx7", "s": "phys", "lv": 1, "topic": "電磁誘導", "q": "コイルに磁石を出し入れすると電流が流れる理由を説明せよ。", "a": "磁石を動かすとコイルを貫く【磁束】が変化する。このときコイルには磁束の変化を妨げる向きに【誘導起電力】が生じ、電流が流れる。この現象を【電磁誘導】といい、発電機の原理となっている。"},
  {"id": "physx8", "s": "phys", "lv": 1, "topic": "比熱", "q": "晴れた日の昼、海岸では陸のほうが海より早く温まる。その理由を説明せよ。", "a": "水は陸の岩石や土に比べて【比熱】が大きく、同じ量の熱を受けても【温度】が上がりにくいため。陸は比熱が小さく温まりやすいので、昼は陸のほうが高温になり、海から陸へ向かう【海風】が吹く。"},
  {"id": "physx9", "s": "phys", "lv": 1, "topic": "光の分散", "q": "プリズムに白色光を通すと、光が虹のような色の帯に分かれる理由を説明せよ。", "a": "白色光はさまざまな【波長】の光が混ざったものである。ガラスの【屈折率】は光の波長によって異なり、波長の短い紫の光ほど大きく屈折する。そのため各色の光が異なる角度で屈折して分かれる。この現象を光の【分散】という。"},
  {"id": "physx10", "s": "phys", "lv": 1, "topic": "力学的エネルギー保存", "q": "空気抵抗や摩擦が無視できるとき、振り子のおもりは最初と同じ高さまで上がる。その理由を説明せよ。", "a": "おもりにはたらく糸の張力は運動の向きと常に垂直で【仕事】をしないため、重力だけが仕事をする。このとき【位置エネルギー】と【運動エネルギー】の和である【力学的エネルギー】が保存されるので、最初と同じ高さまで上がる。"},
  {"id": "physx11", "s": "phys", "lv": 2, "topic": "終端速度", "q": "雨粒は高いところから落ちてきても、ある一定の速さ以上にはならない。その理由を説明せよ。", "a": "雨粒には下向きの【重力】と、速さが増すほど大きくなる上向きの【空気抵抗】がはたらく。速さが増して空気抵抗が重力とつり合うと、【合力】が0になり加速しなくなるため、一定の速さ（【終端速度】）で落下する。"},
  {"id": "physx12", "s": "phys", "lv": 2, "topic": "人工衛星", "q": "地球のまわりを回る人工衛星が、地上に落ちてこない理由を説明せよ。", "a": "人工衛星は地球の【万有引力】を受けて常に地球に向かって落下しているが、同時に大きな速さで水平方向に進んでいる。万有引力が円運動の【向心力】となり、落下しても地表の曲がりに沿って進むため、地表に近づかずに【等速円運動】を続ける。"},
  {"id": "physx13", "s": "phys", "lv": 2, "topic": "うなり", "q": "振動数がわずかに異なる二つのおんさを同時に鳴らすと、音が強弱をくり返して聞こえる理由を説明せよ。", "a": "振動数がわずかに異なる二つの音波が【重ね合わせ】られると、二つの波の山どうしが重なって強めあう時と、山と谷が重なって弱めあう時が周期的にくり返される。これを【うなり】といい、1秒あたりのうなりの回数は二つの音の【振動数の差】に等しい。"},
  {"id": "physx14", "s": "phys", "lv": 2, "topic": "薄膜の干渉", "q": "シャボン玉の表面が色づいて見える理由を説明せよ。", "a": "膜の表面で反射した光と、膜の裏面で反射した光が重なり合って【干渉】する。二つの光の【光路差】は膜の【厚さ】によって変わり、強めあう光の【波長】も異なるため、場所によって特定の色の光が強めあって色づいて見える。"},
  {"id": "physx15", "s": "phys", "lv": 2, "topic": "回折", "q": "塀の向こう側にいる人の声は聞こえるのに、姿は見えない理由を説明せよ。", "a": "波が障害物の背後に回りこむ現象を【回折】といい、波長が障害物やすき間の大きさと同程度以上のときに顕著になる。音波の【波長】は数十cm〜数mと塀の大きさに近く回折しやすいが、光の波長は約0.4〜0.8μmと非常に【短い】ため、ほとんど回折しない。"},
  {"id": "physx16", "s": "phys", "lv": 2, "topic": "レンツの法則", "q": "銅やアルミニウムの管の中に強い磁石を落とすと、ゆっくり落ちる理由を説明せよ。", "a": "磁石が落下すると管を貫く磁束が変化し、管に【電磁誘導】による【渦電流】が流れる。【レンツの法則】により、この電流は磁束の変化を妨げる向きの磁場をつくるため、磁石には運動を妨げる向きの力がはたらき、ゆっくり落下する。"},
  {"id": "physx17", "s": "phys", "lv": 2, "topic": "高電圧送電", "q": "発電所から遠くへ電気を送るとき、高い電圧で送電する理由を説明せよ。", "a": "同じ【電力】を送る場合、電圧を高くすると電流を小さくできる。送電線の抵抗で失われる電力（【ジュール熱】）は電流の2乗に比例するため、高電圧にすると【送電損失】を大幅に減らせる。交流は【変圧器】で電圧を容易に変えられるので送電に用いられる。"},
  {"id": "physx18", "s": "phys", "lv": 2, "topic": "断熱圧縮", "q": "自転車の空気入れで空気を急に圧縮すると、空気入れが熱くなる理由を説明せよ。", "a": "急に圧縮すると、外部と熱をやりとりする時間がない【断熱変化】となる。【熱力学第一法則】より、外部からされた【仕事】がすべて気体の【内部エネルギー】の増加となるため、気体の温度が上昇する。"},
  {"id": "physx19", "s": "phys", "lv": 2, "topic": "光電効果", "q": "金属に光を当てたとき、強い赤色光では電子が飛び出さないのに、弱い紫外線では飛び出すことがある。その理由を説明せよ。", "a": "光は振動数に比例するエネルギーをもつ粒子（【光子】）の集まりである。電子は光子1個のエネルギーを受け取り、それが金属の【仕事関数】を超えたときだけ飛び出す。紫外線は【振動数】が大きく光子1個のエネルギーが大きいため電子が飛び出すが、赤色光は強くしても光子1個のエネルギーが足りない。これを【光電効果】という。"},
  {"id": "physx20", "s": "phys", "lv": 2, "topic": "金属の抵抗と温度", "q": "金属の電気抵抗が、温度が上がると大きくなる理由を説明せよ。", "a": "金属中の電流は【自由電子】の移動によるものである。温度が上がると金属の【陽イオン】の【熱振動】が激しくなり、自由電子が陽イオンに衝突して進みにくくなるため、【抵抗率】が大きくなる。"},
  {"id": "physx21", "s": "phys", "lv": 3, "topic": "空の色", "q": "昼間の空が青く見え、夕焼けが赤く見える理由を説明せよ。", "a": "太陽光が大気中の分子に当たると、波長より小さい粒子による【レイリー散乱】が起こり、波長の【短い】青い光ほど強く散乱される。昼は散乱された青い光が空全体から届くため青く見える。夕方は光が大気中を通る【距離】が長く、青い光は途中で散乱されて失われ、【波長の長い】赤い光が届くため赤く見える。"},
  {"id": "physx22", "s": "phys", "lv": 3, "topic": "核分裂のエネルギー", "q": "ウランの核分裂で大きなエネルギーが放出される理由を、質量とエネルギーの関係から説明せよ。", "a": "ウランのような重い原子核は、核子1個あたりの【結合エネルギー】が中程度の質量の原子核より小さい。核分裂で生じる原子核は結合エネルギーが大きく、分裂後の質量の和は分裂前より小さくなる。この【質量欠損】に相当するエネルギーが、【E=mc²】の関係にしたがって放出される。"},
  {"id": "physx23", "s": "phys", "lv": 3, "topic": "静電遮蔽", "q": "金属の箱で囲まれた内部には、外部の電場の影響が及ばない理由を説明せよ。", "a": "導体に外部電場がかかると、【自由電子】が移動して表面に電荷が現れ、外部電場を打ち消す電場をつくる。電子の移動は導体内部の電場が0になるまで続くため、静電平衡では導体は【等電位】となり、中空部分の電場も0になる。これを【静電遮蔽】という。"},
  {"id": "physx24", "s": "phys", "lv": 3, "topic": "熱機関の効率", "q": "熱機関の熱効率を100％にすることができない理由を説明せよ。", "a": "【熱力学第二法則】によれば、熱は高温から低温へ自然に移動するが、一つの熱源から得た熱をすべて【仕事】に変え続けることはできない。熱機関はサイクルを続けるために、受け取った熱の一部を必ず【低温熱源】へ捨てる必要があるため、熱効率は100％未満になる。【不可逆変化】の存在もその背景にある。"},
  {"id": "physx25", "s": "phys", "lv": 3, "topic": "線スペクトル", "q": "水素原子の出す光が、とびとびの波長だけをもつ線スペクトルになる理由を説明せよ。", "a": "ボーアの理論によれば、原子内の電子はとびとびの【エネルギー準位】の状態しかとれない。電子が高いエネルギー準位から低い準位へ移るとき、その【エネルギー差】に等しいエネルギーをもつ【光子】を放出する。エネルギー差がとびとびの値をとるため、光の波長もとびとびになり【線スペクトル】となる。"},
  {"id": "chemx1", "s": "chem", "lv": 1, "topic": "イオン結晶の性質", "q": "塩化ナトリウムの結晶は固体では電気を通さないが、融解すると電気を通す。その理由を説明せよ。", "a": "塩化ナトリウムは陽イオンと陰イオンが【イオン結合】で規則正しく並んだ【イオン結晶】である。固体ではイオンが固定されて動けないが、融解すると【イオン】が自由に動けるようになり、電荷を運ぶため【電気伝導性】を示す。"},
  {"id": "chemx2", "s": "chem", "lv": 1, "topic": "金属の性質", "q": "金属が電気や熱をよく通し、展性・延性をもつ理由を説明せよ。", "a": "金属では、原子の価電子が特定の原子に束縛されずに結晶全体を動き回る【自由電子】となり、【金属結合】をつくる。自由電子が電荷や熱を運ぶため電気や熱をよく通す。また原子の位置がずれても自由電子が結合を保つため、【展性・延性】を示す。"},
  {"id": "chemx3", "s": "chem", "lv": 1, "topic": "水の沸点", "q": "水の沸点が、分子量が同程度の他の水素化合物に比べて著しく高い理由を説明せよ。", "a": "水分子は【電気陰性度】の大きい酸素原子と水素原子からなり、強い【極性】をもつ。そのため分子間に【水素結合】が形成され、分子どうしが強く引き合っている。これを切るために大きなエネルギーが必要となるため、沸点が高い。"},
  {"id": "chemx4", "s": "chem", "lv": 1, "topic": "貴ガス", "q": "ヘリウムやネオンなどの貴ガスが、他の原子と化合物をつくりにくい理由を説明せよ。", "a": "貴ガスの原子は、最外殻の電子配置が非常に安定な【閉殻】（またはそれに準じる構造）になっている。そのため電子を失ったり受け取ったりして【イオン】になりにくく、【価電子】の数も0とみなされ、他の原子と結合しにくい。"},
  {"id": "chemx5", "s": "chem", "lv": 1, "topic": "酸性雨", "q": "酸性雨はどのようなしくみで発生するか。原因となる物質にふれて説明せよ。", "a": "化石燃料の燃焼によって発生する【硫黄酸化物】や【窒素酸化物】が、大気中で酸化され雨水に溶けると、【硫酸】や硝酸となって強い酸性を示す。こうして通常の雨（pH5.6程度）より酸性の強い【酸性雨】が降る。"},
  {"id": "chemx6", "s": "chem", "lv": 1, "topic": "トタン", "q": "鉄板に亜鉛をめっきしたトタンは、傷がついても鉄がさびにくい理由を説明せよ。", "a": "亜鉛は鉄よりも【イオン化傾向】が大きい。そのため傷がついて鉄が露出しても、亜鉛が先に【酸化】されて陽イオンとなって溶け出し、鉄の酸化を防ぐ。このように、亜鉛が【犠牲】となって鉄を守るはたらきをする。"},
  {"id": "chemx7", "s": "chem", "lv": 1, "topic": "ダイヤモンドと黒鉛", "q": "ダイヤモンドと黒鉛はどちらも炭素からなるが、硬さや電気伝導性が異なる。その理由を説明せよ。", "a": "両者は互いに【同素体】である。ダイヤモンドは各炭素原子が4個の原子と【共有結合】で正四面体状に結びつき、非常に硬く電気を通さない。黒鉛は3個の原子と結合した平面状の層が重なり、層間は弱い【分子間力】で結ばれるため軟らかく、残りの【価電子】が層内を動くので電気を通す。"},
  {"id": "chemx8", "s": "chem", "lv": 1, "topic": "圧力鍋", "q": "圧力鍋を使うと、食材が短時間で調理できる理由を説明せよ。", "a": "液体は【飽和蒸気圧】が外圧と等しくなる温度で沸騰する。圧力鍋では内部の【圧力】が大気圧より高くなるため、水の【沸点】が100℃より高くなる。より高温で加熱できるため、食材が短時間で調理できる。"},
  {"id": "chemx9", "s": "chem", "lv": 1, "topic": "中和", "q": "胃酸が出すぎたときに、炭酸水素ナトリウムを含む胃腸薬を飲むのはなぜか説明せよ。", "a": "胃酸の主成分は【塩酸】である。炭酸水素ナトリウムは水溶液中で弱い【塩基性】を示し、塩酸と【中和】反応を起こして塩化ナトリウム、水、【二酸化炭素】を生じる。これにより過剰な胃酸を打ち消すことができる。"},
  {"id": "chemx10", "s": "chem", "lv": 1, "topic": "電気分解", "q": "塩化銅(Ⅱ)水溶液を電気分解すると、陰極に銅が析出する理由を説明せよ。", "a": "水溶液中の銅(Ⅱ)イオンは【陽イオン】であるため、電源の負極につながれた【陰極】に引き寄せられる。陰極で電子を受け取る【還元】反応が起こり、【銅】が析出する。陽極では塩化物イオンが電子を失って塩素が発生する。"},
  {"id": "chemx11", "s": "chem", "lv": 2, "topic": "凝固点降下", "q": "冬に凍結防止のため道路に塩化カルシウムをまくのはなぜか説明せよ。", "a": "水に塩化カルシウムなどの不揮発性の物質が溶けると、溶液の【凝固点】は純粋な水より低くなる（【凝固点降下】）。塩化カルシウムは水中で電離して多くの【粒子】を生じ、さらに溶ける際に【溶解熱】を放出するため、凍結を効果的に防ぐことができる。"},
  {"id": "chemx12", "s": "chem", "lv": 2, "topic": "浸透圧", "q": "野菜に塩をふると、しばらくして水が出てくる理由を説明せよ。", "a": "細胞膜は水は通すが溶質を通しにくい【半透膜】の性質をもつ。細胞の外側の塩の濃度が内側より高くなると、濃度を等しくしようとして水が【濃度】の低い細胞内から高い外側へ移動する。この【浸透】によって細胞から水が出てくる。生じる圧力を【浸透圧】という。"},
  {"id": "chemx13", "s": "chem", "lv": 2, "topic": "ルシャトリエの原理", "q": "ハーバー・ボッシュ法でアンモニアを合成するとき、高圧にする理由を説明せよ。", "a": "N₂＋3H₂⇄2NH₃の反応では、正反応が進むと気体の【分子数】が減る。【ルシャトリエの原理】により、圧力を高くすると圧力を下げる向き、つまり分子数が減る正反応の向きに【平衡】が移動するため、アンモニアの生成量が増える。なお【触媒】は平衡に達する時間を短くする。"},
  {"id": "chemx14", "s": "chem", "lv": 2, "topic": "触媒", "q": "触媒が反応速度を大きくするしくみを説明せよ。また、平衡には影響するか。", "a": "触媒は反応の経路を変えて【活性化エネルギー】を小さくするため、そのエネルギーを超えられる分子の割合が増え、【反応速度】が大きくなる。正反応と逆反応の速度をともに大きくするので、平衡に達するまでの時間は短くなるが、【平衡】の位置や【反応熱】は変わらない。"},
  {"id": "chemx15", "s": "chem", "lv": 2, "topic": "温度と反応速度", "q": "温度を上げると反応速度が大きくなる理由を説明せよ。", "a": "温度が上がると分子の【熱運動】が激しくなり、【活性化エネルギー】以上のエネルギーをもつ分子の割合が急激に増える。そのため反応が起こる有効な【衝突】の回数が増え、【反応速度】が大きくなる。"},
  {"id": "chemx16", "s": "chem", "lv": 2, "topic": "緩衝液", "q": "酢酸と酢酸ナトリウムの混合水溶液に少量の酸を加えても、pHがほとんど変化しない理由を説明せよ。", "a": "この溶液には【酢酸イオン】と酢酸分子が多量に存在する。酸を加えるとH⁺は酢酸イオンと反応して弱酸の酢酸になり、塩基を加えるとOH⁻は酢酸と【中和】して水になる。そのため水素イオン濃度がほとんど変化しない。このような溶液を【緩衝液】といい、その作用を【緩衝作用】という。"},
  {"id": "chemx17", "s": "chem", "lv": 2, "topic": "不動態", "q": "鉄やアルミニウムは希硝酸には溶けるが、濃硝酸には溶けない。その理由を説明せよ。", "a": "鉄やアルミニウムを濃硝酸に入れると、強い【酸化】作用によって金属の表面にち密な【酸化被膜】が形成される。この被膜が内部を保護するため、それ以上反応が進まなくなる。このような状態を【不動態】という。"},
  {"id": "chemx18", "s": "chem", "lv": 2, "topic": "セッケン", "q": "セッケンが油汚れを落とすしくみを説明せよ。", "a": "セッケン分子は水になじむ【親水基】と、油になじむ【疎水基（親油基）】をもつ。水中では疎水基を内側に向けて油汚れを取り囲み、【ミセル】を形成して油を水中に分散させる（【乳化】作用）。こうして油汚れを水で洗い流すことができる。"},
  {"id": "chemx19", "s": "chem", "lv": 2, "topic": "塩の加水分解", "q": "酢酸ナトリウムの水溶液が塩基性を示す理由を説明せよ。", "a": "酢酸ナトリウムは【弱酸】の酢酸と強塩基の水酸化ナトリウムからなる塩である。水中で生じた酢酸イオンの一部が水と反応して酢酸分子となり、【水酸化物イオン】を生じる。この【加水分解】によって、水溶液が【塩基性】を示す。"},
  {"id": "chemx20", "s": "chem", "lv": 2, "topic": "ダニエル電池", "q": "ダニエル電池で電流が流れるしくみを説明せよ。", "a": "亜鉛は銅より【イオン化傾向】が大きい。そのため【負極】では亜鉛が電子を放出して亜鉛イオンとなって溶け出し（酸化）、電子は導線を通って【正極】へ流れる。正極では銅(Ⅱ)イオンが電子を受け取って銅が析出する（【還元】）。素焼き板はイオンを通して電気的なつりあいを保つ。"},
  {"id": "chemx21", "s": "chem", "lv": 3, "topic": "実在気体", "q": "実在気体が、高圧・低温の条件で理想気体の状態方程式からずれる理由を説明せよ。", "a": "理想気体は分子自身の【体積】と【分子間力】を無視している。高圧では気体の体積に対して分子自身の体積の割合が大きくなり、低温では分子の熱運動が弱まって分子間力の影響が大きくなるため、【理想気体】からのずれが大きくなる。"},
  {"id": "chemx22", "s": "chem", "lv": 3, "topic": "鏡像異性体", "q": "乳酸には、化学的性質はほぼ同じだが互いに重ね合わせられない2種類の分子が存在する。その理由を説明せよ。", "a": "乳酸は、4つの異なる原子または原子団が結合した【不斉炭素原子】をもつ。そのため、実物と鏡に映した像のように、互いに重ね合わせることのできない2種類の立体構造が存在する。これらを【鏡像異性体（光学異性体）】といい、【偏光】面を回転させる向きが異なる。"},
  {"id": "chemx23", "s": "chem", "lv": 3, "topic": "アルコールの溶解性", "q": "メタノールは水によく溶けるが、炭素数の多いアルコールは水に溶けにくい。その理由を説明せよ。", "a": "アルコールのヒドロキシ基は【親水性】で、水分子と【水素結合】をつくる。しかし炭素数が多くなると、【疎水性】の炭化水素基の部分が大きくなり、分子全体として水となじみにくくなるため、水に溶けにくくなる。"},
  {"id": "chemx24", "s": "chem", "lv": 3, "topic": "共通イオン効果", "q": "塩化ナトリウムの飽和水溶液に塩化水素を通じると、塩化ナトリウムの結晶が析出する理由を説明せよ。", "a": "飽和水溶液ではNaCl⇄Na⁺＋Cl⁻の【溶解平衡】が成り立っている。塩化水素を通じると【塩化物イオン】の濃度が増加し、【ルシャトリエの原理】により、その濃度を減らす方向に平衡が移動するため、NaClの結晶が析出する。これを【共通イオン効果】という。"},
  {"id": "chemx25", "s": "chem", "lv": 3, "topic": "タンパク質の変性", "q": "卵を加熱すると白く固まり、冷やしてももとに戻らない理由を説明せよ。", "a": "タンパク質は、ポリペプチド鎖が【水素結合】などによって特定の立体構造をとっている。加熱するとこれらの結合が切れて【立体構造】がくずれ、元に戻らなくなる。これを【変性】という。【ペプチド結合】による一次構造は保たれたままである。"},
  {"id": "biox1", "s": "bio", "lv": 1, "topic": "酵素と温度", "q": "ヒトの酵素の多くが、体温付近で最もよくはたらき、高温になるとはたらかなくなる理由を説明せよ。", "a": "酵素の主成分は【タンパク質】で、特定の立体構造をもつ【活性部位】で基質と結合する。温度が上がると反応速度は増すが、高温になると立体構造が壊れて【変性】し、【失活】する。そのため体温付近の【最適温度】で最もよくはたらく。"},
  {"id": "biox2", "s": "bio", "lv": 1, "topic": "血糖値の調節", "q": "食事のあとに上昇した血糖濃度が、もとの値に戻るしくみを説明せよ。", "a": "血糖濃度が上がると、すい臓の【ランゲルハンス島】のB細胞から【インスリン】が分泌される。インスリンは細胞へのグルコースの取りこみや、肝臓での【グリコーゲン】の合成を促進するため、血糖濃度が低下してもとに戻る。"},
  {"id": "biox3", "s": "bio", "lv": 1, "topic": "体温調節", "q": "寒い環境にいるとき、ヒトの体温が保たれるしくみを説明せよ。", "a": "皮膚で寒さを感じると、【間脳の視床下部】がはたらき、【交感神経】を通じて皮膚の血管を収縮させ、熱の放散を減らす。また、甲状腺ホルモンやアドレナリンの分泌を促して代謝を高め、【ふるえ】によって筋肉で熱を生産し、【体温】を保つ。"},
  {"id": "biox4", "s": "bio", "lv": 1, "topic": "半保存的複製", "q": "DNAの半保存的複製とはどのようなしくみか説明せよ。", "a": "DNAの2本鎖がほどけて、それぞれの鎖が【鋳型】となる。鋳型の塩基に対して【相補的】な塩基をもつヌクレオチドが結合して新しい鎖が合成される。新しくできたDNAは、もとの鎖1本と新しい鎖1本からなる。これを【半保存的複製】という。"},
  {"id": "biox5", "s": "bio", "lv": 1, "topic": "光合成と呼吸", "q": "光合成と呼吸の関係を、エネルギーの流れに着目して説明せよ。", "a": "【光合成】は、光エネルギーを用いて二酸化炭素と水から【有機物】を合成し、エネルギーを化学エネルギーとして蓄える反応である。【呼吸】は有機物を酸素を用いて分解し、蓄えられたエネルギーを取り出して【ATP】を合成する反応である。"},
  {"id": "biox6", "s": "bio", "lv": 1, "topic": "ワクチン", "q": "ワクチンを接種すると、感染症にかかりにくくなる理由を説明せよ。", "a": "ワクチンは、毒性を弱めたり無毒化したりした病原体やその成分である【抗原】を含む。接種すると【獲得免疫】がはたらき、その抗原に対応する【記憶細胞】がつくられる。実際に病原体が侵入したとき、すみやかに強い【二次応答】が起こるため、発症しにくくなる。"},
  {"id": "biox7", "s": "bio", "lv": 1, "topic": "生態系の物質循環", "q": "生態系における生産者と分解者のはたらきを説明せよ。", "a": "【生産者】である植物などは、光合成によって無機物から【有機物】をつくる。【分解者】である菌類や細菌は、生物の遺体や排出物に含まれる有機物を【無機物】に分解し、再び生産者が利用できるようにする。こうして生態系の中で物質が循環する。"},
  {"id": "biox8", "s": "bio", "lv": 1, "topic": "植生の遷移", "q": "日本で裸地から森林へと植生が移り変わる遷移の過程で、陽樹林が陰樹林に移り変わる理由を説明せよ。", "a": "陽樹林が発達すると、林床に届く【光】が少なくなる。陽樹の幼木は暗い林床では育ちにくいが、【陰樹】の幼木は弱い光でも生育できる。そのため次第に陰樹が増え、やがて陰樹林となって安定した【極相】に達する。これが【遷移】の過程である。"},
  {"id": "biox9", "s": "bio", "lv": 1, "topic": "体細胞分裂", "q": "体細胞分裂で生じた2つの娘細胞が、もとの細胞と同じ遺伝情報をもつ理由を説明せよ。", "a": "分裂の前の【間期】に、DNAが正確に【複製】されて2倍になる。分裂期には、複製されたそれぞれの【染色体】が縦に裂けるように分かれて両極に移動し、2つの娘細胞に均等に分配される。そのため娘細胞はもとの細胞と同じ【遺伝情報】をもつ。"},
  {"id": "biox10", "s": "bio", "lv": 1, "topic": "腎臓のはたらき", "q": "腎臓で尿がつくられるしくみを、ろ過と再吸収に着目して説明せよ。", "a": "糸球体で血液がろ過され、タンパク質や血球以外の成分が【ボーマンのう】へ出て【原尿】となる。原尿が細尿管を通る間に、グルコースなどの必要な物質や水が毛細血管へ【再吸収】され、残ったものが【尿】となる。"},
  {"id": "biox11", "s": "bio", "lv": 2, "topic": "アブシシン酸", "q": "植物が乾燥すると気孔を閉じるしくみと、その意義を説明せよ。", "a": "乾燥すると植物体内で【アブシシン酸】が合成され、孔辺細胞からカリウムイオンが流出して膨圧が低下し、【気孔】が閉じる。これにより【蒸散】による水の損失を防ぎ、乾燥に耐えることができる。ただし同時に【二酸化炭素】の取りこみも減る。"},
  {"id": "biox12", "s": "bio", "lv": 2, "topic": "光屈性", "q": "植物の茎が光の来る方向に曲がって伸びるしくみを説明せよ。", "a": "光が一方から当たると、植物ホルモンの【オーキシン】が光の当たらない【影側】へ移動する。茎ではオーキシンが細胞の【伸長】を促すため、影側の細胞がより大きく伸び、茎は光の来る方へ曲がる。これを正の【光屈性】という。"},
  {"id": "biox13", "s": "bio", "lv": 2, "topic": "工業暗化", "q": "イギリスで工業化の進行とともにオオシモフリエダシャクの暗色型が増えた理由を説明せよ。", "a": "工業化で【すす】により樹皮が黒くなると、明色型は目立って鳥に【捕食】されやすくなり、暗色型は目立たず生き残りやすくなった。暗色型が多く子を残した結果、集団中の暗色型の割合が増加した。これは【自然選択】による【適応】進化の例である。"},
  {"id": "biox14", "s": "bio", "lv": 2, "topic": "ヘモグロビン", "q": "ヘモグロビンが肺で酸素と結合し、組織で酸素を放出するしくみを説明せよ。", "a": "ヘモグロビンは【酸素分圧】が高く二酸化炭素分圧が低い肺胞では酸素と結合しやすい。組織では酸素分圧が低く、【二酸化炭素分圧】が高いため、酸素と解離しやすくなる。この性質は【酸素解離曲線】で示され、効率よく組織に【酸素】を供給できる。"},
  {"id": "biox15", "s": "bio", "lv": 2, "topic": "跳躍伝導", "q": "有髄神経繊維では、無髄神経繊維より興奮が速く伝わる理由を説明せよ。", "a": "有髄神経繊維の軸索は、電気を通しにくい【髄鞘】で覆われており、髄鞘の切れ目である【ランビエ絞輪】でのみ活動電位が生じる。興奮が絞輪から絞輪へととびとびに伝わる【跳躍伝導】が起こるため、【伝導速度】が大きくなる。"},
  {"id": "biox16", "s": "bio", "lv": 2, "topic": "減数分裂と多様性", "q": "減数分裂によって、遺伝的に多様な配偶子が生じる理由を説明せよ。", "a": "減数分裂の第一分裂では、【相同染色体】が対合し、それぞれがどちらの極に移動するかがランダムに決まる（【独立】した分配）。また、対合した相同染色体の間で【乗換え】が起こり【遺伝子の組換え】が生じる。これらにより、多様な遺伝子の組み合わせをもつ配偶子ができる。"},
  {"id": "biox17", "s": "bio", "lv": 2, "topic": "フィードバック調節", "q": "甲状腺から分泌されるチロキシンの量が一定に保たれるしくみを説明せよ。", "a": "血液中の【チロキシン】濃度が上がると、それが間脳の視床下部や【脳下垂体前葉】に作用し、甲状腺刺激ホルモン放出ホルモンや【甲状腺刺激ホルモン】の分泌が抑えられ、チロキシンの分泌が減る。このように最終産物が前の段階を調節するしくみを【負のフィードバック】という。"},
  {"id": "biox18", "s": "bio", "lv": 2, "topic": "アレルギー", "q": "アレルギーはどのようなしくみで起こるか説明せよ。", "a": "本来は無害な花粉などの物質が【抗原（アレルゲン）】となって、免疫が過剰に反応することで起こる。【抗体】が結合した【マスト細胞（肥満細胞）】に再び抗原が結合すると、ヒスタミンなどが放出され、くしゃみや炎症などの症状が生じる。急激で全身性の重い反応を【アナフィラキシー】という。"},
  {"id": "biox19", "s": "bio", "lv": 2, "topic": "キーストーン種", "q": "キーストーン種とはどのような生物か。具体例をあげて説明せよ。", "a": "生態系の中で、個体数は少なくても【生物群集】のバランスを保つうえで大きな影響を与える生物。例えば岩礁で【ヒトデ】を除去すると、ヒトデに捕食されていたイガイが増えて他の生物を排除し、【種の多様性】が低下する。このような生物を【キーストーン種】という。"},
  {"id": "biox20", "s": "bio", "lv": 2, "topic": "光周性", "q": "短日植物の花芽形成と、夜の長さとの関係を説明せよ。", "a": "短日植物は、連続した暗期の長さが一定の【限界暗期】以上になると花芽を形成する。暗期の途中に短時間光を当てる【光中断】を行うと、連続した暗期が短くなり花芽を形成しない。このように、植物は【昼の長さ】ではなく連続した暗期の長さを感知している。この性質を【光周性】という。"},
  {"id": "biox21", "s": "bio", "lv": 3, "topic": "遺伝的浮動", "q": "小さな集団で遺伝的浮動の影響が大きくなる理由を説明せよ。", "a": "【遺伝的浮動】は、次世代に伝わる遺伝子が【偶然】によって選ばれることで【遺伝子頻度】が変化する現象である。集団が小さいと、偶然による変動の影響が相対的に大きくなり、ある遺伝子が失われたり【固定】されたりしやすい。【びん首効果】はその一例である。"},
  {"id": "biox22", "s": "bio", "lv": 3, "topic": "ラクトースオペロン", "q": "大腸菌がラクトースのあるときだけラクトース分解酵素を合成するしくみを説明せよ。", "a": "ラクトースがないときは、【リプレッサー】が【オペレーター】に結合し、RNAポリメラーゼの転写を妨げている。ラクトースがあると、その代謝産物がリプレッサーに結合してオペレーターから離れさせるため、【転写】が始まり分解酵素が合成される。このような遺伝子群を【オペロン】という。"},
  {"id": "biox23", "s": "bio", "lv": 3, "topic": "ATP合成酵素", "q": "ミトコンドリアの電子伝達系でATPが合成されるしくみを説明せよ。", "a": "電子伝達系で電子が受け渡される際のエネルギーで、H⁺が内膜の外側（膜間腔）へくみ出され、内膜の内外でH⁺の【濃度勾配】が生じる。H⁺がこの勾配にしたがって【ATP合成酵素】を通ってマトリックスへ戻るときにATPが合成される。このしくみを【化学浸透】といい、最終的に電子は【酸素】に受け渡されて水ができる。"},
  {"id": "biox24", "s": "bio", "lv": 3, "topic": "遺伝子組換え", "q": "大腸菌を用いてヒトのインスリンを生産する遺伝子組換えの手順を説明せよ。", "a": "ヒトのインスリン遺伝子と、【ベクター】となる大腸菌の【プラスミド】を同じ【制限酵素】で切断し、【DNAリガーゼ】で連結して組換えプラスミドをつくる。これを大腸菌に導入して増殖させると、大腸菌が遺伝子を発現し、インスリンが生産される。"},
  {"id": "biox25", "s": "bio", "lv": 3, "topic": "C4植物", "q": "トウモロコシなどのC4植物が、高温・乾燥の環境で光合成を効率よく行える理由を説明せよ。", "a": "C4植物は、二酸化炭素との親和性が高い【PEPカルボキシラーゼ】で葉肉細胞においてCO₂を【C4化合物】として固定し、【維管束鞘細胞】へ送ってそこでCO₂を濃縮する。そのため気孔を閉じ気味にしても、【カルビン回路】に十分なCO₂を供給でき、光合成を効率よく行える。"},
  {"id": "earthx1", "s": "earth", "lv": 1, "topic": "日本の地震", "q": "日本付近で大きな地震が多く発生する理由を、プレートの動きから説明せよ。", "a": "日本付近では、海洋プレートである太平洋プレートやフィリピン海プレートが、大陸プレートの下に【沈み込んで】いる。その境界にある【海溝】付近で大陸プレートがひきずり込まれてひずみがたまり、それが解放されると【海溝型地震】が起こる。また内陸の【活断層】でも地震が起こる。"},
  {"id": "earthx2", "s": "earth", "lv": 1, "topic": "火山の形とマグマ", "q": "火山の形がマグマの性質によって異なる理由を説明せよ。", "a": "二酸化ケイ素（SiO₂）の多いマグマは【粘性】が大きく流れにくいため、盛り上がった【溶岩ドーム】をつくり、爆発的な噴火をしやすい。SiO₂の少ない玄武岩質マグマは粘性が小さく流れやすいため、傾斜のゆるやかな【盾状火山】をつくる。"},
  {"id": "earthx3", "s": "earth", "lv": 1, "topic": "季節の変化", "q": "日本で夏が暑く冬が寒くなる理由を、地球の運動から説明せよ。", "a": "地球は【地軸】を公転面に垂直な方向から約23.4°傾けたまま【公転】している。そのため夏は太陽の【南中高度】が高く昼の時間が長くなり、地面が受け取る太陽エネルギーが多くなる。冬はその逆になるため寒くなる。"},
  {"id": "earthx4", "s": "earth", "lv": 1, "topic": "月の満ち欠け", "q": "月が約1か月の周期で満ち欠けして見える理由を説明せよ。", "a": "月は自ら光を出さず、【太陽】の光を反射して輝いている。月が地球のまわりを【公転】するにつれて、太陽・地球・月の【位置関係】が変わり、地球から見える月の光っている部分の形が変化するため、満ち欠けして見える。"},
  {"id": "earthx5", "s": "earth", "lv": 1, "topic": "示準化石", "q": "示準化石は地層の年代を知るのに役立つ。示準化石として適した生物の条件を説明せよ。", "a": "示準化石に適した生物は、ある【限られた期間】だけ栄え、【広い範囲】に分布し、個体数が多かった生物である。そのため、離れた地域の地層でも同じ化石を含めば同時代と判断でき、【地質年代】の決定や地層の【対比】に役立つ。"},
  {"id": "earthx6", "s": "earth", "lv": 1, "topic": "海陸風", "q": "海岸地方で、昼は海から陸へ、夜は陸から海へ風が吹く理由を説明せよ。", "a": "陸は海より【比熱】が小さく、温まりやすく冷めやすい。昼は陸が海より高温になって陸上に【上昇気流】が生じ気圧が低くなるため、海から陸へ【海風】が吹く。夜は陸が海より低温になるため、陸から海へ【陸風】が吹く。"},
  {"id": "earthx7", "s": "earth", "lv": 1, "topic": "温室効果", "q": "大気中の二酸化炭素が増えると、地球の気温が上がる理由を説明せよ。", "a": "地表は太陽光で暖められ、【赤外線】を宇宙へ放射する。二酸化炭素などの【温室効果ガス】はこの赤外線を吸収し、その一部を再び地表へ放射して地表を暖める。温室効果ガスが増えるとこの【温室効果】が強まり、【地球温暖化】が進む。"},
  {"id": "earthx8", "s": "earth", "lv": 1, "topic": "雲のでき方", "q": "上昇する空気の中で雲ができるしくみを説明せよ。", "a": "空気が上昇すると、上空ほど気圧が低いため【断熱膨張】して温度が下がる。温度が【露点】に達すると、空気中の水蒸気が細かいちりなどを核として【凝結】し、水滴や氷の粒となる。これが集まって【雲】となる。"},
  {"id": "earthx9", "s": "earth", "lv": 1, "topic": "初期微動", "q": "地震のとき、はじめに小さなゆれがあり、その後に大きなゆれが来る理由を説明せよ。", "a": "地震が発生すると、速さの異なる2種類の地震波が同時に出る。速い【P波】が先に到着して小さなゆれの【初期微動】を起こし、遅れて到着した【S波】が大きなゆれの【主要動】を起こす。震源から遠いほど両者の到着時刻の差である【初期微動継続時間】が長くなる。"},
  {"id": "earthx10", "s": "earth", "lv": 1, "topic": "台風の発達", "q": "台風が暖かい海上で発達する理由を説明せよ。", "a": "台風は熱帯の海上で発生する【熱帯低気圧】が発達したものである。暖かい海面から大量の【水蒸気】が供給され、それが上昇して凝結するときに放出される【潜熱】がエネルギー源となるため、海面水温の高い海上で発達する。"},
  {"id": "earthx11", "s": "earth", "lv": 2, "topic": "外核とS波", "q": "地震のS波が地球の中心部を通過しないことから、地球内部についてどのようなことがわかるか説明せよ。", "a": "S波は【横波】であり、固体中は伝わるが【液体】中は伝わらない。震央から角距離103°以遠でS波が観測されない【シャドーゾーン】があることから、地球内部に液体の層があることがわかる。これが鉄を主成分とする【外核】である。"},
  {"id": "earthx12", "s": "earth", "lv": 2, "topic": "ホットスポット", "q": "ハワイ諸島で、島の年代が北西に向かうほど古くなっている理由を説明せよ。", "a": "マントル深部からの【プルーム】が上昇してくる【ホットスポット】の位置はほぼ固定されている。その上を【太平洋プレート】が北西方向へ移動しているため、ホットスポット上でできた火山島がプレートとともに北西へ運ばれ、北西ほど古い島が並ぶ。"},
  {"id": "earthx13", "s": "earth", "lv": 2, "topic": "天気の移り変わり", "q": "日本付近では天気が西から東へ移り変わることが多い。その理由を説明せよ。", "a": "日本は中緯度に位置し、上空に強い【偏西風】が吹いている。春や秋に日本付近を通る【温帯低気圧】や【移動性高気圧】は、偏西風に流されて西から東へ移動するため、天気も【西から東】へ移り変わることが多い。"},
  {"id": "earthx14", "s": "earth", "lv": 2, "topic": "ハドレー循環", "q": "低緯度の大気の大循環であるハドレー循環のしくみを説明せよ。", "a": "赤道付近では強く暖められた空気が上昇し、上空を高緯度側へ移動する。緯度30°付近で下降して【亜熱帯高圧帯】をつくり、地表付近を赤道へ向かって戻る。この地表付近の流れが【転向力（コリオリの力）】で西向きにそれたものが【貿易風】である。この循環を【ハドレー循環】という。"},
  {"id": "earthx15", "s": "earth", "lv": 2, "topic": "深層循環", "q": "海洋の深層循環はどのようにして起こるか説明せよ。", "a": "北大西洋のグリーンランド沖や南極周辺では、海水が冷却され、海氷ができる際に塩分が排出されるため、【低温】で【高塩分】の密度の大きい海水ができる。これが深層へ【沈み込み】、ゆっくりと世界の海洋の深層をめぐる。この循環を【熱塩循環】ともいう。"},
  {"id": "earthx16", "s": "earth", "lv": 2, "topic": "太陽の黒点", "q": "太陽の表面に見られる黒点が、周囲より黒く見える理由を説明せよ。", "a": "黒点は、太陽の内部からの強い【磁場】が光球面に現れた部分で、磁場によって内部からの熱の【対流】による輸送が妨げられている。そのため周囲の光球（約5800K）より【温度】が約1500〜2000K低く、相対的に暗く見える。黒点の数が多い時期は太陽の【活動】が活発である。"},
  {"id": "earthx17", "s": "earth", "lv": 2, "topic": "主系列星", "q": "恒星の多くがHR図上の主系列に分布する理由を説明せよ。", "a": "恒星は一生の大部分の期間、中心部で【水素】が【ヘリウム】に変わる【核融合】反応によってエネルギーを生み出し、安定して輝いている。この段階の恒星を【主系列星】といい、恒星はその一生の大部分をこの段階で過ごすため、多くの恒星が主系列に分布する。"},
  {"id": "earthx18", "s": "earth", "lv": 2, "topic": "金星の見え方", "q": "金星が明け方か夕方にしか見えず、真夜中には見えない理由を説明せよ。", "a": "金星は地球より内側を公転する【内惑星】であるため、地球から見て太陽から一定の角度（【最大離角】約47°）以上は離れない。そのため太陽が沈んだ直後の西の空（【宵の明星】）か、日の出前の東の空（明けの明星）にしか見えない。"},
  {"id": "earthx19", "s": "earth", "lv": 2, "topic": "津波", "q": "海溝型の巨大地震で大きな津波が発生しやすい理由を説明せよ。", "a": "海溝型地震では、プレート境界の【逆断層】がずれ動き、沈み込むプレートにひきずり込まれていた陸側のプレートが跳ね上がる。これにより広い範囲で【海底】が急激に隆起・沈降し、その上の大量の海水が持ち上げられて【津波】となる。津波は【水深】が浅くなる海岸で波高が高くなる。"},
  {"id": "earthx20", "s": "earth", "lv": 2, "topic": "示相化石", "q": "示相化石とは何か。具体例をあげて説明せよ。", "a": "地層が堆積した当時の【環境】を推定するのに役立つ化石。生息環境が限られた生物が適している。例えば【サンゴ】の化石が見つかれば、その地層は暖かくきれいな浅い海で堆積したと推定できる。このような化石を【示相化石】という。"},
  {"id": "earthx21", "s": "earth", "lv": 3, "topic": "アイソスタシー", "q": "氷河が融けたスカンジナビア半島で、現在も土地が隆起し続けている理由を説明せよ。", "a": "地殻はマントルの上に浮かんでつり合っている（【アイソスタシー】）。氷期には厚い【氷床】の重みで地殻が沈み込んだが、氷床が融けて荷重が取り除かれたため、つり合いを回復しようとしてゆっくり【隆起】している。マントルは長い時間では【流動】するためである。"},
  {"id": "earthx22", "s": "earth", "lv": 3, "topic": "宇宙の膨張", "q": "遠い銀河ほど速く遠ざかっていることから、宇宙についてどのようなことがわかるか説明せよ。", "a": "遠い銀河のスペクトルは波長が長い方へずれる【赤方偏移】を示し、その後退速度は距離に比例する（【ハッブル・ルメートルの法則】）。これは宇宙全体が一様に【膨張】していることを示し、過去にさかのぼると宇宙は高温・高密度の状態から始まったという【ビッグバン】の考えを支持する。"},
  {"id": "earthx23", "s": "earth", "lv": 3, "topic": "縞状鉄鉱層", "q": "約25億〜20億年前に縞状鉄鉱層が大量に形成された理由を説明せよ。", "a": "【シアノバクテリア】の【光合成】によって海中に酸素が放出されると、それまで海水中に溶けていた【鉄イオン】が酸化されて酸化鉄となり、海底に沈殿して【縞状鉄鉱層】ができた。海中の鉄が消費された後、酸素は大気中に蓄積していった。"},
  {"id": "earthx24", "s": "earth", "lv": 3, "topic": "偏西風の蛇行", "q": "偏西風が大きく蛇行すると、異常気象が起こりやすくなる理由を説明せよ。", "a": "偏西風が大きく南北に【蛇行】すると、高緯度側の寒気が南下し、低緯度側の暖気が北上する。蛇行した状態が長く続く【ブロッキング】が起こると、高気圧や低気圧が同じ場所に停滞するため、【熱波】や【寒波】、大雨などの異常気象が長く続きやすくなる。"},
  {"id": "earthx25", "s": "earth", "lv": 3, "topic": "恒星の寿命", "q": "質量の大きい恒星ほど寿命が短い理由を説明せよ。", "a": "質量の大きい恒星は、自身の重力が大きいため中心部が高温・高圧となり、【核融合】反応がきわめて激しく進む。燃料となる【水素】の量は質量に比例して多いが、【光度】は質量の約3乗以上に比例して大きくなるため燃料を急速に消費し、【主系列星】の段階の寿命が短くなる。"}
];
